export default "   await manager.unsubscribe(flow_id, queue2)\\n\\n\\n# =============================================================================\\n# UNIT TESTS - PURE FUNCTIONS (NO DB, NO FIXTURES)\\n# =============================================================================\\n\\n\\nclass TestGetVertexIdsFromFlow:\\n    \\\"\\\"\\\"Unit tests for _get_vertex_ids_from_flow helper function.\\\"\\\"\\\"\\n\\n    def test_returns_empty_list_when_flow_data_is_none(self):\\n        \\\"\\\"\\\"Should return empty list when flow.data is None.\\\"\\\"\\\"\\n        from unittest.mock import Mock\\n\\n        from langflow.api.v1.endpoints import _get_vertex_ids_from_flow\\n\\n        flow = Mock()\\n        flow.data = None\\n\\n        result = _get_vertex_ids_from_flow(flow)\\n\\n        assert result == []\\n\\n    def test_returns_empty_list_when_nodes_is_empty(self):\\n        \\\"\\\"\\\"Should return empty list when nodes array is empty.\\\"\\\"\\\"\\n        from unittest.mock import Mock\\n\\n        from langflow.api.v1.endpoints import _get_vertex_ids_from_flow\\n\\n        flow = Mock()\\n        flow.data = {\\\"nodes\\\": []}\\n\\n        result = _get_vertex_ids_from_flow(flow)\\n\\n        assert result == []\\n\\n    def test_returns_empty_list_when_nodes_key_missing(self):\\n        \\\"\\\"\\\"Should return empty list when nodes key is missing.\\\"\\\"\\\"\\n        from unittest.mock import Mock\\n\\n        from langflow.api.v1.endpoints import _get_vertex_ids_from_flow\\n\\n        flow = Mock()\\n        flow.data = {\\\"other_key\\\": \\\"value\\\"}\\n\\n        result = _get_vertex_ids_from_flow(flow)\\n\\n        assert result == []\\n\\n    def test_extracts_vertex_ids_from_nodes(self):\\n        \\\"\\\"\\\"Should extract all vertex IDs from nodes.\\\"\\\"\\\"\\n        from unittest.mock import Mock\\n\\n        from langflow.api.v1.endpoints import _get_vertex_ids_from_flow\\n\\n        flow = Mock()\\n        flow.data = {\\n            \\\"nodes\\\": [\\n                {\\\"id\\\": \\\"vertex-1\\\", \\\"type\\\": \\\"ChatInput\\\"},\\n                {\\\"id\\\": \\\"vertex-2\\\", \\\"type\\\": \\\"ChatOutput\\\"},\\n                {\\\"id\\\": \\\"vertex-3\\\", \\\"type\\\": \\\"LLM\\\"},\\n            ]\\n        }\\n\\n        result = _get_vertex_ids_from_flow(flow)\\n\\n        assert result == [\\\"vertex-1\\\", \\\"vertex-2\\\", \\\"vertex-3\\\"]\\n\\n    def test_skips_nodes_without_id(self):\\n        \\\"\\\"\\\"Should skip nodes that don't have an id field.\\\"\\\"\\\"\\n        from unittest.mock import Mock\\n\\n        from langflow.api.v1.endpoints import _get_vertex_ids_from_flow\\n\\n        flow = Mock()\\n        flow.data = {\\n            \\\"nodes\\\": [\\n                {\\\"id\\\": \\\"vertex-1\\\", \\\"type\\\": \\\"ChatInput\\\"},\\n                {\\\"type\\\": \\\"NoIdNode\\\"},  # No id\\n                {\\\"id\\\": None, \\\"type\\\": \\\"NullId\\\"},  # None id\\n                {\\\"id\\\": \\\"vertex-2\\\", \\\"type\\\": \\\"ChatOutput\\\"},\\n            ]\\n        }\\n\\n        result = _get_vertex_ids_from_flow(flow)\\n\\n        assert result == [\\\"vertex-1\\\", \\\"vertex-2\\\"]\\n\\n\\n# =============================================================================\\n# UNIT TESTS - SIMPLE_RUN_FLOW_TASK (WITH MOCKS)\\n# =============================================================================\\n\\n\\nclass TestSimpleRunFlowTask:\\n    \\\"\\\"\\\"Unit tests for simple_run_flow_task function.\\\"\\\"\\\"\\n\\n    async def test_emits_vertices_sorted_event_when_emit_events_true(self):\\n        \\\"\\\"\\\"Should emit vertices_sorted event when emit_events=True and has listeners.\\\"\\\"\\\"\\n        from unittest.mock import AsyncMock, Mock, patch\\n\\n        from langflow.api.v1.endpoints import simple_run_flow_task\\n\\n        flow = Mock()\\n        flow.id = \\\"test-flow-id\\\"\\n        flow.data = {\\\"nodes\\\": [{\\\"id\\\": \\\"v1\\\"}, {\\\"id\\\": \\\"v2\\\"}]}\\n\\n        input_request = Mock()\\n\\n        with (\\n            patch(\\\"langflow.api.v1.endpoints.simple_run_flow\\\", new_callable=AsyncMock) as mock_run,\\n            patch(\\\"langflow.api.v1.endpoints.webhook_event_manager\\\") as mock_manager,\\n        ):\\n            mock_run.return_value = {\\\"result\\\": \\\"success\\\"}\\n            mock_manager.emit = AsyncMock()\\n\\n            await simple_run_flow_task(\\n                flow=flow,\\n                input_request=input_request,\\n                emit_events=True,\\n                flow_id=\\\"test-flow-id\\\",\\n                run_id=\\\"run-123\\\",\\n            )\\n\\n            # Should emit vertices_sorted\\n            mock_manager.emit.assert_any_call(\\n                \\\"test-flow-id\\\",\\n                \\\"vertices_sorted\\\",\\n                {\\\"ids\\\": [\\\"v1\\\", \\\"v2\\\"], \\\"to_run\\\": [\\\"v1\\\", \\\"v2\\\"], \\\"run_id\\\": \\\"run-123\\\"},\\n            )\\n\\n            # Should emit end with success\\n            mock_manager.emit.assert_any_call(\\n                \\\"test-flow-id\\\",\\n                \\\"end\\\",\\n                {\\\"run_id\\\": \\\"run-123\\\", \\\"success\\\": True},\\n            )\\n\\n    async def test_does_not_emit_events_when_emit_events_false(self):\\n        \\\"\\\"\\\"Should not emit events when emit_events=False.\\\"\\\"\\\"\\n        from unittest.mock import AsyncMock, Mock, patch\\n\\n        from langflow.api.v1.endpoints import simple_run_flow_task\\n\\n        flow = Mock()\\n        flow.id = \\\"test-flow-id\\\"\\n        flow.data = {\\\"nodes\\\": [{\\\"id\\\": \\\"v1\\\"}]}\\n\\n        input_request = Mock()\\n\\n        with (\\n            patch(\\\"langflow.api.v1.endpoints.simple_run_flow\\\", new_callable=AsyncMock) as mock_run,\\n            patch(\\\"langflow.api.v1.endpoints.webhook_event_manager\\\") as mock_manager,\\n        ):\\n            mock_run.return_value = {\\\"result\\\": \\\"success\\\"}\\n            mock_manager.emit = AsyncMock()\\n\\n            await simple_run_flow_task(\\n                flow=flow,\\n                input_request=input_request,\\n                emit_events=False,\\n                flow_id=\\\"test-flow-id\\\",\\n            )\\n\\n            # Should NOT emit any events\\n            mock_manager.emit.assert_not_called()\\n\\n    async def test_emits_error_event_on_exception(self):\\n        \\\"\\\"\\\"Should emit end event with error when exception occurs.\\\"\\\"\\\"\\n        from unittest.mock import AsyncMock, Mock, patch\\n\\n        from langflow.api.v1.endpoints import simple_run_flow_task\\n\\n        flow = Mock()\\n        flow.id = \\\"test-flow-id\\\"\\n        flow.data = {\\\"nodes\\\": [{\\\"id\\\": \\\"v1\\\"}]}\\n\\n        input_request = Mock()\\n\\n        with (\\n            patch(\\\"langflow.api.v1.endpoints.simple_run_flow\\\", new_callable=AsyncMock) as mock_run,\\n            patch(\\\"langflow.api.v1.endpoints.webhook_event_manager\\\") as mock_manager,\\n            patch(\\\"langflow.api.v1.endpoints.logger\\\") as mock_logger,\\n        ):\\n            mock_run.side_effect = Exception(\\\"Test error\\\")\\n            mock_manager.emit = AsyncMock()\\n            mock_logger.aexception = AsyncMock()\\n\\n            result = await simple_run_flow_task(\\n                flow=flow,\\n                input_request=input_request,\\n                emit_events=True,\\n                flow_id=\\\"test-flow-id\\\",\\n                run_id=\\\"run-456\\\",\\n            )\\n\\n            # Should return None on error\\n            assert result is None\\n\\n            # Should emit end with error\\n            mock_manager.emit.assert_called_with(\\n                \\\"test-flow-id\\\",\\n                \\\"end\\\",\\n                {\\\"run_id\\\": \\\"run-456\\\", \\\"success\\\": False, \\\"error\\\": \\\"Test error\\\"},\\n            )\\n\\n    async def test_logs_telemetry_on_success(self):\\n        \\\"\\\"\\\"Should log telemetry on successful execution.\\\"\\\"\\\"\\n        from unittest.mock import AsyncMock, Mock, patch\\n\\n        from langflow.api.v1.endpoints import simple_run_flow_task\\n\\n        flow = Mock()\\n        flow.id = \\\"test-flow-id\\\"\\n        flow.data = {\\\"nodes\\\": []}\\n\\n        input_request = Mock()\\n        telemetry_service = Mock()\\n        telemetry_service.log_package_run = AsyncMock()\\n\\n        with patch(\\\"langflow.api.v1.endpoints.simple_run_flow\\\", new_callable=AsyncMock) as mock_run:\\n            mock_run.return_value = {\\\"result\\\": \\\"success\\\"}\\n\\n            await simple_run_flow_task(\\n                flow=flow,\\n                input_request=input_request,\\n                telemetry_service=telemetry_service,\\n                start_time=0.0,\\n                run_id=\\\"run-789\\\",\\n            )\\n\\n            # Should log telemetry\\n            telemetry_service.log_package_run.assert_called_once()\\n            call_args = telemetry_service.log_package_run.call_args[0][0]\\n            assert call_args.run_is_webhook is True\\n            assert call_args.run_success is True\\n\\n\\n# =============================================================================\\n# UNIT TESTS - WEBHOOK_EVENTS_STREAM AUTHENTICATION (WITH MOCKS)\\n# =============================================================================\\n\\n\\nclass TestWebhookEventsStreamAuth:\\n    \\\"\\\"\\\"Tests for webhook_events_stream authentication.\\\"\\\"\\\"\\n\\n    async def test_raises_404_when_user_does_not_own_flow(self):\\n        \\\"\\\"\\\"Should raise 404 when authenticated user doesn't own the flow.\\\"\\\"\\\"\\n        from unittest.mock import Mock, patch\\n\\n        from fastapi import HTTPException\\n        from langflow.api.v1.endpoints import get_flow_for_sse_user\\n\\n        mock_user = Mock()\\n        mock_user.id = \\\"different-user-id\\\"\\n\\n        # Mock get_flow_by_id_or_endpoint_name to raise 404 as it would if user doesn't own it\\n        with patch(\\\"langflow.api.v1.endpoints.get_flow_by_id_or_endpoint_name\\\") as mock_get_flow:\\n            mock_get_flow.side_effect = HTTPException(status_code=404, detail=\\\"Flow identifier test-flow-id not found\\\")\\n\\n            with pytest.raises(HTTPException) as exc_info:\\n                await get_flow_for_sse_user(\\n                    flow_id_or_name=\\\"test-flow-id\\\",\\n                    user=mock_user,\\n                )\\n\\n        assert exc_info.value.status_code == 404\\n        assert \\\"Flow identifier test-flow-id not found\\\" in exc_info.value.detail\\n\\n    async def test_webhook_events_stream_cross_user_access_returns_404(\\n        self, client, added_webhook_test, user_two_api_key\\n    ):\\n        \\\"\\\"\\\"Regression test: cross-user access to /webhook-events/{id} returns 404, not 403.\\n\\n        This ensures no existence oracle is exposed.\\n        \\\"\\\"\\\"\\n        flow_id = added_webhook_test[\\\"id\\\"]\\n        endpoint = f\\\"api/v1/webhook-events/{flow_id}\\\"\\n\\n        # Clear cookies to ensure we don't use the identity from added_webhook_test/logged_in_headers\\n        client.cookies.clear()\\n\\n        # Access with User 2's API key\\n        response = await client.get(endpoint, params={\\\"x-api-key\\\": user_two_api_key})\\n\\n        # Should return 404 because the flow doesn't belong to User 2\\n        assert response.status_code == 404\\n        assert f\\\"Flow identifier {flow_id} not found\\\" in response.json()[\\\"detail\\\"]\\n\\n    async def test_webhook_events_stream_cross_user_endpoint_name_returns_404(\\n        self, client, added_webhook_test, user_two_api_key\\n    ):\\n        \\\"\\\"\\\"Regression test: cross-user access to SSE via endpoint_name returns 404.\\\"\\\"\\\"\\n        endpoint_name = added_webhook_test[\\\"endpoint_name\\\"]\\n        endpoint = f\\\"api/v1/webhook-events/{endpoint_name}\\\"\\n\\n        # Clear cookies to ensure we don't use the identity from added_webhook_test/logged_in_headers\\n        client.cookies.clear()\\n\\n        # Access with User 2's API key\\n        response = await client.get(endpoint, params={\\\"x-api-key\\\": user_two_api_key})\\n\\n        # Should return 404 because the flow doesn't belong to User 2\\n        assert response.status_code == 404\\n        assert f\\\"Flow identifier {endpoint_name} not found\\\" in response.json()[\\\"detail\\\"]\\n\\n    async def test_sse_route_calls_ensure_flow_permission_for_shared_flow(self):\\n        \\\"\\\"\\\"Regression: webhook_events_stream must enforce flow:read before subscribing.\\n\\n        The SSE dependency widens to share-aware lookup when an authz plugin is\\n        active, so a non-owner *could* resolve another user's flow.  The route\\n        guards against this by calling ``ensure_flow_permission`` before any\\n        event-bus subscription happens \u2014 without that, a non-owner with\\n        cross-user fetch enabled could exfiltrate webhook event payloads for\\n        another user's flow.\\n        \\\"\\\"\\\"\\n        from types import SimpleNamespace\\n        from unittest.mock import AsyncMock\\n        from uuid import uuid4\\n\\n        from fastapi import HTTPException\\n        from langflow.api.v1 import endpoints as endpoints_module\\n\\n        owner = SimpleNamespace(id=uuid4(), is_superuser=False)\\n        attacker = SimpleNamespace(id=uuid4(), is_superuser=False)\\n        flow = SimpleNamespace(\\n            id=uuid4(),\\n            name=\\\"shared-flow\\\",\\n            user_id=owner.id,\\n            workspace_id=None,\\n            folder_id=None,\\n        )\\n        auth = endpoints_module.SseAuth(user=attacker, flow=flow)\\n\\n        async def _deny(*_args, **_kwargs):\\n            raise HTTPException(status_code=403, detail=\\\"Permission denied\\\")\\n\\n        # Subscribe must NOT be reached when permission is denied \u2014 if the\\n        # route accidentally falls through to event_generator() and calls\\n        # subscribe(), this AsyncMock will fail the test.\\n        subscribe_mock = AsyncMock(side_effect=AssertionError(\\\"subscribe() must not be called when authz denies\\\"))\\n\\n        with (\\n            patch.object(endpoints_module, \\\"ensure_flow_permission\\\", side_effect=_deny),\\n            patch.object(endpoints_module.webhook_event_manager, \\\"subscribe\\\", subscribe_mock),\\n        ):\\n            request_stub = SimpleNamespace()\\n            with pytest.raises(HTTPException) as exc_info:\\n                # The deny raises before the session is touched; a mock satisfies\\n                # the transaction-release parameter added for #14445.\\n                await endpoints_module.webhook_events_stream(auth=auth, request=request_stub, session=AsyncMock())\\n\\n        assert exc_info.value.status_code == 403\\n        subscribe_mock.assert_not_awaited()\\n\\n    async def test_webhook_run_cross_user_uuid_returns_404(self, client, added_webhook_test, user_two_api_key):\\n        \\\"\\\"\\\"Regression test: cross-user access to run webhook via UUID returns 404.\\\"\\\"\\\"\\n        flow_id = added_webhook_test[\\\"id\\\"]\\n        endpoint = f\\\"api/v1/webhook/{flow_id}\\\"\\n\\n        # Clear cookies to ensure we don't use the identity from added_webhook_test/logged_in_headers\\n        client.cookies.clear()\\n\\n        # Access with User 2's API key\\n        response = await client.post(endpoint, json={\\\"test\\\": \\\"data\\\"}, params={\\\"x-api-key\\\": user_two_api_key})\\n\\n        # Should return 404 because the flow doesn't belong to User 2\\n        # If it returns 403, it's an existence oracle\\n        assert response.status_code == 404\\n        assert f\\\"Flow identifier {flow_id} not found\\\" in response.json()[\\\"detail\\\"]\\n\\n    async def test_webhook_run_cross_user_endpoint_name_returns_404(self, client, added_webhook_test, user_two_api_key):\\n        \\\"\\\"\\\"Regression test: cross-user access to run webhook via endpoint_name returns 404.\\\"\\\"\\\"\\n        endpoint_name = added_webhook_test[\\\"endpoint_name\\\"]\\n        endpoint = f\\\"api/v1/webhook/{endpoint_name}\\\"\\n\\n        # Clear cookies to ensure we don't use the identity from added_webhook_test/logged_in_headers\\n        client.cookies.clear()\\n\\n        # Access with User 2's API key\\n        response = await client.post(endpoint, json={\\\"test\\\": \\\"data\\\"}, params={\\\"x-api-key\\\": user_two_api_key})\\n\\n        # Should return 404 because the flow doesn't belong to User 2\\n        assert response.status_code == 404\\n        assert f\\\"Flow identifier {endpoint_name} not found\\\" in response.json()[\\\"detail\\\"]\\n\\n\\ndef _enable_serving_required(monkeypatch):\\n    \\\"\\\"\\\"Turn on the serving end-user feature with identity REQUIRED, on the live settings.\\\"\\\"\\\"\\n    from lfx.services.deps import get_settings_service\\n\\n    settings = get_settings_service().settings\\n    monkeypatch.setattr(settings, \\\"serving_end_user_header\\\", \\\"X-End-User-Id\\\")\\n    monkeypatch.setattr(settings, \\\"serving_trust_proxy_headers\\\", True)\\n    monkeypatch.setattr(settings, \\\"serving_end_user_required\\\", True)\\n\\n\\nasync def test_webhook_required_identity_absent_is_rejected_401(\\n    client, added_webhook_test, created_api_key, monkeypatch\\n):\\n    \\\"\\\"\\\"I3: a webhook with no identity is a SYNCHRONOUS 401 when identity is required.\\n\\n    The run executes in a fire-and-forget task that can't surface an error, so the gate must fire in\\n    the endpoint before scheduling \u2014 otherwise a required-but-absent identity would 202 and be\\n    silently dropped.\\n    \\\"\\\"\\\"\\n    _enable_serving_required(monkeypatch)\\n    endpoint = f\\\"api/v1/webhook/{added_webhook_test['endpoint_name']}\\\"\\n    resp = await client.post(endpoint, headers={\\\"x-api-key\\\": created_api_key.api_key}, json={\\\"k\\\": \\\"v\\\"})\\n    assert resp.status_code == 401, resp.text\\n    assert resp.json()[\\\"detail\\\"][\\\"code\\\"] == \\\"END_USER_IDENTITY_REQUIRED\\\"\\n\\n\\nasync def test_webhook_required_identity_present_is_accepted(client, added_webhook_test, created_api_key, monkeypatch):\\n    # With the header present the gate passes and the run is scheduled as usual (202).\\n    _enable_serving_required(monkeypatch)\\n    endpoint = f\\\"api/v1/webhook/{added_webhook_test['endpoint_name']}\\\"\\n    resp = await client.post(\\n        endpoint,\\n        headers={\\\"x-api-key\\\": created_api_key.api_key, \\\"X-End-User-Id\\\": \\\"alice\\\"},\\n        json={\\\"k\\\": \\\"v\\\"},\\n    )\\n    assert resp.status_code == 202, resp.text\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/test_webhook_sse_regression.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"0d8e317c7635fd0196edb79b533d74b3f56c53f1d6ddb13e4455f58deb85482e\",\"content\":\"\\\"\\\"\\\"Regression test for webhook SSE real-time event delivery.\\n\\nBug: After POST /api/v1/webhook/{flow_id}, the UI's Inspect Output panel never shows\\nthe Webhook build because the SSE endpoint `/api/v1/webhook-events/{flow_id}` was\\nreturning 403 to the frontend subscriber. As a result the frontend `flowPool` stayed\\nempty and the Inspect Output panel showed \\\"Please build the component first\\\".\\n\\nRoot cause: `get_current_user_for_sse` takes `db: AsyncSession = Depends(...)` as a\\ndefault parameter \u2014 it is supposed to be invoked as a FastAPI dependency.\\n`webhook_events_stream` was calling it as a plain function\\n(`user = await get_current_user_for_sse(request)`), so the `db` argument was the\\nunresolved `Depends(...)` object instead of an `AsyncSession`. Every auth attempt then\\nblew up inside the auth service, was wrapped as `InvalidCredentialsError`, and the SSE\\nendpoint raised 403 for every request.\\n\\nThe regression was introduced in PR #11654 (Pluggable AuthService) when\\n`get_current_user_for_sse` was refactored from using `async with session_scope() as db`\\ninternally to receiving `db` via FastAPI `Depends(...)`.\\n\\nFix: make `webhook_events_stream` resolve `get_current_user_for_sse` through FastAPI\\ndependency injection so the `db` session is properly provided.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport asyncio\\n\\n\\nasync def _assert_sse_not_forbidden(client, url: str) -> None:\\n    \\\"\\\"\\\"Send a GET with a tight timeout and assert the endpoint does not return 403.\\n\\n    SSE responses are long-lived, so we can't read the body; instead:\\n      * 403 response \u2192 regression is present (fails fast, before the timeout)\\n      * TimeoutError \u2192 the SSE stream opened (200) and is idle waiting for events\\n    \\\"\\\"\\\"\\n    try:\\n        response = await asyncio.wait_for(client.get(url), timeout=3.0)\\n    except asyncio.TimeoutError:\\n        return\\n\\n    assert response.status_code != 403, (\\n        f\\\"SSE endpoint returned 403. Regression: get_current_user_for_sse was \\\"\\n        \\\"called directly instead of via FastAPI DI, so its `db` parameter was \\\"\\n        f\\\"a Depends(...) object. Body: {response.text}\\\"\\n    )\\n\\n\\nasync def test_should_not_return_403_when_accessing_webhook_sse_endpoint_with_valid_api_key(\\n    client,\\n    added_webhook_test,\\n    created_api_key,\\n):\\n    \\\"\\\"\\\"Direct reproduction: SSE must accept `x-api-key` query param.\\\"\\\"\\\"\\n    flow_id = added_webhook_test[\\\"id\\\"]\\n    sse_url = f\\\"api/v1/webhook-events/{flow_id}?x-api-key={created_api_key.api_key}\\\"\\n\\n    await _assert_sse_not_forbidden(client, sse_url)\\n\\n\\nasync def test_should_not_return_403_when_accessing_webhook_sse_endpoint_with_valid_cookie(\\n    client,\\n    added_webhook_test,\\n    active_user,\\n):\\n    \\\"\\\"\\\"SSE must accept `access_token_lf` cookie \u2014 the real path used by the browser.\\n\\n    The frontend's EventSource relies on cookies (not headers or query params) for\\n    authentication. This test mirrors that exact flow to make sure the fix holds for\\n    the real end-user scenario.\\n    \\\"\\\"\\\"\\n    login_response = await client.post(\\n        \\\"api/v1/login\\\",\\n        data={\\\"username\\\": active_user.username, \\\"password\\\": \\\"testpassword\\\"},\\n    )\\n    assert login_response.status_code == 200\\n    # httpx AsyncClient automatically persists Set-Cookie headers into client.cookies,\\n    # so subsequent requests will carry access_token_lf.\\n    assert \\\"access_token_lf\\\" in client.cookies\\n\\n    flow_id = added_webhook_test[\\\"id\\\"]\\n    sse_url = f\\\"api/v1/webhook-events/{flow_id}\\\"\\n\\n    await _assert_sse_not_forbidden(client, sse_url)\\n\\n\\nasync def test_should_not_return_403_on_sse_endpoint_when_webhook_auth_enable_is_true(\\n    client,\\n    added_webhook_test,\\n    created_api_key,\\n):\\n    \\\"\\\"\\\"SSE auth is independent of LANGFLOW_WEBHOOK_AUTH_ENABLE.\\n\\n    `WEBHOOK_AUTH_ENABLE` controls the POST /webhook endpoint (allow/deny public\\n    execution). It must not interfere with SSE subscription: the SSE endpoint always\\n    requires a logged-in user who owns the flow, regardless of the flag.\\n    \\\"\\\"\\\"\\n    from langflow.services.deps import get_settings_service\\n\\n    settings_service = get_settings_service()\\n    original = settings_service.auth_settings.WEBHOOK_AUTH_ENABLE\\n\\n    try:\\n        settings_service.auth_settings.WEBHOOK_AUTH_ENABLE = True\\n\\n        flow_id = added_webhook_test[\\\"id\\\"]\\n        sse_url = f\\\"api/v1/webhook-events/{flow_id}?x-api-key={created_api_key.api_key}\\\"\\n\\n        await _assert_sse_not_forbidden(client, sse_url)\\n    finally:\\n        settings_service.auth_settings.WEBHOOK_AUTH_ENABLE = original\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/test_windows_postgres_helper.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"abf4abcdcc12d700bd46fc6e4b83e85d8b1daccbb49cfe7cd55a38533980bf5a\",\"content\":\"\\\"\\\"\\\"Unit tests for Windows + PostgreSQL event loop configuration.\\n\\nThese tests ensure the fix works correctly across all platforms:\\n- Windows with PostgreSQL (applies fix)\\n- Windows with SQLite (no fix)\\n- Linux (no fix)\\n- macOS (no fix)\\n- Docker (no fix)\\n\\\"\\\"\\\"\\n\\nimport asyncio\\nimport os\\nfrom unittest.mock import MagicMock, patch\\n\\nimport pytest\\nfrom langflow.helpers.windows_postgres_helper import (\\n    LANGFLOW_DATABASE_URL,\\n    POSTGRESQL_PREFIXES,\\n    configure_windows_postgres_event_loop,\\n)\\n\\n# Mock class for asyncio.WindowsSelectorEventLoopPolicy (only exists on Windows)\\nMockWindowsSelectorPolicy = type(\\\"WindowsSelectorEventLoopPolicy\\\", (), {})\\n\\n\\nclass TestWindowsPostgresHelper:\\n    \\\"\\\"\\\"Test Windows + PostgreSQL helper functions.\\\"\\\"\\\"\\n\\n    @pytest.fixture(autouse=True)\\n    def reset_event_loop_policy(self):\\n        \\\"\\\"\\\"Reset event loop policy before each test.\\\"\\\"\\\"\\n        original_policy = asyncio.get_event_loop_policy()\\n        yield\\n        asyncio.set_event_loop_policy(original_policy)\\n\\n    def test_constants_defined(self):\\n        \\\"\\\"\\\"Test that required constants are properly defined.\\\"\\\"\\\"\\n        assert LANGFLOW_DATABASE_URL == \\\"LANGFLOW_DATABASE_URL\\\"\\n        assert POSTGRESQL_PREFIXES == (\\\"postgresql\\\", \\\"postgres\\\")\\n\\n    @patch(\\\"platform.system\\\")\\n    @patch.dict(os.environ, {}, clear=True)\\n    def test_non_windows_returns_false(self, mock_platform):\\n        \\\"\\\"\\\"Test that non-Windows systems return False and don't change event loop.\\\"\\\"\\\"\\n        for system in [\\\"Linux\\\", \\\"Darwin\\\", \\\"FreeBSD\\\"]:\\n            mock_platform.return_value = system\\n            os.environ[LANGFLOW_DATABASE_URL] = \\\"postgresql://user:pass@localhost/db\\\"\\n\\n            result = configure_windows_postgres_event_loop()\\n\\n            assert result is False\\n\\n    @patch(\\\"platform.system\\\")\\n    @patch.dict(os.environ, {}, clear=True)\\n    def test_windows_without_database_url_returns_false(self, mock_platform):\\n        \\\"\\\"\\\"Test Windows without DATABASE_URL returns False.\\\"\\\"\\\"\\n        mock_platform.return_value = \\\"Windows\\\"\\n\\n        result = configure_windows_postgres_event_loop()\\n\\n        assert result is False\\n\\n    @patch(\\\"platform.system\\\")\\n    @patch.dict(os.environ, {\\\"LANGFLOW_DATABASE_URL\\\": \\\"sqlite:///test.db\\\"}, clear=True)\\n    def test_windows_with_sqlite_returns_false(self, mock_platform):\\n        \\\"\\\"\\\"Test Windows with SQLite returns False and doesn't change event loop.\\\"\\\"\\\"\\n        mock_platform.return_value = \\\"Windows\\\"\\n\\n        result = configure_windows_postgres_event_loop()\\n\\n        assert result is False\\n\\n    @patch.object(asyncio, \\\"WindowsSelectorEventLoopPolicy\\\", MockWindowsSelectorPolicy, create=True)\\n    @patch(\\\"platform.system\\\")\\n    @patch.dict(os.environ, {\\\"LANGFLOW_DATABASE_URL\\\": \\\"postgresql://user:pass@localhost/db\\\"}, clear=True)\\n    @patch(\\\"asyncio.get_event_loop_policy\\\")\\n    @patch(\\\"asyncio.set_event_loop_policy\\\")\\n    def test_windows_with_postgresql_sets_policy(self, mock_set_policy, mock_get_policy, mock_platform):\\n        \\\"\\\"\\\"Test Windows with PostgreSQL sets WindowsSelectorEventLoopPolicy.\\\"\\\"\\\"\\n        mock_platform.return_value = \\\"Windows\\\"\\n        mock_policy = MagicMock()\\n        mock_get_policy.return_value = mock_policy\\n\\n        result = configure_windows_postgres_event_loop()\\n\\n        assert result is True\\n        mock_set_policy.assert_called_once()\\n        args = mock_set_policy.call_args[0]\\n        assert len(args) == 1\\n        assert \\\"WindowsSelectorEventLoopPolicy\\\" in str(args[0].__class__)\\n\\n    @patch.object(asyncio, \\\"WindowsSelectorEventLoopPolicy\\\", MockWindowsSelectorPolicy, create=True)\\n    @patch(\\\"platform.system\\\")\\n    @patch.dict(os.environ, {\\\"LANGFLOW_DATABASE_URL\\\": \\\"postgres://user:pass@localhost/db\\\"}, clear=True)\\n    @patch(\\\"asyncio.get_event_loop_policy\\\")\\n    @patch(\\\"asyncio.set_event_loop_policy\\\")\\n    def test_windows_with_postgres_protocol_sets_policy(self, mock_set_policy, mock_get_policy, mock_platform):\\n        \\\"\\\"\\\"Test Windows with 'postgres://' (deprecated) protocol also works.\\\"\\\"\\\"\\n        mock_platform.return_value = \\\"Windows\\\"\\n        mock_policy = MagicMock()\\n        mock_get_policy.return_value = mock_policy\\n\\n        result = configure_windows_postgres_event_loop()\\n\\n        assert result is True\\n        mock_set_policy.assert_called_once()\\n\\n    @patch.object(asyncio, \\\"WindowsSelectorEventLoopPolicy\\\", MockWindowsSelectorPolicy, create=True)\\n    @patch(\\\"platform.system\\\")\\n    @patch.dict(os.environ, {\\\"LANGFLOW_DATABASE_URL\\\": \\\"postgresql://user:pass@localhost/db\\\"}, clear=True)\\n    @patch(\\\"asyncio.get_event_loop_policy\\\")\\n    @patch(\\\"asyncio.set_event_loop_policy\\\")\\n    def test_windows_with_selector_already_set_returns_false(self, mock_set_policy, mock_get_policy, mock_platform):\\n        \\\"\\\"\\\"Test that if WindowsSelectorEventLoopPolicy is already set, returns False.\\\"\\\"\\\"\\n        mock_platform.return_value = \\\"Windows\\\"\\n        mock_policy = MagicMock(spec=MockWindowsSelectorPolicy)\\n        mock_get_policy.return_value = mock_policy\\n\\n        result = configure_windows_postgres_event_loop()\\n\\n        assert result is False\\n        mock_set_policy.assert_not_called()\\n\\n    @patch.object(asyncio, \\\"WindowsSelectorEventLoopPolicy\\\", MockWindowsSelectorPolicy, create=True)\\n    @patch(\\\"platform.system\\\")\\n    @patch.dict(os.environ, {\\\"LANGFLOW_DATABASE_URL\\\": \\\"postgresql://user:pass@localhost/db\\\"}, clear=True)\\n    @patch(\\\"asyncio.get_event_loop_policy\\\")\\n    @patch(\\\"asyncio.set_event_loop_policy\\\")\\n    @patch(\\\"langflow.helpers.windows_postgres_helper.logger\\\")\\n    def test_logging_includes_source_when_provided(self, mock_logger, mock_set_policy, mock_get_policy, mock_platform):  # noqa: ARG002\\n        \\\"\\\"\\\"Test that source is included in log context when provided.\\\"\\\"\\\"\\n        mock_platform.return_value = \\\"Windows\\\"\\n        mock_policy = MagicMock()\\n        mock_get_policy.return_value = mock_policy\\n\\n        result = configure_windows_postgres_event_loop(source=\\\"test_source\\\")\\n\\n        assert result is True\\n        mock_logger.debug.assert_called_once_with(\\n            \\\"Windows PostgreSQL event loop configured\\\",\\n            extra={\\n                \\\"event_loop\\\": \\\"WindowsSelectorEventLoop\\\",\\n                \\\"reason\\\": \\\"psycopg_compatibility\\\",\\n                \\\"source\\\": \\\"test_source\\\",\\n            },\\n        )\\n\\n    @patch(\\\"platform.system\\\")\\n    @patch.dict(os.environ, {\\\"LANGFLOW_DATABASE_URL\\\": \\\"mysql://user:pass@localhost/db\\\"}, clear=True)\\n    def test_windows_with_other_database_returns_false(self, mock_platform):\\n        \\\"\\\"\\\"Test Windows with non-PostgreSQL database returns False.\\\"\\\"\\\"\\n        mock_platform.return_value = \\\"Windows\\\"\\n\\n        result = configure_windows_postgres_event_loop()\\n\\n        assert result is False\\n\\n    @patch(\\\"platform.system\\\")\\n    def test_docker_environment_not_affected(self, mock_platform):\\n        \\\"\\\"\\\"Test that Docker environments (typically Linux) are not affected.\\\"\\\"\\\"\\n        mock_platform.return_value = \\\"Linux\\\"\\n        os.environ[LANGFLOW_DATABASE_URL] = \\\"postgresql://user:pass@postgres:5432/langflow\\\"\\n        os.environ[\\\"DOCKER_CONTAINER\\\"] = \\\"true\\\"\\n\\n        original_policy = asyncio.get_event_loop_policy()\\n        result = configure_windows_postgres_event_loop()\\n\\n        assert result is False\\n        assert asyncio.get_event_loop_policy() is original_policy\\n\\n    @pytest.mark.parametrize(\\n        \\\"db_url\\\",\\n        [\\n            \\\"postgresql://localhost/test\\\",\\n            \\\"postgresql+psycopg://localhost/test\\\",\\n            \\\"postgresql+asyncpg://localhost/test\\\",\\n            \\\"postgres://localhost/test\\\",\\n        ],\\n    )\\n    @patch.object(asyncio, \\\"WindowsSelectorEventLoopPolicy\\\", MockWindowsSelectorPolicy, create=True)\\n    @patch(\\\"platform.system\\\")\\n    @patch(\\\"asyncio.get_event_loop_policy\\\")\\n    @patch(\\\"asyncio.set_event_loop_policy\\\")\\n    def test_various_postgresql_urls_handled(self, mock_set_policy, mock_get_policy, mock_platform, db_url):\\n        \\\"\\\"\\\"Test that various PostgreSQL URL formats are handled correctly.\\\"\\\"\\\"\\n        mock_platform.return_value = \\\"Windows\\\"\\n        mock_policy = MagicMock()\\n        mock_get_policy.return_value = mock_policy\\n\\n        with patch.dict(os.environ, {LANGFLOW_DATABASE_URL: db_url}, clear=True):\\n            result = configure_windows_postgres_event_loop()\\n\\n        assert result is True\\n        mock_set_policy.assert_called_once()\\n\\n    @patch(\\\"platform.system\\\")\\n    @patch.dict(os.environ, {\\\"LANGFLOW_DATABASE_URL\\\": \\\"postgresql://user:pass@localhost/db\\\"}, clear=True)\\n    def test_windows_without_policy_class_returns_false(self, mock_platform):\\n        \\\"\\\"\\\"Test that if WindowsSelectorEventLoopPolicy class is unavailable, returns False.\\\"\\\"\\\"\\n        mock_platform.return_value = \\\"Windows\\\"\\n\\n        with patch.object(asyncio, \\\"WindowsSelectorEventLoopPolicy\\\", None, create=True):\\n            result = configure_windows_postgres_event_loop()\\n\\n        assert result is False\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/utils/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/utils/mcp.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"7c73cbacd37efdff03a3f0d1fae95f986a64852b588c95139986447ebe3f9179\",\"content\":\"from __future__ import annotations\\n\\nfrom contextlib import asynccontextmanager\\n\\nfrom langflow.api.v1.mcp_projects import (\\n    project_mcp_servers,\\n    start_project_task_group,\\n    stop_project_task_group,\\n)\\n\\n\\n@asynccontextmanager\\nasync def project_session_manager_lifespan():\\n    \\\"\\\"\\\"Test helper to ensure project session managers start and stop cleanly.\\\"\\\"\\\"\\n    await start_project_task_group()\\n    try:\\n        yield\\n    finally:\\n        await stop_project_task_group()\\n        project_mcp_servers.clear()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/utils/test_async_helpers.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"eb32afec37ad634d2e67a1e59ef8f3174edb9c6a46d116c5f07e25b8b0d780a3\",\"content\":\"from unittest.mock import Mock, patch\\n\\nimport pytest\\nfrom lfx.utils.async_helpers import run_until_complete, timeout_context\\n\\n\\nclass TestTimeoutContext:\\n    \\\"\\\"\\\"Test cases for timeout_context function.\\\"\\\"\\\"\\n\\n    def test_timeout_context_exists(self):\\n        \\\"\\\"\\\"Test that timeout_context function exists and is callable.\\\"\\\"\\\"\\n        # Check if timeout_context is callable\\n        assert callable(timeout_context)\\n\\n    def test_timeout_context_is_async_context_manager(self):\\n        \\\"\\\"\\\"Test that timeout_context returns an async context manager.\\\"\\\"\\\"\\n        ctx_manager = timeout_context(1.0)\\n        # Check it has async context manager methods\\n        assert hasattr(ctx_manager, \\\"__aenter__\\\")\\n        assert hasattr(ctx_manager, \\\"__aexit__\\\")\\n        assert callable(ctx_manager.__aenter__)\\n        assert callable(ctx_manager.__aexit__)\\n\\n\\nclass TestRunUntilComplete:\\n    \\\"\\\"\\\"Test cases for run_until_complete function.\\\"\\\"\\\"\\n\\n    def test_run_until_complete_basic(self):\\n        \\\"\\\"\\\"Test basic functionality of run_until_complete.\\\"\\\"\\\"\\n\\n        async def simple_coro():\\n            return 42\\n\\n        result = run_until_complete(simple_coro())\\n        assert result == 42\\n\\n    def test_run_until_complete_with_exception(self):\\n        \\\"\\\"\\\"Test run_until_complete with exception.\\\"\\\"\\\"\\n\\n        async def failing_coro():\\n            msg = \\\"Test error\\\"\\n            raise ValueError(msg)\\n\\n        with pytest.raises(ValueError, match=\\\"Test error\\\"):\\n            run_until_complete(failing_coro())\\n\\n    def test_run_until_complete_different_return_types(self):\\n        \\\"\\\"\\\"Test run_until_complete with different return types.\\\"\\\"\\\"\\n        test_cases = [\\n            (42, int),\\n            (\\\"hello\\\", str),\\n            ([1, 2, 3], list),\\n            ({\\\"key\\\": \\\"value\\\"}, dict),\\n            (None, type(None)),\\n        ]\\n\\n        for expected_value, expected_type in test_cases:\\n\\n            async def typed_coro(val=expected_value):\\n                return val\\n\\n            result = run_until_complete(typed_coro())\\n            assert result == expected_value\\n            assert isinstance(result, expected_type)\\n\\n    @patch(\\\"asyncio.get_running_loop\\\")\\n    def test_run_until_complete_no_running_loop(self, mock_get_running_loop):\\n        \\\"\\\"\\\"Test run_until_complete when no event loop is running.\\\"\\\"\\\"\\n        # Mock no running loop (raises RuntimeError)\\n        mock_get_running_loop.side_effect = RuntimeError(\\\"No running event loop\\\")\\n\\n        async def simple_coro():\\n            return \\\"no_loop\\\"\\n\\n        with patch(\\\"asyncio.run\\\") as mock_run:\\n            mock_run.return_value = \\\"no_loop\\\"\\n\\n            coro = simple_coro()\\n            try:\\n                result = run_until_complete(coro)\\n            finally:\\n                # Close the coroutine to avoid \\\"coroutine was never awaited\\\" warning\\n                # since the mocked asyncio.run doesn't actually run it\\n                coro.close()\\n\\n            mock_run.assert_called_once()\\n            assert result == \\\"no_loop\\\"\\n\\n    @patch(\\\"asyncio.get_running_loop\\\")\\n    @patch(\\\"concurrent.futures.ThreadPoolExecutor\\\")\\n    def test_run_until_complete_with_running_loop_path(self, mock_executor_class, mock_get_running_loop):\\n        \\\"\\\"\\\"Test run_until_complete when event loop is already running.\\\"\\\"\\\"\\n        # Mock that there is a running loop\\n        mock_get_running_loop.return_value = Mock()\\n\\n        # Mock the ThreadPoolExecutor and future\\n        mock_executor = Mock()\\n        mock_future = Mock()\\n        mock_future.result.return_value = \\\"thread_result\\\"\\n        mock_executor.submit.return_value = mock_future\\n        mock_executor_class.return_value.__enter__.return_value = mock_executor\\n\\n        async def simple_coro():\\n            return \\\"thread_result\\\"\\n\\n        coro = simple_coro()\\n        try:\\n            result = run_until_complete(coro)\\n        finally:\\n            # Close the coroutine to avoid \\\"coroutine was never awaited\\\" warning\\n            # since the mocked executor doesn't actually run it\\n            coro.close()\\n\\n        # Verify ThreadPoolExecutor was used\\n        mock_executor_class.assert_called_once()\\n        mock_executor.submit.assert_called_once()\\n        assert result == \\\"thread_result\\\"\\n\\n    @patch(\\\"asyncio.get_running_loop\\\")\\n    @patch(\\\"concurrent.futures.ThreadPoolExecutor\\\")\\n    def test_run_until_complete_thread_pool_exception(self, mock_executor_class, mock_get_running_loop):\\n        \\\"\\\"\\\"Test run_until_complete handles thread pool exceptions.\\\"\\\"\\\"\\n        mock_get_running_loop.return_value = Mock()\\n\\n        async def failing_coro():\\n            msg = \\\"Thread pool test error\\\"\\n            raise ValueError(msg)\\n\\n        # Mock executor to raise exception\\n        mock_executor = Mock()\\n        mock_future = Mock()\\n        mock_future.result.side_effect = ValueError(\\\"Thread pool test error\\\")\\n        mock_executor.submit.return_value = mock_future\\n        mock_executor_class.return_value.__enter__.return_value = mock_executor\\n\\n        coro = failing_coro()\\n        try:\\n            with pytest.raises(ValueError, match=\\\"Thread pool test error\\\"):\\n                run_until_complete(coro)\\n        finally:\\n            # Close the coroutine to avoid \\\"coroutine was never awaited\\\" warning\\n            # since the mocked executor doesn't actually run it\\n            coro.close()\\n\\n    @patch(\\\"asyncio.get_running_loop\\\")\\n    @patch(\\\"concurrent.futures.ThreadPoolExecutor\\\")\\n    @patch(\\\"asyncio.new_event_loop\\\")\\n    def test_run_until_complete_new_loop_cleanup(self, mock_new_loop, mock_executor_class, mock_get_running_loop):\\n        \\\"\\\"\\\"Test that new event loop is properly cleaned up.\\\"\\\"\\\"\\n        mock_get_running_loop.return_value = Mock()\\n        # Event loop setup for thread execution\\n\\n        mock_loop_instance = Mock()\\n        mock_loop_instance.run_until_complete.return_value = \\\"cleanup_test\\\"\\n        mock_new_loop.return_value = mock_loop_instance\\n\\n        mock_executor = Mock()\\n        mock_future = Mock()\\n        mock_future.result.return_value = \\\"cleanup_test\\\"\\n        mock_executor.submit.return_value = mock_future\\n        mock_executor_class.return_value.__enter__.return_value = mock_executor\\n\\n        async def simple_coro():\\n            return \\\"cleanup_test\\\"\\n\\n        coro = simple_coro()\\n        try:\\n            result = run_until_complete(coro)\\n        finally:\\n            # Close the coroutine to avoid \\\"coroutine was never awaited\\\" warning\\n            # since the mocked executor doesn't actually run it\\n            coro.close()\\n\\n        # Verify the loop operations happened in the thread\\n        assert result == \\\"cleanup_test\\\"\\n        mock_executor.submit.assert_called_once()\\n\\n    @patch(\\\"asyncio.get_running_loop\\\")\\n    @patch(\\\"concurrent.futures.ThreadPoolExecutor\\\")\\n    @patch(\\\"asyncio.new_event_loop\\\")\\n    def test_run_until_complete_new_loop_exception_cleanup(\\n        self, mock_new_loop, mock_executor_class, mock_get_running_loop\\n    ):\\n        \\\"\\\"\\\"Test that event loop is cleaned up even when exception occurs.\\\"\\\"\\\"\\n        mock_get_running_loop.return_value = Mock()\\n        # Event loop setup for thread execution\\n\\n        async def failing_coro():\\n            msg = \\\"Loop exception test\\\"\\n            raise RuntimeError(msg)\\n\\n        mock_loop_instance = Mock()\\n        mock_loop_instance.run_until_complete.side_effect = RuntimeError(\\\"Loop exception test\\\")\\n        mock_new_loop.return_value = mock_loop_instance\\n\\n        mock_executor = Mock()\\n        mock_future = Mock()\\n        mock_future.result.side_effect = RuntimeError(\\\"Loop exception test\\\")\\n        mock_executor.submit.return_value = mock_future\\n        mock_executor_class.return_value.__enter__.return_value = mock_executor\\n\\n        coro = failing_coro()\\n        try:\\n            with pytest.raises(RuntimeError, match=\\\"Loop exception test\\\"):\\n                run_until_complete(coro)\\n        finally:\\n            # Close the coroutine to avoid \\\"coroutine was never awaited\\\" warning\\n            # since the mocked executor doesn't actually run it\\n            coro.close()\\n\\n        # Verify executor was still called\\n        mock_executor.submit.assert_called_once()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/utils/test_component_utils.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"77d4343ea47dd49afaac0edd2d132e3bd2017d5b5435c1b0324802553ff4a68b\",\"content\":\"from unittest.mock import Mock\\n\\nfrom langflow.schema.dotdict import dotdict\\nfrom langflow.utils.component_utils import (\\n    DEFAULT_FIELDS,\\n    add_fields,\\n    delete_fields,\\n    get_fields,\\n    merge_build_configs,\\n    set_current_fields,\\n    set_field_advanced,\\n    set_field_display,\\n    set_multiple_field_advanced,\\n    set_multiple_field_display,\\n    update_fields,\\n    update_input_types,\\n)\\n\\n\\nclass TestUpdateFields:\\n    \\\"\\\"\\\"Test cases for update_fields function.\\\"\\\"\\\"\\n\\n    def test_update_existing_fields(self):\\n        \\\"\\\"\\\"Test updating existing fields in build_config.\\\"\\\"\\\"\\n        build_config = dotdict({\\\"field1\\\": \\\"old_value\\\", \\\"field2\\\": \\\"old_value2\\\"})\\n        fields = {\\\"field1\\\": \\\"new_value\\\", \\\"field2\\\": \\\"new_value2\\\"}\\n\\n        result = update_fields(build_config, fields)\\n\\n        assert result[\\\"field1\\\"] == \\\"new_value\\\"\\n        assert result[\\\"field2\\\"] == \\\"new_value2\\\"\\n\\n    def test_update_non_existing_fields_ignored(self):\\n        \\\"\\\"\\\"Test that non-existing fields are ignored.\\\"\\\"\\\"\\n        build_config = dotdict({\\\"field1\\\": \\\"value1\\\"})\\n        fields = {\\\"field1\\\": \\\"new_value\\\", \\\"non_existing\\\": \\\"ignored\\\"}\\n\\n        result = update_fields(build_config, fields)\\n\\n        assert result[\\\"field1\\\"] == \\\"new_value\\\"\\n        assert \\\"non_existing\\\" not in result\\n\\n    def test_update_empty_fields(self):\\n        \\\"\\\"\\\"Test updating with empty fields dict.\\\"\\\"\\\"\\n        build_config = dotdict({\\\"field1\\\": \\\"value1\\\"})\\n        fields = {}\\n\\n        result = update_fields(build_config, fields)\\n\\n        assert result[\\\"field1\\\"] == \\\"value1\\\"\\n\\n    def test_update_fields_returns_same_object(self):\\n        \\\"\\\"\\\"Test that update_fields modifies and returns the same object.\\\"\\\"\\\"\\n        build_config = dotdict({\\\"field1\\\": \\\"value1\\\"})\\n        fields = {\\\"field1\\\": \\\"new_value\\\"}\\n\\n        result = update_fields(build_config, fields)\\n\\n        assert result is build_config\\n        assert build_config[\\\"field1\\\"] == \\\"new_value\\\"\\n\\n\\nclass TestAddFields:\\n    \\\"\\\"\\\"Test cases for add_fields function.\\\"\\\"\\\"\\n\\n    def test_add_new_fields(self):\\n        \\\"\\\"\\\"Test adding new fields to build_config.\\\"\\\"\\\"\\n        build_config = dotdict({\\\"existing\\\": \\\"value\\\"})\\n        fields = {\\\"new_field1\\\": \\\"value1\\\", \\\"new_field2\\\": \\\"value2\\\"}\\n\\n        result = add_fields(build_config, fields)\\n\\n        assert result[\\\"existing\\\"] == \\\"value\\\"\\n        assert result[\\\"new_field1\\\"] == \\\"value1\\\"\\n        assert result[\\\"new_field2\\\"] == \\\"value2\\\"\\n\\n    def test_add_fields_overwrites_existing(self):\\n        \\\"\\\"\\\"Test that add_fields overwrites existing fields.\\\"\\\"\\\"\\n        build_config = dotdict({\\\"field1\\\": \\\"old_value\\\"})\\n        fields = {\\\"field1\\\": \\\"new_value\\\", \\\"field2\\\": \\\"value2\\\"}\\n\\n        result = add_fields(build_config, fields)\\n\\n        assert result[\\\"field1\\\"] == \\\"new_value\\\"\\n        assert result[\\\"field2\\\"] == \\\"value2\\\"\\n\\n    def test_add_empty_fields(self):\\n        \\\"\\\"\\\"Test adding empty fields dict.\\\"\\\"\\\"\\n        build_config = dotdict({\\\"field1\\\": \\\"value1\\\"})\\n        fields = {}\\n\\n        result = add_fields(build_config, fields)\\n\\n        assert result[\\\"field1\\\"] == \\\"value1\\\"\\n        assert len(result) == 1\\n\\n    def test_add_fields_returns_same_object(self):\\n        \\\"\\\"\\\"Test that add_fields modifies and returns the same object.\\\"\\\"\\\"\\n        build_config = dotdict({\\\"field1\\\": \\\"value1\\\"})\\n        fields = {\\\"field2\\\": \\\"value2\\\"}\\n\\n        result = add_fields(build_config, fields)\\n\\n        assert result is build_config\\n\\n\\nclass TestDeleteFields:\\n    \\\"\\\"\\\"Test cases for delete_fields function.\\\"\\\"\\\"\\n\\n    def test_delete_fields_with_dict(self):\\n        \\\"\\\"\\\"Test deleting fields using dict parameter.\\\"\\\"\\\"\\n        build_config = dotdict({\\\"field1\\\": \\\"value1\\\", \\\"field2\\\": \\\"value2\\\", \\\"field3\\\": \\\"value3\\\"})\\n        fields = {\\\"field1\\\": \\\"ignored_value\\\", \\\"field2\\\": \\\"also_ignored\\\"}\\n\\n        result = delete_fields(build_config, fields)\\n\\n        assert \\\"field1\\\" not in result\\n        assert \\\"field2\\\" not in result\\n        assert result[\\\"field3\\\"] == \\\"value3\\\"\\n\\n    def test_delete_fields_with_list(self):\\n        \\\"\\\"\\\"Test deleting fields using list parameter.\\\"\\\"\\\"\\n        build_config = dotdict({\\\"field1\\\": \\\"value1\\\", \\\"field2\\\": \\\"value2\\\", \\\"field3\\\": \\\"value3\\\"})\\n        fields = [\\\"field1\\\", \\\"field3\\\"]\\n\\n        result = delete_fields(build_config, fields)\\n\\n        assert \\\"field1\\\" not in result\\n        assert result[\\\"field2\\\"] == \\\"value2\\\"\\n        assert \\\"field3\\\" not in result\\n\\n    def test_delete_non_existing_fields(self):\\n        \\\"\\\"\\\"Test deleting non-existing fields does not raise error.\\\"\\\"\\\"\\n        build_config = dotdict({\\\"field1\\\": \\\"value1\\\"})\\n        fields = [\\\"field1\\\", \\\"non_existing\\\"]\\n\\n        result = delete_fields(build_config, fields)\\n\\n        assert \\\"field1\\\" not in result\\n        assert len(result) == 0\\n\\n    def test_delete_fields_returns_same_object(self):\\n        \\\"\\\"\\\"Test that delete_fields modifies and returns the same object.\\\"\\\"\\\"\\n        build_config = dotdict({\\\"field1\\\": \\\"value1\\\", \\\"field2\\\": \\\"value2\\\"})\\n        fields = [\\\"field1\\\"]\\n\\n        result = delete_fields(build_config, fields)\\n\\n        assert result is build_config\\n\\n\\nclass TestGetFields:\\n    \\\"\\\"\\\"Test cases for get_fields function.\\\"\\\"\\\"\\n\\n    def test_get_specific_fields(self):\\n        \\\"\\\"\\\"Test getting specific fields from build_config.\\\"\\\"\\\"\\n        build_config = dotdict({\\\"field1\\\": \\\"value1\\\", \\\"field2\\\": \\\"value2\\\", \\\"field3\\\": \\\"value3\\\"})\\n        fields = [\\\"field1\\\", \\\"field3\\\"]\\n\\n        result = get_fields(build_config, fields)\\n\\n        assert result == {\\\"field1\\\": \\\"value1\\\", \\\"field3\\\": \\\"value3\\\"}\\n\\n    def test_get_all_fields(self):\\n        \\\"\\\"\\\"Test getting all fields when fields is None.\\\"\\\"\\\"\\n        build_config = dotdict({\\\"field1\\\": \\\"value1\\\", \\\"field2\\\": \\\"value2\\\"})\\n\\n        result = get_fields(build_config, None)\\n\\n        assert result == {\\\"field1\\\": \\\"value1\\\", \\\"field2\\\": \\\"value2\\\"}\\n\\n    def test_get_non_existing_fields(self):\\n        \\\"\\\"\\\"Test getting non-existing fields returns empty dict.\\\"\\\"\\\"\\n        build_config = dotdict({\\\"field1\\\": \\\"value1\\\"})\\n        fields = [\\\"non_existing\\\"]\\n\\n        result = get_fields(build_config, fields)\\n\\n        assert result == {}\\n\\n    def test_get_mixed_existing_and_non_existing(self):\\n        \\\"\\\"\\\"Test getting mix of existing and non-existing fields.\\\"\\\"\\\"\\n        build_config = dotdict({\\\"field1\\\": \\\"value1\\\", \\\"field2\\\": \\\"value2\\\"})\\n        fields = [\\\"field1\\\", \\\"non_existing\\\", \\\"field2\\\"]\\n\\n        result = get_fields(build_config, fields)\\n\\n        assert result == {\\\"field1\\\": \\\"value1\\\", \\\"field2\\\": \\\"value2\\\"}\\n\\n    def test_get_fields_returns_new_dict(self):\\n        \\\"\\\"\\\"Test that get_fields returns a new dict, not modifying original.\\\"\\\"\\\"\\n        build_config = dotdict({\\\"field1\\\": \\\"value1\\\"})\\n\\n        result = get_fields(build_config, [\\\"field1\\\"])\\n        result[\\\"field1\\\"] = \\\"modified\\\"\\n\\n        assert build_config[\\\"field1\\\"] == \\\"value1\\\"  # Original unchanged\\n\\n\\nclass TestUpdateInputTypes:\\n    \\\"\\\"\\\"Test cases for update_input_types function.\\\"\\\"\\\"\\n\\n    def test_update_input_types_dict_format(self):\\n        \\\"\\\"\\\"Test updating input types for dict format fields.\\\"\\\"\\\"\\n        build_config = dotdict(\\n            {\\n                \\\"field1\\\": {\\\"input_types\\\": None},\\n                \\\"field2\\\": {\\\"input_types\\\": [\\\"existing\\\"]},\\n                \\\"field3\\\": {\\\"other_prop\\\": \\\"value\\\"},\\n            }\\n        )\\n\\n        result = update_input_types(build_config)\\n\\n        assert result[\\\"field1\\\"][\\\"input_types\\\"] == []\\n        assert result[\\\"field2\\\"][\\\"input_types\\\"] == [\\\"existing\\\"]  # Unchanged\\n        # The function adds input_types to all dict fields that don't have it\\n        assert result[\\\"field3\\\"][\\\"input_types\\\"] == []\\n\\n    def test_update_input_types_object_format(self):\\n        \\\"\\\"\\\"Test updating input types for object format fields.\\\"\\\"\\\"\\n        mock_obj1 = Mock()\\n        mock_obj1.input_types = None\\n        mock_obj2 = Mock()\\n        mock_obj2.input_types = [\\\"existing\\\"]\\n\\n        build_config = dotdict({\\\"field1\\\": mock_obj1, \\\"field2\\\": mock_obj2, \\\"field3\\\": \\\"string_value\\\"})\\n\\n        _ = update_input_types(build_config)\\n\\n        assert mock_obj1.input_types == []\\n        assert mock_obj2.input_types == [\\\"existing\\\"]  # Unchanged\\n\\n    def test_update_input_types_mixed_formats(self):\\n        \\\"\\\"\\\"Test updating input types with mixed dict and object formats.\\\"\\\"\\\"\\n        mock_obj = Mock()\\n        mock_obj.input_types = None\\n\\n        build_config = dotdict(\\n            {\\\"dict_field\\\": {\\\"input_types\\\": None, \\\"other\\\": \\\"value\\\"}, \\\"obj_field\\\": mock_obj, \\\"string_field\\\": \\\"value\\\"}\\n        )\\n\\n        result = update_input_types(build_config)\\n\\n        assert result[\\\"dict_field\\\"][\\\"input_types\\\"] == []\\n        assert mock_obj.input_types == []\\n\\n    def test_update_input_types_no_input_types_attr(self):\\n        \\\"\\\"\\\"Test updating with objects that don't have input_types attribute.\\\"\\\"\\\"\\n        mock_obj = Mock()\\n        del mock_obj.input_types  # Remove the attribute\\n\\n        build_config = dotdict({\\\"field1\\\": mock_obj})\\n\\n        # Should not raise error\\n        result = update_input_types(build_config)\\n\\n        assert result is build_config\\n\\n\\nclass TestSetFieldDisplay:\\n    \\\"\\\"\\\"Test cases for set_field_display function.\\\"\\\"\\\"\\n\\n    def test_set_field_display_existing_field(self):\\n        \\\"\\\"\\\"Test setting display for existing field with show property.\\\"\\\"\\\"\\n        build_config = dotdict({\\\"field1\\\": {\\\"show\\\": True, \\\"other\\\": \\\"value\\\"}})\\n\\n        result = set_field_display(build_config, \\\"field1\\\", value=False)\\n\\n        assert result[\\\"field1\\\"][\\\"show\\\"] is False\\n        assert result[\\\"field1\\\"][\\\"other\\\"] == \\\"value\\\"\\n\\n    def test_set_field_display_non_existing_field(self):\\n        \\\"\\\"\\\"Test setting display for non-existing field does nothing.\\\"\\\"\\\"\\n        build_config = dotdict({\\\"field1\\\": {\\\"show\\\": True}})\\n\\n        result = set_field_display(build_config, \\\"non_existing\\\", value=False)\\n\\n        assert result[\\\"field1\\\"][\\\"show\\\"] is True  # Unchanged\\n\\n    def test_set_field_display_field_without_show(self):\\n        \\\"\\\"\\\"Test setting display for field without show property does nothing.\\\"\\\"\\\"\\n        build_config = dotdict({\\\"field1\\\": {\\\"other\\\": \\\"value\\\"}})\\n\\n        result = set_field_display(build_config, \\\"field1\\\", value=False)\\n\\n        assert \\\"show\\\" not in result[\\\"field1\\\"]\\n\\n    def test_set_field_display_none_value(self):\\n        \\\"\\\"\\\"Test setting display with None value.\\\"\\\"\\\"\\n        build_config = dotdict({\\\"field1\\\": {\\\"show\\\": True}})\\n\\n        result = set_field_display(build_config, \\\"field1\\\", None)\\n\\n        assert result[\\\"field1\\\"][\\\"show\\\"] is None\\n\\n\\nclass TestSetMultipleFieldDisplay:\\n    \\\"\\\"\\\"Test cases for set_multiple_field_display function.\\\"\\\"\\\"\\n\\n    def test_set_multiple_field_display_with_fields_dict(self):\\n        \\\"\\\"\\\"Test setting display for multiple fields using fields dict.\\\"\\\"\\\"\\n        build_config = dotdict({\\\"field1\\\": {\\\"show\\\": True}, \\\"field2\\\": {\\\"show\\\": True}, \\\"field3\\\": {\\\"show\\\": True}})\\n        fields = {\\\"field1\\\": False, \\\"field2\\\": True}\\n\\n        result = set_multiple_field_display(build_config, fields=fields)\\n\\n        assert result[\\\"field1\\\"][\\\"show\\\"] is False\\n        assert result[\\\"field2\\\"][\\\"show\\\"] is True\\n        assert result[\\\"field3\\\"][\\\"show\\\"] is True  # Unchanged\\n\\n    def test_set_multiple_field_display_with_field_list(self):\\n        \\\"\\\"\\\"Test setting display for multiple fields using field list.\\\"\\\"\\\"\\n        build_config = dotdict({\\\"field1\\\": {\\\"show\\\": True}, \\\"field2\\\": {\\\"show\\\": True}, \\\"field3\\\": {\\\"show\\\": True}})\\n        field_list = [\\\"field1\\\", \\\"field2\\\"]\\n\\n        result = set_multiple_field_display(build_config, field_list=field_list, value=False)\\n\\n        assert result[\\\"field1\\\"][\\\"show\\\"] is False\\n        assert result[\\\"field2\\\"][\\\"show\\\"] is False\\n        assert result[\\\"field3\\\"][\\\"show\\\"] is True  # Unchanged\\n\\n    def test_set_multiple_field_display_no_params(self):\\n        \\\"\\\"\\\"Test setting multiple field display with no parameters does nothing.\\\"\\\"\\\"\\n        build_config = dotdict({\\\"field1\\\": {\\\"show\\\": True}})\\n\\n        result = set_multiple_field_display(build_config)\\n\\n        assert result[\\\"field1\\\"][\\\"show\\\"] is True  # Unchanged\\n\\n\\nclass TestSetFieldAdvanced:\\n    \\\"\\\"\\\"Test cases for set_field_advanced function.\\\"\\\"\\\"\\n\\n    def test_set_field_advanced_existing_field(self):\\n        \\\"\\\"\\\"Test setting advanced for existing field.\\\"\\\"\\\"\\n        build_config = dotdict({\\\"field1\\\": {\\\"advanced\\\": False, \\\"other\\\": \\\"value\\\"}})\\n\\n        result = set_field_advanced(build_config, \\\"field1\\\", value=True)\\n\\n        assert result[\\\"field1\\\"][\\\"advanced\\\"] is True\\n        assert result[\\\"field1\\\"][\\\"other\\\"] == \\\"value\\\"\\n\\n    def test_set_field_advanced_default_value(self):\\n        \\\"\\\"\\\"Test setting advanced with default value (None -> False).\\\"\\\"\\\"\\n        build_config = dotdict({\\\"field1\\\": {\\\"other\\\": \\\"value\\\"}})\\n\\n        result = set_field_advanced(build_config, \\\"field1\\\", None)\\n\\n        assert result[\\\"field1\\\"][\\\"advanced\\\"] is False\\n\\n    def test_set_field_advanced_non_dict_field(self):\\n        \\\"\\\"\\\"Test setting advanced for non-dict field does nothing.\\\"\\\"\\\"\\n        build_config = dotdict({\\\"field1\\\": \\\"string_value\\\"})\\n\\n        result = set_field_advanced(build_config, \\\"field1\\\", value=True)\\n\\n        assert result[\\\"field1\\\"] == \\\"string_value\\\"  # Unchanged\\n\\n    def test_set_field_advanced_creates_advanced_property(self):\\n        \\\"\\\"\\\"Test that advanced property is created if it doesn't exist.\\\"\\\"\\\"\\n        build_config = dotdict({\\\"field1\\\": {\\\"other\\\": \\\"value\\\"}})\\n\\n        result = set_field_advanced(build_config, \\\"field1\\\", value=True)\\n\\n        assert result[\\\"field1\\\"][\\\"advanced\\\"] is True\\n\\n\\nclass TestSetMultipleFieldAdvanced:\\n    \\\"\\\"\\\"Test cases for set_multiple_field_advanced function.\\\"\\\"\\\"\\n\\n    def test_set_multiple_field_advanced_with_fields_dict(self):\\n        \\\"\\\"\\\"Test setting advanced for multiple fields using fields dict.\\\"\\\"\\\"\\n        build_config = dotdict({\\\"field1\\\": {\\\"advanced\\\": False}, \\\"field2\\\": {\\\"advanced\\\": False}})\\n        fields = {\\\"field1\\\": True, \\\"field2\\\": False}\\n\\n        result = set_multiple_field_advanced(build_config, fields=fields)\\n\\n        assert result[\\\"field1\\\"][\\\"advanced\\\"] is True\\n        assert result[\\\"field2\\\"][\\\"advanced\\\"] is False\\n\\n    def test_set_multiple_field_advanced_with_field_list(self):\\n        \\\"\\\"\\\"Test setting advanced for multiple fields using field list.\\\"\\\"\\\"\\n        build_config = dotdict({\\\"field1\\\": {\\\"advanced\\\": False}, \\\"field2\\\": {\\\"advanced\\\": False}})\\n        field_list = [\\\"field1\\\", \\\"field2\\\"]\\n\\n        result = set_multiple_field_advanced(build_config, field_list=field_list, value=True)\\n\\n        assert result[\\\"field1\\\"][\\\"advanced\\\"] is True\\n        assert result[\\\"field2\\\"][\\\"advanced\\\"] is True\\n\\n\\nclass TestMergeBuildConfigs:\\n    \\\"\\\"\\\"Test cases for merge_build_configs function.\\\"\\\"\\\"\\n\\n    def test_merge_build_configs_simple(self):\\n        \\\"\\\"\\\"Test merging simple build configurations.\\\"\\\"\\\"\\n        base_config = dotdict({\\\"field1\\\": \\\"base_value\\\", \\\"field2\\\": \\\"base_value2\\\"})\\n        override_config = dotdict({\\\"field1\\\": \\\"override_value\\\", \\\"field3\\\": \\\"new_value\\\"})\\n\\n        result = merge_build_configs(base_config, override_config)\\n\\n        assert result[\\\"field1\\\"] == \\\"override_value\\\"  # Overridden\\n        assert result[\\\"field2\\\"] == \\\"base_value2\\\"  # From base\\n        assert result[\\\"field3\\\"] == \\\"new_value\\\"  # Added\\n\\n    def test_merge_build_configs_nested_dicts(self):\\n        \\\"\\\"\\\"Test merging build configurations with nested dictionaries.\\\"\\\"\\\"\\n        base_config = dotdict({\\\"field1\\\": {\\\"nested1\\\": \\\"base_value\\\", \\\"nested2\\\": \\\"base_value2\\\"}})\\n        override_config = dotdict({\\\"field1\\\": {\\\"nested1\\\": \\\"override_value\\\", \\\"nested3\\\": \\\"new_value\\\"}})\\n\\n        result = merge_build_configs(base_config, override_config)\\n\\n        assert result[\\\"field1\\\"][\\\"nested1\\\"] == \\\"override_value\\\"\\n        assert result[\\\"field1\\\"][\\\"nested2\\\"] == \\\"base_value2\\\"\\n        assert result[\\\"field1\\\"][\\\"nested3\\\"] == \\\"new_value\\\"\\n\\n    def test_merge_build_configs_returns_new_object(self):\\n        \\\"\\\"\\\"Test that merge returns a new dotdict object.\\\"\\\"\\\"\\n        base_config = dotdict({\\\"field1\\\": \\\"base_value\\\"})\\n        override_config = dotdict({\\\"field2\\\": \\\"override_value\\\"})\\n\\n        result = merge_build_configs(base_config, override_config)\\n\\n        assert result is not base_config\\n        assert isinstance(result, dotdict)\\n\\n    def test_merge_build_configs_override_dict_with_non_dict(self):\\n        \\\"\\\"\\\"Test overriding dict with non-dict value.\\\"\\\"\\\"\\n        base_config = dotdict({\\\"field1\\\": {\\\"nested\\\": \\\"value\\\"}})\\n        override_config = dotdict({\\\"field1\\\": \\\"string_value\\\"})\\n\\n        result = merge_build_configs(base_config, override_config)\\n\\n        assert result[\\\"field1\\\"] == \\\"string_value\\\"\\n\\n\\nclass TestSetCurrentFields:\\n    \\\"\\\"\\\"Test cases for set_current_fields function.\\\"\\\"\\\"\\n\\n    def test_set_current_fields_with_selected_action(self):\\n        \\\"\\\"\\\"Test setting current fields with a selected action.\\\"\\\"\\\"\\n        build_config = dotdict(\\n            {\\n                \\\"field1\\\": {\\\"show\\\": False},\\n                \\\"field2\\\": {\\\"show\\\": False},\\n                \\\"field3\\\": {\\\"show\\\": False},\\n                \\\"code\\\": {\\\"show\\\": False},\\n                \\\"_type\\\": {\\\"show\\\": False},\\n            }\\n        )\\n        action_fields = {\\\"action1\\\": [\\\"field1\\\", \\\"field2\\\"], \\\"action2\\\": [\\\"field3\\\"]}\\n\\n        result = set_current_fields(build_config, action_fields, \\\"action1\\\")\\n\\n        # Selected action fields should be shown\\n        assert result[\\\"field1\\\"][\\\"show\\\"] is True\\n        assert result[\\\"field2\\\"][\\\"show\\\"] is True\\n        # Other action fields should be hidden\\n        assert result[\\\"field3\\\"][\\\"show\\\"] is False\\n        # Default fields should be shown\\n        assert result[\\\"code\\\"][\\\"show\\\"] is True\\n        assert result[\\\"_type\\\"][\\\"show\\\"] is True\\n\\n    def test_set_current_fields_no_selected_action(self):\\n        \\\"\\\"\\\"Test setting current fields with no selected action.\\\"\\\"\\\"\\n        build_config = dotdict({\\\"field1\\\": {\\\"show\\\": True}, \\\"field2\\\": {\\\"show\\\": True}, \\\"code\\\": {\\\"show\\\": False}})\\n        action_fields = {\\\"action1\\\": [\\\"field1\\\"], \\\"action2\\\": [\\\"field2\\\"]}\\n\\n        result = set_current_fields(build_config, action_fields, None)\\n\\n        # All action fields should be hidden\\n        assert result[\\\"field1\\\"][\\\"show\\\"] is False\\n        assert result[\\\"field2\\\"][\\\"show\\\"] is False\\n        # Default fields should be shown\\n        assert result[\\\"code\\\"][\\\"show\\\"] is True\\n\\n    def test_set_current_fields_custom_function(self):\\n        \\\"\\\"\\\"Test setting current fields with custom function.\\\"\\\"\\\"\\n        build_config = dotdict(\\n            {\\\"field1\\\": {\\\"advanced\\\": False}, \\\"field2\\\": {\\\"advanced\\\": False}, \\\"code\\\": {\\\"advanced\\\": False}}\\n        )\\n        action_fields = {\\\"action1\\\": [\\\"field1\\\"], \\\"action2\\\": [\\\"field2\\\"]}\\n\\n        result = set_current_fields(build_config, action_fields, \\\"action1\\\", func=set_field_advanced)\\n\\n        # Selected field should be True (not default_value)\\n        assert result[\\\"field1\\\"][\\\"advanced\\\"] is True  # Selected field gets not default_value (True)\\n        assert result[\\\"field2\\\"][\\\"advanced\\\"] is False  # Non-selected field gets default_value (False)\\n        assert result[\\\"code\\\"][\\\"advanced\\\"] is True  # Default field gets not default_value (True)\\n\\n    def test_set_current_fields_custom_default_value(self):\\n        \\\"\\\"\\\"Test setting current fields with custom default value.\\\"\\\"\\\"\\n        build_config = dotdict({\\\"field1\\\": {\\\"show\\\": False}, \\\"field2\\\": {\\\"show\\\": False}, \\\"code\\\": {\\\"show\\\": False}})\\n        action_fields = {\\\"action1\\\": [\\\"field1\\\"], \\\"action2\\\": [\\\"field2\\\"]}\\n\\n        result = set_current_fields(\\n            build_config,\\n            action_fields,\\n            \\\"action1\\\",\\n            default_value=True,  # Inverted logic\\n        )\\n\\n        # With default_value=True:\\n        # - Selected field gets not default_value = False\\n        # - Non-selected fields get default_value = True\\n        # - Default fields get not default_value = False\\n        assert result[\\\"field1\\\"][\\\"show\\\"] is False  # Selected field gets not default_value\\n        assert result[\\\"field2\\\"][\\\"show\\\"] is True  # Non-selected field gets default_value\\n        assert result[\\\"code\\\"][\\\"show\\\"] is False  # Default field gets not default_value\\n\\n    def test_set_current_fields_no_default_fields(self):\\n        \\\"\\\"\\\"Test setting current fields with no default fields.\\\"\\\"\\\"\\n        build_config = dotdict({\\\"field1\\\": {\\\"show\\\": False}, \\\"code\\\": {\\\"show\\\": False}})\\n        action_fields = {\\\"action1\\\": [\\\"field1\\\"]}\\n\\n        result = set_current_fields(build_config, action_fields, \\\"action1\\\", default_fields=None)\\n\\n        # Only action field should be affected\\n        assert result[\\\"field1\\\"][\\\"show\\\"] is True\\n        assert result[\\\"code\\\"][\\\"show\\\"] is False  # Unchanged\\n\\n    def test_default_fields_constant(self):\\n        \\\"\\\"\\\"Test that DEFAULT_FIELDS constant has expected value.\\\"\\\"\\\"\\n        assert DEFAULT_FIELDS == [\\\"code\\\", \\\"_type\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/utils/test_compression.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"925bcdfe7f0a3f3a3c54f373dc56de31cef0f8d12d31585bc67c83162356bb39\",\"content\":\"import gzip\\nimport json\\nfrom datetime import date, datetime, timezone\\nfrom unittest.mock import patch\\n\\nfrom fastapi import Response\\nfrom langflow.utils.compression import compress_response\\n\\n\\nclass TestCompressResponse:\\n    \\\"\\\"\\\"Test cases for compress_response function.\\\"\\\"\\\"\\n\\n    def test_compress_response_simple_dict(self):\\n        \\\"\\\"\\\"Test compressing a simple dictionary.\\\"\\\"\\\"\\n        data = {\\\"message\\\": \\\"hello\\\", \\\"status\\\": \\\"success\\\"}\\n\\n        response = compress_response(data)\\n\\n        assert isinstance(response, Response)\\n        assert response.media_type == \\\"application/json\\\"\\n        assert response.headers[\\\"Content-Encoding\\\"] == \\\"gzip\\\"\\n        assert response.headers[\\\"Vary\\\"] == \\\"Accept-Encoding\\\"\\n        assert \\\"Content-Length\\\" in response.headers\\n\\n        # Decompress and verify content\\n        decompressed = gzip.decompress(response.body)\\n        parsed_data = json.loads(decompressed.decode(\\\"utf-8\\\"))\\n        assert parsed_data == data\\n\\n    def test_compress_response_simple_list(self):\\n        \\\"\\\"\\\"Test compressing a simple list.\\\"\\\"\\\"\\n        data = [\\\"item1\\\", \\\"item2\\\", \\\"item3\\\"]\\n\\n        response = compress_response(data)\\n\\n        assert isinstance(response, Response)\\n        assert response.media_type == \\\"application/json\\\"\\n\\n        # Decompress and verify content\\n        decompressed = gzip.decompress(response.body)\\n        parsed_data = json.loads(decompressed.decode(\\\"utf-8\\\"))\\n        assert parsed_data == data\\n\\n    def test_compress_response_string(self):\\n        \\\"\\\"\\\"Test compressing a string.\\\"\\\"\\\"\\n        data = \\\"simple string message\\\"\\n\\n        response = compress_response(data)\\n\\n        assert isinstance(response, Response)\\n\\n        # Decompress and verify content\\n        decompressed = gzip.decompress(response.body)\\n        parsed_data = json.loads(decompressed.decode(\\\"utf-8\\\"))\\n        assert parsed_data == data\\n\\n    def test_compress_response_number(self):\\n        \\\"\\\"\\\"Test compressing numeric data.\\\"\\\"\\\"\\n        data = 42\\n\\n        response = compress_response(data)\\n\\n        assert isinstance(response, Response)\\n\\n        # Decompress and verify content\\n        decompressed = gzip.decompress(response.body)\\n        parsed_data = json.loads(decompressed.decode(\\\"utf-8\\\"))\\n        assert parsed_data == data\\n\\n    def test_compress_response_boolean(self):\\n        \\\"\\\"\\\"Test compressing boolean data.\\\"\\\"\\\"\\n        data = True\\n\\n        response = compress_response(data)\\n\\n        assert isinstance(response, Response)\\n\\n        # Decompress and verify content\\n        decompressed = gzip.decompress(response.body)\\n        parsed_data = json.loads(decompressed.decode(\\\"utf-8\\\"))\\n        assert parsed_data == data\\n\\n    def test_compress_response_none(self):\\n        \\\"\\\"\\\"Test compressing None value.\\\"\\\"\\\"\\n        data = None\\n\\n        response = compress_response(data)\\n\\n        assert isinstance(response, Response)\\n\\n        # Decompress and verify content\\n        decompressed = gzip.decompress(response.body)\\n        parsed_data = json.loads(decompressed.decode(\\\"utf-8\\\"))\\n        assert parsed_data is None\\n\\n    def test_compress_response_nested_data(self):\\n        \\\"\\\"\\\"Test compressing nested data structures.\\\"\\\"\\\"\\n        data = {\\n            \\\"users\\\": [{\\\"id\\\": 1, \\\"name\\\": \\\"Alice\\\", \\\"active\\\": True}, {\\\"id\\\": 2, \\\"name\\\": \\\"Bob\\\", \\\"active\\\": False}],\\n            \\\"metadata\\\": {\\\"total\\\": 2, \\\"page\\\": 1, \\\"has_more\\\": False},\\n            \\\"settings\\\": None,\\n        }\\n\\n        response = compress_response(data)\\n\\n        assert isinstance(response, Response)\\n\\n        # Decompress and verify content\\n        decompressed = gzip.decompress(response.body)\\n        parsed_data = json.loads(decompressed.decode(\\\"utf-8\\\"))\\n        assert parsed_data == data\\n\\n    def test_compress_response_large_data(self):\\n        \\\"\\\"\\\"Test compressing large data to verify compression effectiveness.\\\"\\\"\\\"\\n        # Create large data that should compress well (repeated patterns)\\n        data = {\\\"items\\\": [\\\"test_item\\\"] * 1000, \\\"metadata\\\": {\\\"repeated_value\\\": \\\"x\\\" * 500}}\\n\\n        response = compress_response(data)\\n\\n        # Original JSON size\\n        original_json = json.dumps(data).encode(\\\"utf-8\\\")\\n        original_size = len(original_json)\\n        compressed_size = len(response.body)\\n\\n        # Verify compression occurred (should be significantly smaller)\\n        assert compressed_size < original_size\\n        assert compressed_size < original_size * 0.5  # At least 50% compression\\n\\n        # Verify content integrity\\n        decompressed = gzip.decompress(response.body)\\n        parsed_data = json.loads(decompressed.decode(\\\"utf-8\\\"))\\n        assert parsed_data == data\\n\\n    def test_compress_response_unicode_data(self):\\n        \\\"\\\"\\\"Test compressing data with unicode characters.\\\"\\\"\\\"\\n        data = {\\n            \\\"message\\\": \\\"Hello \u4e16\u754c! \ud83c\udf0d \u00c9mojis and acc\u00e9nts\\\",\\n            \\\"unicode_string\\\": \\\"\u30c6\u30b9\u30c8 \u30c7\u30fc\u30bf\\\",\\n            \\\"special_chars\\\": \\\"\u00e0\u00e1\u00e2\u00e3\u00e4\u00e5\u00e6\u00e7\u00e8\u00e9\u00ea\u00eb\\\",\\n        }\\n\\n        response = compress_response(data)\\n\\n        assert isinstance(response, Response)\\n\\n        # Decompress and verify content\\n        decompressed = gzip.decompress(response.body)\\n        parsed_data = json.loads(decompressed.decode(\\\"utf-8\\\"))\\n        assert parsed_data == data\\n\\n    def test_compress_response_empty_dict(self):\\n        \\\"\\\"\\\"Test compressing empty dictionary.\\\"\\\"\\\"\\n        data = {}\\n\\n        response = compress_response(data)\\n\\n        assert isinstance(response, Response)\\n\\n        # Decompress and verify content\\n        decompressed = gzip.decompress(response.body)\\n        parsed_data = json.loads(decompressed.decode(\\\"utf-8\\\"))\\n        assert parsed_data == data\\n\\n    def test_compress_response_empty_list(self):\\n        \\\"\\\"\\\"Test compressing empty list.\\\"\\\"\\\"\\n        data = []\\n\\n        response = compress_response(data)\\n\\n        assert isinstance(response, Response)\\n\\n        # Decompress and verify content\\n        decompressed = gzip.decompress(response.body)\\n        parsed_data = json.loads(decompressed.decode(\\\"utf-8\\\"))\\n        assert parsed_data == data\\n\\n    def test_compress_response_headers(self):\\n        \\\"\\\"\\\"Test that response has correct headers.\\\"\\\"\\\"\\n        data = {\\\"test\\\": \\\"data\\\"}\\n\\n        response = compress_response(data)\\n\\n        # Check required headers\\n        assert response.headers[\\\"Content-Encoding\\\"] == \\\"gzip\\\"\\n        assert response.headers[\\\"Vary\\\"] == \\\"Accept-Encoding\\\"\\n        assert response.headers[\\\"Content-Length\\\"] == str(len(response.body))\\n        assert response.media_type == \\\"application/json\\\"\\n\\n    def test_compress_response_content_length_accuracy(self):\\n        \\\"\\\"\\\"Test that Content-Length header matches actual body length.\\\"\\\"\\\"\\n        data = {\\\"message\\\": \\\"test\\\", \\\"numbers\\\": [1, 2, 3, 4, 5]}\\n\\n        response = compress_response(data)\\n\\n        content_length = int(response.headers[\\\"Content-Length\\\"])\\n        actual_length = len(response.body)\\n\\n        assert content_length == actual_length\\n\\n    @patch(\\\"langflow.utils.compression.jsonable_encoder\\\")\\n    def test_compress_response_jsonable_encoder_called(self, mock_encoder):\\n        \\\"\\\"\\\"Test that jsonable_encoder is called on the data.\\\"\\\"\\\"\\n        data = {\\\"test\\\": \\\"data\\\"}\\n        mock_encoder.return_value = data\\n\\n        compress_response(data)\\n\\n        mock_encoder.assert_called_once_with(data)\\n\\n    @patch(\\\"langflow.utils.compression.gzip.compress\\\")\\n    def test_compress_response_gzip_compression_level(self, mock_compress):\\n        \\\"\\\"\\\"Test that gzip.compress is called with correct compression level.\\\"\\\"\\\"\\n        data = {\\\"test\\\": \\\"data\\\"}\\n        mock_compress.return_value = b\\\"compressed_data\\\"\\n\\n        compress_response(data)\\n\\n        # Verify gzip.compress was called with compresslevel=6\\n        mock_compress.assert_called_once()\\n        call_args = mock_compress.call_args\\n        assert call_args[1][\\\"compresslevel\\\"] == 6\\n\\n    def test_compress_response_with_custom_objects(self):\\n        \\\"\\\"\\\"Test compressing data with objects that need JSON encoding.\\\"\\\"\\\"\\n        data = {\\n            \\\"timestamp\\\": datetime(2023, 1, 1, 12, 0, 0, tzinfo=timezone.utc),\\n            \\\"date\\\": date(2023, 1, 1),\\n            \\\"message\\\": \\\"test with custom objects\\\",\\n        }\\n\\n        response = compress_response(data)\\n\\n        assert isinstance(response, Response)\\n\\n        # Decompress and verify content (datetime should be converted to string)\\n        decompressed = gzip.decompress(response.body)\\n        parsed_data = json.loads(decompressed.decode(\\\"utf-8\\\"))\\n\\n        # Check that custom objects were properly serialized\\n        assert \\\"timestamp\\\" in parsed_data\\n        assert \\\"date\\\" in parsed_data\\n        assert parsed_data[\\\"message\\\"] == \\\"test with custom objects\\\"\\n\\n    def test_compress_response_compression_ratio(self):\\n        \\\"\\\"\\\"Test compression ratio with different types of data.\\\"\\\"\\\"\\n        # Highly compressible data (lots of repetition)\\n        repetitive_data = {\\\"data\\\": \\\"a\\\" * 1000}\\n\\n        # Less compressible data (more random)\\n        import random\\n        import string\\n\\n        random_data = {\\\"data\\\": [\\\"\\\".join(random.choices(string.ascii_letters, k=10)) for _ in range(100)]}  # noqa: S311\\n\\n        rep_response = compress_response(repetitive_data)\\n        rand_response = compress_response(random_data)\\n\\n        rep_original = len(json.dumps(repetitive_data).encode(\\\"utf-8\\\"))\\n        rand_original = len(json.dumps(random_data).encode(\\\"utf-8\\\"))\\n\\n        rep_compressed = len(rep_response.body)\\n        rand_compressed = len(rand_response.body)\\n\\n        # Repetitive data should have better compression ratio\\n        rep_ratio = rep_compressed / rep_original\\n        rand_ratio = rand_compressed / rand_original\\n\\n        assert rep_ratio < rand_ratio  # Better compression for repetitive data\\n        assert rep_ratio < 0.1  # Very good compression for repetitive data\\n\\n    def test_compress_response_error_handling_invalid_json(self):\\n        \\\"\\\"\\\"Test error handling when data cannot be JSON serialized.\\\"\\\"\\\"\\n\\n        # Create an object that cannot be JSON serialized\\n        class NonSerializable:\\n            def __init__(self):\\n                self.func = lambda x: x\\n\\n        data = {\\\"object\\\": NonSerializable()}\\n\\n        # jsonable_encoder should handle this, but if it doesn't, test the behavior\\n        try:\\n            response = compress_response(data)\\n            # If no exception, verify the response is still valid\\n            assert isinstance(response, Response)\\n        except (TypeError, ValueError):\\n            # Expected behavior if jsonable_encoder can't handle the object\\n            pass\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/utils/test_concurrency.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a829a7ddaf9090c0d393ac3b70abe917d9c66b7e89cb3c27328e1f5063de13fd\",\"content\":\"import threading\\nimport time\\nfrom unittest.mock import MagicMock, patch\\n\\nimport pytest\\nfrom lfx.utils.concurrency import KeyedMemoryLockManager, KeyedWorkerLockManager\\n\\n\\nclass TestKeyedMemoryLockManager:\\n    \\\"\\\"\\\"Test cases for KeyedMemoryLockManager class.\\\"\\\"\\\"\\n\\n    def test_initialization(self):\\n        \\\"\\\"\\\"Test proper initialization of KeyedMemoryLockManager.\\\"\\\"\\\"\\n        manager = KeyedMemoryLockManager()\\n\\n        assert isinstance(manager.locks, dict)\\n        assert len(manager.locks) == 0\\n        assert hasattr(manager, \\\"global_lock\\\")\\n        assert hasattr(manager.global_lock, \\\"acquire\\\")\\n        assert hasattr(manager.global_lock, \\\"release\\\")\\n\\n    def test_get_lock_creates_new_lock(self):\\n        \\\"\\\"\\\"Test that _get_lock creates a new lock for new keys.\\\"\\\"\\\"\\n        manager = KeyedMemoryLockManager()\\n\\n        lock1 = manager._get_lock(\\\"key1\\\")\\n\\n        assert hasattr(lock1, \\\"acquire\\\")\\n        assert hasattr(lock1, \\\"release\\\")\\n        assert \\\"key1\\\" in manager.locks\\n        assert manager.locks[\\\"key1\\\"] is lock1\\n\\n    def test_get_lock_returns_existing_lock(self):\\n        \\\"\\\"\\\"Test that _get_lock returns existing lock for known keys.\\\"\\\"\\\"\\n        manager = KeyedMemoryLockManager()\\n\\n        lock1 = manager._get_lock(\\\"key1\\\")\\n        lock2 = manager._get_lock(\\\"key1\\\")\\n\\n        assert lock1 is lock2\\n        assert len(manager.locks) == 1\\n\\n    def test_get_lock_different_keys(self):\\n        \\\"\\\"\\\"Test that different keys get different locks.\\\"\\\"\\\"\\n        manager = KeyedMemoryLockManager()\\n\\n        lock1 = manager._get_lock(\\\"key1\\\")\\n        lock2 = manager._get_lock(\\\"key2\\\")\\n\\n        assert lock1 is not lock2\\n        assert len(manager.locks) == 2\\n        assert manager.locks[\\\"key1\\\"] is lock1\\n        assert manager.locks[\\\"key2\\\"] is lock2\\n\\n    def test_context_manager_basic_functionality(self):\\n        \\\"\\\"\\\"Test that the context manager works with basic functionality.\\\"\\\"\\\"\\n        manager = KeyedMemoryLockManager()\\n\\n        # Test that context manager doesn't raise exceptions\\n        with manager.lock(\\\"test_key\\\"):\\n            assert \\\"test_key\\\" in manager.locks\\n\\n        # Lock should still exist after context\\n        assert \\\"test_key\\\" in manager.locks\\n\\n    def test_context_manager_exception_handling(self):\\n        \\\"\\\"\\\"Test that context manager handles exceptions properly.\\\"\\\"\\\"\\n        manager = KeyedMemoryLockManager()\\n\\n        # Test that exceptions don't break the manager\\n        try:\\n            with manager.lock(\\\"test_key\\\"):\\n                msg = \\\"Test exception\\\"\\n                raise ValueError(msg)\\n        except ValueError:\\n            pass\\n\\n        # Manager should still be functional\\n        assert \\\"test_key\\\" in manager.locks\\n\\n        # Should be able to use the same lock again\\n        with manager.lock(\\\"test_key\\\"):\\n            pass\\n\\n    def test_concurrent_access_same_key(self):\\n        \\\"\\\"\\\"Test concurrent access to the same key is serialized.\\\"\\\"\\\"\\n        manager = KeyedMemoryLockManager()\\n        results = []\\n\\n        def worker(worker_id):\\n            with manager.lock(\\\"shared_key\\\"):\\n                results.append(f\\\"start_{worker_id}\\\")\\n                time.sleep(0.01)  # Small delay to ensure serialization\\n                results.append(f\\\"end_{worker_id}\\\")\\n\\n        threads = []\\n        for i in range(3):\\n            thread = threading.Thread(target=worker, args=(i,))\\n            threads.append(thread)\\n            thread.start()\\n\\n        for thread in threads:\\n            thread.join()\\n\\n        # Results should be properly serialized (start/end pairs together)\\n        assert len(results) == 6\\n        # Each worker should complete fully before next one starts\\n        for i in range(3):\\n            start_idx = results.index(f\\\"start_{i}\\\")\\n            end_idx = results.index(f\\\"end_{i}\\\")\\n            assert end_idx == start_idx + 1\\n\\n    def test_concurrent_access_different_keys(self):\\n        \\\"\\\"\\\"Test concurrent access to different keys can proceed in parallel.\\\"\\\"\\\"\\n        manager = KeyedMemoryLockManager()\\n        results = []\\n        result_lock = threading.Lock()\\n\\n        def worker(worker_id, key):\\n            with manager.lock(key):\\n                with result_lock:\\n                    results.append(f\\\"start_{worker_id}\\\")\\n                time.sleep(0.01)\\n                with result_lock:\\n                    results.append(f\\\"end_{worker_id}\\\")\\n\\n        threads = []\\n        for i in range(3):\\n            thread = threading.Thread(target=worker, args=(i, f\\\"key_{i}\\\"))\\n            threads.append(thread)\\n            thread.start()\\n\\n        for thread in threads:\\n            thread.join()\\n\\n        # All threads should have completed\\n        assert len(results) == 6\\n        assert len([r for r in results if r.startswith(\\\"start_\\\")]) == 3\\n        assert len([r for r in results if r.startswith(\\\"end_\\\")]) == 3\\n\\n    def test_lock_manager_thread_safety(self):\\n        \\\"\\\"\\\"Test that the lock manager itself is thread-safe.\\\"\\\"\\\"\\n        manager = KeyedMemoryLockManager()\\n        created_locks = []\\n\\n        def create_locks():\\n            for i in range(10):\\n                lock = manager._get_lock(f\\\"key_{i}\\\")\\n                created_locks.append(lock)\\n\\n        threads = []\\n        for _ in range(3):\\n            thread = threading.Thread(target=create_locks)\\n            threads.append(thread)\\n            thread.start()\\n\\n        for thread in threads:\\n            thread.join()\\n\\n        # Should have created exactly 10 unique locks\\n        assert len(manager.locks) == 10\\n        assert len(created_locks) == 30  # 3 threads * 10 locks each\\n\\n\\nclass TestKeyedWorkerLockManager:\\n    \\\"\\\"\\\"Test cases for KeyedWorkerLockManager class.\\\"\\\"\\\"\\n\\n    def test_initialization(self):\\n        \\\"\\\"\\\"Test proper initialization of KeyedWorkerLockManager.\\\"\\\"\\\"\\n        with (\\n            patch(\\\"lfx.utils.concurrency.user_cache_dir\\\") as mock_cache_dir,\\n            patch(\\\"lfx.utils.concurrency.Path\\\") as mock_path,\\n        ):\\n            mock_cache_dir.return_value = \\\"/cache/dir\\\"\\n            mock_path_instance = MagicMock()\\n            mock_path.return_value = mock_path_instance\\n\\n            manager = KeyedWorkerLockManager()\\n\\n            mock_cache_dir.assert_called_once_with(\\\"langflow\\\", ensure_exists=True)\\n            assert manager.locks_dir == mock_path_instance.__truediv__.return_value\\n\\n    def test_validate_key_valid_keys(self):\\n        \\\"\\\"\\\"Test that _validate_key accepts valid keys.\\\"\\\"\\\"\\n        manager = KeyedWorkerLockManager()\\n\\n        valid_keys = [\\n            \\\"valid_key\\\",\\n            \\\"key123\\\",\\n            \\\"KEY_WITH_CAPS\\\",\\n            \\\"mix3d_K3y\\\",\\n            \\\"_underscore_start\\\",\\n            \\\"underscore_end_\\\",\\n            \\\"123numbers\\\",\\n            \\\"a\\\",\\n            \\\"A\\\",\\n            \\\"_\\\",\\n            \\\"key_123_test\\\",\\n        ]\\n\\n        for key in valid_keys:\\n            assert manager._validate_key(key) is True\\n\\n    def test_validate_key_invalid_keys(self):\\n        \\\"\\\"\\\"Test that _validate_key rejects invalid keys.\\\"\\\"\\\"\\n        manager = KeyedWorkerLockManager()\\n\\n        invalid_keys = [\\n            \\\"key-with-dashes\\\",\\n            \\\"key with spaces\\\",\\n            \\\"key.with.dots\\\",\\n            \\\"key@symbol\\\",\\n            \\\"key#hash\\\",\\n            \\\"key$dollar\\\",\\n            \\\"key%percent\\\",\\n            \\\"key^caret\\\",\\n            \\\"key&ampersand\\\",\\n            \\\"key*asterisk\\\",\\n            \\\"key+plus\\\",\\n            \\\"key=equals\\\",\\n            \\\"key[bracket\\\",\\n            \\\"key{brace\\\",\\n            \\\"key/slash\\\",\\n            \\\"key\\\\\\\\backslash\\\",\\n            \\\"key|pipe\\\",\\n            \\\"key:colon\\\",\\n            \\\"key;semicolon\\\",\\n            \\\"key'quote\\\",\\n            'key\\\"doublequote',\\n            \\\"key<less\\\",\\n            \\\"key>greater\\\",\\n            \\\"key?question\\\",\\n            \\\"\\\",  # empty string\\n        ]\\n\\n        for key in invalid_keys:\\n            assert manager._validate_key(key) is False\\n\\n    def test_lock_with_valid_key(self):\\n        \\\"\\\"\\\"Test lock context manager with valid key.\\\"\\\"\\\"\\n        manager = KeyedWorkerLockManager()\\n\\n        with patch(\\\"lfx.utils.concurrency.FileLock\\\") as mock_filelock:\\n            mock_lock_instance = MagicMock()\\n            mock_filelock.return_value = mock_lock_instance\\n\\n            with manager.lock(\\\"valid_key\\\"):\\n                pass\\n\\n            # Verify FileLock was created with correct path\\n            mock_filelock.assert_called_once()\\n            # Verify context manager was used\\n            mock_lock_instance.__enter__.assert_called_once()\\n            mock_lock_instance.__exit__.assert_called_once()\\n\\n    def test_lock_with_invalid_key_raises_error(self):\\n        \\\"\\\"\\\"Test that lock raises ValueError for invalid keys.\\\"\\\"\\\"\\n        manager = KeyedWorkerLockManager()\\n\\n        with (\\n            pytest.raises(ValueError, match=\\\"Invalid key: invalid-key\\\"),\\n            manager.lock(\\\"invalid-key\\\"),\\n        ):\\n            pass\\n\\n    def test_lock_file_path_construction(self):\\n        \\\"\\\"\\\"Test that lock file path is constructed correctly.\\\"\\\"\\\"\\n        with (\\n            patch(\\\"lfx.utils.concurrency.user_cache_dir\\\") as mock_cache_dir,\\n            patch(\\\"lfx.utils.concurrency.Path\\\") as mock_path,\\n            patch(\\\"lfx.utils.concurrency.FileLock\\\") as mock_filelock,\\n        ):\\n            mock_cache_dir.return_value = \\\"/cache\\\"\\n            mock_locks_dir = MagicMock()\\n            mock_path.return_value.__truediv__.return_value = mock_locks_dir\\n\\n            manager = KeyedWorkerLockManager()\\n\\n            with manager.lock(\\\"test_key\\\"):\\n                pass\\n\\n            # Verify FileLock was called with correct path\\n            mock_filelock.assert_called_once_with(mock_locks_dir.__truediv__.return_value)\\n            mock_locks_dir.__truediv__.assert_called_once_with(\\\"test_key\\\")\\n\\n    def test_lock_context_manager_exception_handling(self):\\n        \\\"\\\"\\\"Test that lock is properly released even when exception occurs.\\\"\\\"\\\"\\n        manager = KeyedWorkerLockManager()\\n\\n        with patch(\\\"lfx.utils.concurrency.FileLock\\\") as mock_filelock:\\n            mock_lock_instance = MagicMock()\\n            mock_filelock.return_value = mock_lock_instance\\n\\n            try:\\n                with manager.lock(\\\"valid_key\\\"):\\n                    msg = \\\"Test exception\\\"\\n                    raise ValueError(msg)\\n            except ValueError:\\n                pass\\n\\n            # Verify context manager was properly exited\\n            mock_lock_instance.__exit__.assert_called_once()\\n\\n    def test_multiple_keys_create_different_locks(self):\\n        \\\"\\\"\\\"Test that different keys create different file locks.\\\"\\\"\\\"\\n        manager = KeyedWorkerLockManager()\\n\\n        with patch(\\\"lfx.utils.concurrency.FileLock\\\") as mock_filelock:\\n            mock_filelock.return_value = MagicMock()\\n\\n            with manager.lock(\\\"key1\\\"):\\n                pass\\n\\n            with manager.lock(\\\"key2\\\"):\\n                pass\\n\\n            # Should have been called twice with different paths\\n            assert mock_filelock.call_count == 2\\n            call_args = [call[0][0] for call in mock_filelock.call_args_list]\\n            assert call_args[0] != call_args[1]  # Different paths\\n\\n    def test_validate_key_regex_pattern(self):\\n        \\\"\\\"\\\"Test the regex pattern used for key validation.\\\"\\\"\\\"\\n        manager = KeyedWorkerLockManager()\\n\\n        # Test edge cases for the regex pattern\\n        assert manager._validate_key(\\\"_\\\") is True  # Single underscore\\n        assert manager._validate_key(\\\"1\\\") is True  # Single digit\\n        assert manager._validate_key(\\\"a\\\") is True  # Single letter\\n        assert manager._validate_key(\\\"Z\\\") is True  # Single capital letter\\n        assert manager._validate_key(\\\"\\\") is False  # Empty string\\n        assert manager._validate_key(\\\" \\\") is False  # Single space\\n\\n    def test_concurrent_worker_locks_same_key(self):\\n        \\\"\\\"\\\"Test that multiple workers with same key are serialized.\\\"\\\"\\\"\\n        manager = KeyedWorkerLockManager()\\n        results = []\\n\\n        def worker(worker_id):\\n            try:\\n                with manager.lock(\\\"shared_worker_key\\\"):\\n                    results.append(f\\\"worker_{worker_id}_start\\\")\\n                    time.sleep(0.01)\\n                    results.append(f\\\"worker_{worker_id}_end\\\")\\n            except Exception:\\n                # Skip the test if file locking is not available in test environment\\n                results.append(f\\\"worker_{worker_id}_skipped\\\")\\n\\n        threads = []\\n        for i in range(2):\\n            thread = threading.Thread(target=worker, args=(i,))\\n            threads.append(thread)\\n            thread.start()\\n\\n        for thread in threads:\\n            thread.join()\\n\\n        # If file locking worked, should be serialized\\n        # If not available, workers would be skipped\\n        if \\\"skipped\\\" not in \\\"\\\".join(results):\\n            assert len(results) == 4\\n            # Each worker should complete before the next starts\\n            assert results[0].endswith(\\\"_start\\\")\\n            assert results[1].endswith(\\\"_end\\\")\\n            assert results[2].endswith(\\\"_start\\\")\\n            assert results[3].endswith(\\\"_end\\\")\\n\\n    @patch(\\\"lfx.utils.concurrency.user_cache_dir\\\")\\n    def test_locks_directory_creation(self, mock_cache_dir):\\n        \\\"\\\"\\\"Test that locks directory is created properly.\\\"\\\"\\\"\\n        mock_cache_dir.return_value = \\\"/test/cache\\\"\\n\\n        with patch(\\\"lfx.utils.concurrency.Path\\\") as mock_path:\\n            mock_path_instance = MagicMock()\\n            mock_path.return_value = mock_path_instance\\n\\n            KeyedWorkerLockManager()\\n\\n            # Verify user_cache_dir was called with ensure_exists=True\\n            mock_cache_dir.assert_called_once_with(\\\"langflow\\\", ensure_exists=True)\\n            # Verify Path was called correctly\\n            mock_path.assert_called_once_with(\\\"/test/cache\\\")\\n            mock_path_instance.__truediv__.assert_called_once_with(\\\"worker_locks\\\")\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/utils/test_connection_string_parser.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"0c1756f0b8fa28461a75d29444f5039c8e640a56e4dbc9ec2b5d31c1a8e539d0\",\"content\":\"from langflow.utils import connection_string_parser as langflow_parser\\nfrom lfx.utils import connection_string_parser as lfx_parser\\n\\n\\ndef test_langflow_reexports_lfx_helper():\\n    \\\"\\\"\\\"The langflow module is a shim; behavior is tested in src/lfx/tests/unit/utils.\\\"\\\"\\\"\\n    assert langflow_parser.transform_connection_string is lfx_parser.transform_connection_string\\n    assert langflow_parser.transform_connection_string(\\\"protocol:user:p/ss@host\\\") == \\\"protocol:user:p%2Fss@host\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/utils/test_data_structure.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"79c161dbdb4aa5bc1eacb68f2b2973244e802b194391294fce051ac2966f238a\",\"content\":\"from unittest.mock import Mock\\n\\nfrom langflow.schema.data import Data\\nfrom langflow.utils.data_structure import (\\n    analyze_value,\\n    get_data_structure,\\n    get_sample_values,\\n    get_type_str,\\n    infer_list_type,\\n)\\n\\n\\nclass TestInferListType:\\n    \\\"\\\"\\\"Test cases for infer_list_type function.\\\"\\\"\\\"\\n\\n    def test_empty_list(self):\\n        \\\"\\\"\\\"Test empty list inference.\\\"\\\"\\\"\\n        result = infer_list_type([])\\n        assert result == \\\"list(unknown)\\\"\\n\\n    def test_single_type_list(self):\\n        \\\"\\\"\\\"Test list with single type.\\\"\\\"\\\"\\n        result = infer_list_type([1, 2, 3, 4])\\n        assert result == \\\"list(int)\\\"\\n\\n        result = infer_list_type([\\\"a\\\", \\\"b\\\", \\\"c\\\"])\\n        assert result == \\\"list(str)\\\"\\n\\n    def test_mixed_type_list(self):\\n        \\\"\\\"\\\"Test list with mixed types.\\\"\\\"\\\"\\n        result = infer_list_type([1, \\\"hello\\\", 3.14])\\n        assert \\\"list(\\\" in result\\n        assert \\\"|\\\" in result  # Should show mixed types\\n        assert \\\"int\\\" in result\\n        assert \\\"str\\\" in result\\n        assert \\\"float\\\" in result\\n\\n    def test_max_samples_limit(self):\\n        \\\"\\\"\\\"Test max_samples parameter.\\\"\\\"\\\"\\n        long_list = list(range(100))  # 100 integers\\n        result = infer_list_type(long_list, max_samples=3)\\n        assert result == \\\"list(int)\\\"\\n\\n    def test_boolean_list(self):\\n        \\\"\\\"\\\"Test list with boolean values.\\\"\\\"\\\"\\n        result = infer_list_type([True, False, True])\\n        assert result == \\\"list(bool)\\\"\\n\\n    def test_none_values_list(self):\\n        \\\"\\\"\\\"Test list with None values.\\\"\\\"\\\"\\n        result = infer_list_type([None, None, None])\\n        assert result == \\\"list(null)\\\"\\n\\n    def test_mixed_with_none(self):\\n        \\\"\\\"\\\"Test mixed list including None.\\\"\\\"\\\"\\n        result = infer_list_type([1, None, \\\"test\\\"])\\n        assert \\\"null\\\" in result\\n        assert \\\"int\\\" in result\\n        assert \\\"str\\\" in result\\n\\n\\nclass TestGetTypeStr:\\n    \\\"\\\"\\\"Test cases for get_type_str function.\\\"\\\"\\\"\\n\\n    def test_basic_types(self):\\n        \\\"\\\"\\\"Test basic Python types.\\\"\\\"\\\"\\n        assert get_type_str(None) == \\\"null\\\"\\n        assert get_type_str(True) == \\\"bool\\\"  # noqa: FBT003\\n        assert get_type_str(False) == \\\"bool\\\"  # noqa: FBT003\\n        assert get_type_str(42) == \\\"int\\\"\\n        assert get_type_str(3.14) == \\\"float\\\"\\n        assert get_type_str(\\\"hello\\\") == \\\"str\\\"\\n\\n    def test_collection_types(self):\\n        \\\"\\\"\\\"Test collection types.\\\"\\\"\\\"\\n        result = get_type_str([1, 2, 3])\\n        assert result == \\\"list(int)\\\"\\n\\n        result = get_type_str((1, 2, 3))\\n        assert result == \\\"list(int)\\\"\\n\\n        result = get_type_str({1, 2, 3})\\n        assert result == \\\"list(int)\\\"\\n\\n        result = get_type_str({\\\"key\\\": \\\"value\\\"})\\n        assert result == \\\"dict\\\"\\n\\n    def test_date_string_detection(self):\\n        \\\"\\\"\\\"Test detection of date-like strings.\\\"\\\"\\\"\\n        # Strings that contain the date detection patterns\\n        date_strings = [\\n            \\\"this has a date in it\\\",\\n            \\\"time stamp here\\\",\\n            \\\"yyyy format string\\\",\\n            \\\"mm/dd format\\\",\\n            \\\"dd/mm format\\\",\\n            \\\"yyyy-mm format\\\",\\n        ]\\n\\n        for date_str in date_strings:\\n            result = get_type_str(date_str)\\n            assert result == \\\"str(possible_date)\\\"\\n\\n        # Test strings that don't match patterns\\n        non_date_strings = [\\\"2023-01-01\\\", \\\"January 1, 2023\\\", \\\"01/01/2023\\\"]\\n        for non_date_str in non_date_strings:\\n            result = get_type_str(non_date_str)\\n            assert result == \\\"str\\\"\\n\\n    def test_json_string_detection(self):\\n        \\\"\\\"\\\"Test detection of JSON strings.\\\"\\\"\\\"\\n        json_string = '{\\\"key\\\": \\\"value\\\", \\\"number\\\": 42}'\\n        result = get_type_str(json_string)\\n        assert result == \\\"str(json)\\\"\\n\\n        # Invalid JSON should be regular string\\n        invalid_json = '{\\\"key\\\": invalid}'\\n        result = get_type_str(invalid_json)\\n        assert result == \\\"str\\\"\\n\\n    def test_custom_objects(self):\\n        \\\"\\\"\\\"Test custom object type detection.\\\"\\\"\\\"\\n\\n        class CustomClass:\\n            pass\\n\\n        obj = CustomClass()\\n        result = get_type_str(obj)\\n        assert result == \\\"CustomClass\\\"\\n\\n    def test_regular_string(self):\\n        \\\"\\\"\\\"Test regular strings without special patterns.\\\"\\\"\\\"\\n        result = get_type_str(\\\"just a regular string\\\")\\n        assert result == \\\"str\\\"\\n\\n        result = get_type_str(\\\"no patterns here\\\")\\n        assert result == \\\"str\\\"\\n\\n\\nclass TestAnalyzeValue:\\n    \\\"\\\"\\\"Test cases for analyze_value function.\\\"\\\"\\\"\\n\\n    def test_simple_values(self):\\n        \\\"\\\"\\\"Test analysis of simple values.\\\"\\\"\\\"\\n        assert analyze_value(42) == \\\"int\\\"\\n        assert analyze_value(\\\"hello\\\") == \\\"str\\\"\\n        assert analyze_value(True) == \\\"bool\\\"  # noqa: FBT003\\n        assert analyze_value(None) == \\\"null\\\"\\n\\n    def test_simple_list(self):\\n        \\\"\\\"\\\"Test analysis of simple list.\\\"\\\"\\\"\\n        result = analyze_value([1, 2, 3])\\n        assert \\\"list(int)\\\" in result\\n        assert \\\"[size=3]\\\" in result\\n\\n    def test_empty_list(self):\\n        \\\"\\\"\\\"Test analysis of empty list.\\\"\\\"\\\"\\n        result = analyze_value([])\\n        assert result == \\\"list(unknown)\\\"\\n\\n    def test_nested_dict(self):\\n        \\\"\\\"\\\"Test analysis of nested dictionary.\\\"\\\"\\\"\\n        nested_data = {\\\"name\\\": \\\"John\\\", \\\"age\\\": 30, \\\"scores\\\": [95, 87, 92]}\\n\\n        result = analyze_value(nested_data)\\n\\n        assert isinstance(result, dict)\\n        assert result[\\\"name\\\"] == \\\"str\\\"\\n        assert result[\\\"age\\\"] == \\\"int\\\"\\n        assert \\\"list(int)\\\" in result[\\\"scores\\\"]\\n\\n    def test_max_depth_limit(self):\\n        \\\"\\\"\\\"Test max depth limitation.\\\"\\\"\\\"\\n        deeply_nested = {\\\"level1\\\": {\\\"level2\\\": {\\\"level3\\\": {\\\"level4\\\": \\\"deep\\\"}}}}\\n\\n        result = analyze_value(deeply_nested, max_depth=2)\\n\\n        # Should reach max depth at some point\\n        assert \\\"max_depth_reached\\\" in str(result)\\n\\n    def test_size_hints_disabled(self):\\n        \\\"\\\"\\\"Test with size hints disabled.\\\"\\\"\\\"\\n        result = analyze_value([1, 2, 3], size_hints=False)\\n        assert \\\"list(int)\\\" in result\\n        assert \\\"[size=\\\" not in result\\n\\n    def test_include_samples_for_complex_list(self):\\n        \\\"\\\"\\\"Test sample inclusion for complex list structures.\\\"\\\"\\\"\\n        complex_list = [{\\\"name\\\": \\\"John\\\", \\\"age\\\": 30}, {\\\"name\\\": \\\"Jane\\\", \\\"age\\\": 25}]\\n\\n        result = analyze_value(complex_list, include_samples=True)\\n\\n        assert \\\"sample:\\\" in result\\n        assert \\\"list(dict)\\\" in result\\n\\n    def test_include_samples_disabled(self):\\n        \\\"\\\"\\\"Test with samples disabled.\\\"\\\"\\\"\\n        complex_list = [{\\\"name\\\": \\\"John\\\", \\\"age\\\": 30}, {\\\"name\\\": \\\"Jane\\\", \\\"age\\\": 25}]\\n\\n        result = analyze_value(complex_list, include_samples=False)\\n\\n        assert \\\"sample:\\\" not in result\\n\\n    def test_error_handling(self):\\n        \\\"\\\"\\\"Test error handling in analysis.\\\"\\\"\\\"\\n\\n        # Create an object that raises exception on access\\n        class ProblematicClass:\\n            def __getitem__(self, key):\\n                msg = \\\"Access error\\\"\\n                raise RuntimeError(msg)\\n\\n        problematic = ProblematicClass()\\n        result = analyze_value(problematic)\\n\\n        assert \\\"ProblematicClass\\\" in result or \\\"error(\\\" in result\\n\\n    def test_tuple_and_set_handling(self):\\n        \\\"\\\"\\\"Test analysis of tuples and sets.\\\"\\\"\\\"\\n        tuple_result = analyze_value((1, 2, 3))\\n        assert \\\"list(int)\\\" in tuple_result\\n\\n        set_result = analyze_value({1, 2, 3})\\n        assert \\\"list(int)\\\" in set_result\\n\\n\\nclass TestGetDataStructure:\\n    \\\"\\\"\\\"Test cases for get_data_structure function.\\\"\\\"\\\"\\n\\n    def test_data_object_input(self):\\n        \\\"\\\"\\\"Test with Data object as input.\\\"\\\"\\\"\\n        mock_data = Mock(spec=Data)\\n        mock_data.data = {\\\"field\\\": \\\"value\\\"}\\n\\n        result = get_data_structure(mock_data)\\n\\n        assert \\\"structure\\\" in result\\n        assert isinstance(result[\\\"structure\\\"], dict)\\n        assert result[\\\"structure\\\"][\\\"field\\\"] == \\\"str\\\"\\n\\n    def test_dict_input(self):\\n        \\\"\\\"\\\"Test with dictionary as input.\\\"\\\"\\\"\\n        test_dict = {\\n            \\\"name\\\": \\\"Test\\\",\\n            \\\"count\\\": 42,\\n            \\\"items\\\": [1, 2, 3],\\n            \\\"metadata\\\": {\\n                \\\"created\\\": \\\"date created on server\\\",  # Contains \\\"date\\\" pattern\\n                \\\"tags\\\": [\\\"tag1\\\", \\\"tag2\\\"],\\n            },\\n        }\\n\\n        result = get_data_structure(test_dict)\\n\\n        assert \\\"structure\\\" in result\\n        structure = result[\\\"structure\\\"]\\n        assert structure[\\\"name\\\"] == \\\"str\\\"\\n        assert structure[\\\"count\\\"] == \\\"int\\\"\\n        assert \\\"list(int)\\\" in structure[\\\"items\\\"]\\n        assert isinstance(structure[\\\"metadata\\\"], dict)\\n        assert \\\"str(possible_date)\\\" in structure[\\\"metadata\\\"][\\\"created\\\"]\\n        assert \\\"list(str)\\\" in structure[\\\"metadata\\\"][\\\"tags\\\"]\\n\\n    def test_with_sample_values(self):\\n        \\\"\\\"\\\"Test including sample values.\\\"\\\"\\\"\\n        test_dict = {\\\"numbers\\\": [1, 2, 3, 4, 5], \\\"nested\\\": {\\\"key\\\": \\\"value\\\"}}\\n\\n        result = get_data_structure(test_dict, include_sample_values=True)\\n\\n        assert \\\"structure\\\" in result\\n        assert \\\"samples\\\" in result\\n        assert \\\"numbers\\\" in result[\\\"samples\\\"]\\n        assert \\\"nested\\\" in result[\\\"samples\\\"]\\n\\n    def test_max_depth_parameter(self):\\n        \\\"\\\"\\\"Test max_depth parameter.\\\"\\\"\\\"\\n        deeply_nested = {\\\"level1\\\": {\\\"level2\\\": {\\\"level3\\\": {\\\"level4\\\": \\\"deep_value\\\"}}}}\\n\\n        result = get_data_structure(deeply_nested, max_depth=2)\\n\\n        # Should have limited depth in analysis\\n        structure = result[\\\"structure\\\"]\\n        assert \\\"level1\\\" in structure\\n        # Check that max depth was respected\\n        assert \\\"max_depth_reached\\\" in str(structure)\\n\\n    def test_size_hints_disabled(self):\\n        \\\"\\\"\\\"Test with size hints disabled.\\\"\\\"\\\"\\n        test_dict = {\\\"items\\\": [1, 2, 3, 4, 5]}\\n\\n        result = get_data_structure(test_dict, size_hints=False)\\n\\n        structure = result[\\\"structure\\\"]\\n        assert \\\"list(int)\\\" in structure[\\\"items\\\"]\\n        assert \\\"[size=\\\" not in structure[\\\"items\\\"]\\n\\n    def test_sample_structure_disabled(self):\\n        \\\"\\\"\\\"Test with sample structure disabled.\\\"\\\"\\\"\\n        test_dict = {\\\"complex_list\\\": [{\\\"a\\\": 1}, {\\\"b\\\": 2}]}\\n\\n        result = get_data_structure(test_dict, include_sample_structure=False)\\n\\n        structure = result[\\\"structure\\\"]\\n        assert \\\"sample:\\\" not in structure[\\\"complex_list\\\"]\\n\\n    def test_max_sample_size(self):\\n        \\\"\\\"\\\"Test max_sample_size parameter.\\\"\\\"\\\"\\n        test_dict = {\\\"long_list\\\": list(range(10))}\\n\\n        result = get_data_structure(test_dict, include_sample_values=True, max_sample_size=3)\\n\\n        samples = result[\\\"samples\\\"]\\n        assert len(samples[\\\"long_list\\\"]) == 3\\n\\n\\nclass TestGetSampleValues:\\n    \\\"\\\"\\\"Test cases for get_sample_values function.\\\"\\\"\\\"\\n\\n    def test_simple_values(self):\\n        \\\"\\\"\\\"Test sampling simple values.\\\"\\\"\\\"\\n        assert get_sample_values(42) == 42\\n        assert get_sample_values(\\\"hello\\\") == \\\"hello\\\"\\n        assert get_sample_values(True) is True  # noqa: FBT003\\n\\n    def test_list_sampling(self):\\n        \\\"\\\"\\\"Test sampling from lists.\\\"\\\"\\\"\\n        long_list = list(range(10))\\n        result = get_sample_values(long_list, max_items=3)\\n\\n        assert len(result) == 3\\n        assert result == [0, 1, 2]\\n\\n    def test_tuple_sampling(self):\\n        \\\"\\\"\\\"Test sampling from tuples.\\\"\\\"\\\"\\n        test_tuple = tuple(range(5))\\n        result = get_sample_values(test_tuple, max_items=2)\\n\\n        assert len(result) == 2\\n        assert result == [0, 1]\\n\\n    def test_set_sampling(self):\\n        \\\"\\\"\\\"Test sampling from sets.\\\"\\\"\\\"\\n        test_set = {1, 2, 3, 4, 5}\\n        result = get_sample_values(test_set, max_items=3)\\n\\n        assert len(result) == 3\\n        # Order may vary for sets, but should contain elements from the set\\n        assert all(item in test_set for item in result)\\n\\n    def test_dict_sampling(self):\\n        \\\"\\\"\\\"Test sampling from dictionaries.\\\"\\\"\\\"\\n        test_dict = {\\\"list_field\\\": [1, 2, 3, 4, 5], \\\"simple_field\\\": \\\"value\\\", \\\"nested_dict\\\": {\\\"inner\\\": [10, 20, 30]}}\\n\\n        result = get_sample_values(test_dict, max_items=2)\\n\\n        assert isinstance(result, dict)\\n        assert \\\"simple_field\\\" in result\\n        assert result[\\\"simple_field\\\"] == \\\"value\\\"\\n        assert len(result[\\\"list_field\\\"]) == 2  # Should be limited by max_items\\n        assert len(result[\\\"nested_dict\\\"][\\\"inner\\\"]) == 2  # Nested sampling\\n\\n    def test_nested_structure_sampling(self):\\n        \\\"\\\"\\\"Test sampling from nested structures.\\\"\\\"\\\"\\n        nested_structure = {\\\"data\\\": [{\\\"items\\\": [1, 2, 3, 4, 5]}, {\\\"items\\\": [6, 7, 8, 9, 10]}]}\\n\\n        result = get_sample_values(nested_structure, max_items=2)\\n\\n        assert len(result[\\\"data\\\"]) == 2\\n        # The function recursively applies max_items at each level\\n        # But the nested dictionaries are returned as-is, then their contents are sampled\\n        # Let's just verify the structure is correct without specific lengths\\n        assert \\\"items\\\" in result[\\\"data\\\"][0]\\n        assert \\\"items\\\" in result[\\\"data\\\"][1]\\n        assert isinstance(result[\\\"data\\\"][0][\\\"items\\\"], list)\\n        assert isinstance(result[\\\"data\\\"][1][\\\"items\\\"], list)\\n\\n    def test_empty_collections(self):\\n        \\\"\\\"\\\"Test sampling from empty collections.\\\"\\\"\\\"\\n        assert get_sample_values([]) == []\\n        assert get_sample_values({}) == {}\\n        assert get_sample_values(set()) == []\\n\\n    def test_max_items_larger_than_collection(self):\\n        \\\"\\\"\\\"Test when max_items is larger than collection size.\\\"\\\"\\\"\\n        small_list = [1, 2]\\n        result = get_sample_values(small_list, max_items=10)\\n\\n        assert result == [1, 2]  # Should return all items\\n\\n\\nclass TestIntegrationScenarios:\\n    \\\"\\\"\\\"Integration test cases for complex data structures.\\\"\\\"\\\"\\n\\n    def test_real_world_api_response(self):\\n        \\\"\\\"\\\"Test analysis of realistic API response structure.\\\"\\\"\\\"\\n        api_response = {\\n            \\\"status\\\": \\\"success\\\",\\n            \\\"data\\\": {\\n                \\\"users\\\": [\\n                    {\\n                        \\\"id\\\": 1,\\n                        \\\"name\\\": \\\"John Doe\\\",\\n                        \\\"email\\\": \\\"john@example.com\\\",\\n                        \\\"created_at\\\": \\\"2023-01-15T10:30:00Z\\\",\\n                        \\\"metadata\\\": {\\\"login_count\\\": 42, \\\"preferences\\\": {\\\"theme\\\": \\\"dark\\\", \\\"notifications\\\": True}},\\n                    },\\n                    {\\n                        \\\"id\\\": 2,\\n                        \\\"name\\\": \\\"Jane Smith\\\",\\n                        \\\"email\\\": \\\"jane@example.com\\\",\\n                        \\\"created_at\\\": \\\"2023-02-01T14:20:00Z\\\",\\n                        \\\"metadata\\\": {\\\"login_count\\\": 15, \\\"preferences\\\": {\\\"theme\\\": \\\"light\\\", \\\"notifications\\\": False}},\\n                    },\\n                ],\\n                \\\"pagination\\\": {\\\"page\\\": 1, \\\"per_page\\\": 10, \\\"total\\\": 2},\\n            },\\n        }\\n\\n        result = get_data_structure(api_response, include_sample_values=True, include_sample_structure=True)\\n\\n        assert \\\"structure\\\" in result\\n        assert \\\"samples\\\" in result\\n\\n        structure = result[\\\"structure\\\"]\\n        assert structure[\\\"status\\\"] == \\\"str\\\"\\n        assert \\\"data\\\" in structure\\n        assert \\\"users\\\" in structure[\\\"data\\\"]\\n        assert \\\"list(dict)\\\" in structure[\\\"data\\\"][\\\"users\\\"]\\n\\n        # Check that pagination structure is captured\\n        pagination = structure[\\\"data\\\"][\\\"pagination\\\"]\\n        assert pagination[\\\"page\\\"] == \\\"int\\\"\\n        assert pagination[\\\"total\\\"] == \\\"int\\\"\\n\\n    def test_mixed_data_types_analysis(self):\\n        \\\"\\\"\\\"Test analysis of mixed data types.\\\"\\\"\\\"\\n        mixed_data = {\\n            \\\"strings\\\": [\\\"hello\\\", \\\"world\\\"],\\n            \\\"numbers\\\": [1, 2, 3.14, 5],\\n            \\\"booleans\\\": [True, False, True],\\n            \\\"mixed_list\\\": [1, \\\"hello\\\", True, None, {\\\"nested\\\": \\\"value\\\"}],\\n            \\\"json_strings\\\": ['{\\\"key\\\": \\\"value\\\"}', '{\\\"another\\\": \\\"json\\\"}'],\\n            \\\"dates\\\": [\\\"has date in string\\\", \\\"another time value\\\"],\\n            \\\"empty_structures\\\": {\\\"empty_list\\\": [], \\\"empty_dict\\\": {}},\\n        }\\n\\n        result = get_data_structure(mixed_data)\\n        structure = result[\\\"structure\\\"]\\n\\n        assert \\\"list(str)\\\" in structure[\\\"strings\\\"]\\n        assert \\\"int|float\\\" in structure[\\\"numbers\\\"] or \\\"float|int\\\" in structure[\\\"numbers\\\"]\\n        assert \\\"list(bool)\\\" in structure[\\\"booleans\\\"]\\n        # The mixed list types may be in any order, so just check it contains list() and multiple types\\n        mixed_list_str = structure[\\\"mixed_list\\\"]\\n        assert \\\"list(\\\" in mixed_list_str\\n        assert \\\"|\\\" in mixed_list_str  # Multiple types indicated by pipe\\n        assert \\\"str(json)\\\" in structure[\\\"json_strings\\\"]\\n        assert \\\"str(possible_date)\\\" in structure[\\\"dates\\\"]\\n        assert structure[\\\"empty_structures\\\"][\\\"empty_list\\\"] == \\\"list(unknown)\\\"\\n        assert structure[\\\"empty_structures\\\"][\\\"empty_dict\\\"] == {}\\n\\n    def test_deep_nesting_with_max_depth(self):\\n        \\\"\\\"\\\"Test deeply nested structure with depth limits.\\\"\\\"\\\"\\n\\n        def create_deep_structure(depth):\\n            if depth == 0:\\n                return \\\"leaf_value\\\"\\n            return {\\\"level\\\": depth, \\\"nested\\\": create_deep_structure(depth - 1)}\\n\\n        deep_data = create_deep_structure(10)\\n\\n        result = get_data_structure(deep_data, max_depth=5)\\n\\n        # Should handle deep nesting gracefully\\n        assert \\\"structure\\\" in result\\n        assert \\\"max_depth_reached\\\" in str(result[\\\"structure\\\"])\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/utils/test_format_directory_path.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"c43b199cb61d371313017dfbda26ffb4919409aedd06457f3be226ccea0bc628\",\"content\":\"import pytest\\nfrom lfx.base.data.utils import format_directory_path\\n\\n\\n@pytest.mark.parametrize(\\n    (\\\"input_path\\\", \\\"expected\\\"),\\n    [\\n        # Test case 1: Standard path with no newlines (no change expected)\\n        (\\\"/home/user/documents/file.txt\\\", \\\"/home/user/documents/file.txt\\\"),\\n        # Test case 2: Path with newline character (replace \\\\n with \\\\\\\\n)\\n        (\\\"/home/user/docu\\\\nments/file.txt\\\", \\\"/home/user/docu\\\\\\\\nments/file.txt\\\"),\\n        # Test case 3: Path with multiple newline characters\\n        (\\\"/home/user/\\\\ndocu\\\\nments/file.txt\\\", \\\"/home/user/\\\\\\\\ndocu\\\\\\\\nments/file.txt\\\"),\\n        # Test case 4: Path with only newline characters\\n        (\\\"\\\\n\\\\n\\\\n\\\", \\\"\\\\\\\\n\\\\\\\\n\\\\\\\\n\\\"),\\n        # Test case 5: Empty path (as per the original function, this remains an empty string)\\n        (\\\"\\\", \\\"\\\"),\\n        # Test case 6: Path with mixed newlines and other special characters\\n        (\\\"/home/user/my-\\\\ndocs/special_file!.pdf\\\", \\\"/home/user/my-\\\\\\\\ndocs/special_file!.pdf\\\"),\\n        # Test case 7: Windows-style path with newline\\n        (\\\"C:\\\\\\\\Users\\\\\\\\\\\\nDocuments\\\\\\\\file.txt\\\", \\\"C:\\\\\\\\Users\\\\\\\\\\\\\\\\nDocuments\\\\\\\\file.txt\\\"),  # No conversion of backslashes\\n        # Test case 8: Path with trailing newline\\n        (\\\"/home/user/documents/\\\\n\\\", \\\"/home/user/documents/\\\\\\\\n\\\"),\\n        # Test case 9: Path with leading newline\\n        (\\\"\\\\n/home/user/documents/\\\", \\\"\\\\\\\\n/home/user/documents/\\\"),\\n        # Test case 10: Path with multiple consecutive newlines\\n        (\\\"/home/user/docu\\\\n\\\\nments/file.txt\\\", \\\"/home/user/docu\\\\\\\\n\\\\\\\\nments/file.txt\\\"),\\n        # Test case 11: Windows-style path (backslashes remain unchanged)\\n        (\\\"C:\\\\\\\\Users\\\\\\\\Documents\\\\\\\\file.txt\\\", \\\"C:\\\\\\\\Users\\\\\\\\Documents\\\\\\\\file.txt\\\"),\\n        # Test case 12: Windows path with trailing backslash\\n        (\\\"C:\\\\\\\\Users\\\\\\\\Documents\\\\\\\\\\\", \\\"C:\\\\\\\\Users\\\\\\\\Documents\\\\\\\\\\\"),\\n        # Test case 13: Mixed separators (leave as is)\\n        (\\\"C:/Users\\\\\\\\Documents/file.txt\\\", \\\"C:/Users\\\\\\\\Documents/file.txt\\\"),\\n        # Test case 14: Network path (UNC) (leave backslashes as is)\\n        (\\\"\\\\\\\\\\\\\\\\server\\\\\\\\share\\\\\\\\file.txt\\\", \\\"\\\\\\\\\\\\\\\\server\\\\\\\\share\\\\\\\\file.txt\\\"),\\n    ],\\n)\\ndef test_format_directory_path(input_path, expected):\\n    result = format_directory_path(input_path)\\n    assert result == expected\\n\\n\\n# Additional test for type checking\\ndef test_format_directory_path_type():\\n    result = format_directory_path(\\\"/home/user/file.txt\\\")\\n    assert isinstance(result, str)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/utils/test_image_utils.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"9dd0b01ff4a28d1c4c574abd754329c33a6bad42900491f7ddf8b3f88c3e7d26\",\"content\":\"import base64\\n\\nimport pytest\\nfrom langflow.utils.image import convert_image_to_base64, create_data_url, create_image_content_dict\\n\\n\\n@pytest.fixture\\ndef sample_image(tmp_path):\\n    \\\"\\\"\\\"Create a sample image file for testing.\\\"\\\"\\\"\\n    image_path = tmp_path / \\\"test_image.png\\\"\\n    # Create a small black 1x1 pixel PNG file\\n    image_content = base64.b64decode(\\n        \\\"iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAACklEQVR4nGMAAQAABQABDQottAAAAABJRU5ErkJggg==\\\"\\n    )\\n    image_path.write_bytes(image_content)\\n    return image_path\\n\\n\\ndef test_convert_image_to_base64_success(sample_image):\\n    \\\"\\\"\\\"Test successful conversion of image to base64.\\\"\\\"\\\"\\n    base64_str = convert_image_to_base64(sample_image)\\n    assert isinstance(base64_str, str)\\n    # Verify it's valid base64\\n    assert base64.b64decode(base64_str)\\n\\n\\ndef test_convert_image_to_base64_empty_path():\\n    \\\"\\\"\\\"Test conversion with empty path.\\\"\\\"\\\"\\n    with pytest.raises(ValueError, match=\\\"Image path cannot be empty\\\"):\\n        convert_image_to_base64(\\\"\\\")\\n\\n\\ndef test_convert_image_to_base64_nonexistent_file():\\n    \\\"\\\"\\\"Test conversion with non-existent file.\\\"\\\"\\\"\\n    with pytest.raises(FileNotFoundError, match=\\\"Image file not found\\\"):\\n        convert_image_to_base64(\\\"nonexistent.png\\\")\\n\\n\\ndef test_convert_image_to_base64_directory(tmp_path):\\n    \\\"\\\"\\\"Test conversion with directory path instead of file.\\\"\\\"\\\"\\n    with pytest.raises(ValueError, match=\\\"Path is not a file\\\"):\\n        convert_image_to_base64(tmp_path)\\n\\n\\ndef test_create_data_url_success(sample_image):\\n    \\\"\\\"\\\"Test successful creation of data URL.\\\"\\\"\\\"\\n    data_url = create_data_url(sample_image)\\n    assert data_url.startswith(\\\"data:image/png;base64,\\\")\\n    # Verify the base64 part is valid\\n    base64_part = data_url.split(\\\",\\\")[1]\\n    assert base64.b64decode(base64_part)\\n\\n\\ndef test_create_data_url_with_custom_mime(sample_image):\\n    \\\"\\\"\\\"Test creation of data URL with custom MIME type.\\\"\\\"\\\"\\n    custom_mime = \\\"image/custom\\\"\\n    data_url = create_data_url(sample_image, mime_type=custom_mime)\\n    assert data_url.startswith(f\\\"data:{custom_mime};base64,\\\")\\n\\n\\ndef test_create_data_url_invalid_file():\\n    \\\"\\\"\\\"Test creation of data URL with invalid file.\\\"\\\"\\\"\\n    with pytest.raises(FileNotFoundError):\\n        create_data_url(\\\"nonexistent.jpg\\\")\\n\\n\\ndef test_create_data_url_unrecognized_extension(tmp_path):\\n    \\\"\\\"\\\"Test creation of data URL with unrecognized file extension.\\\"\\\"\\\"\\n    invalid_file = tmp_path / \\\"test.unknown\\\"\\n    invalid_file.touch()\\n    with pytest.raises(ValueError, match=\\\"Could not determine MIME type\\\"):\\n        create_data_url(invalid_file)\\n\\n\\ndef test_create_image_content_dict_success(sample_image):\\n    \\\"\\\"\\\"Test successful creation of image content dict.\\\"\\\"\\\"\\n    content_dict = create_image_content_dict(sample_image)\\n    assert content_dict[\\\"type\\\"] == \\\"image_url\\\"\\n    assert \\\"image_url\\\" in content_dict\\n    assert \\\"url\\\" in content_dict[\\\"image_url\\\"]\\n    assert content_dict[\\\"image_url\\\"][\\\"url\\\"].startswith(\\\"data:image/png;base64,\\\")\\n    # Verify the base64 part is valid\\n    base64_part = content_dict[\\\"image_url\\\"][\\\"url\\\"].split(\\\",\\\")[1]\\n    assert base64.b64decode(base64_part)\\n\\n\\ndef test_create_image_content_dict_with_custom_mime(sample_image):\\n    \\\"\\\"\\\"Test creation of image content dict with custom MIME type.\\\"\\\"\\\"\\n    custom_mime = \\\"image/custom\\\"\\n    content_dict = create_image_content_dict(sample_image, mime_type=custom_mime)\\n    assert content_dict[\\\"type\\\"] == \\\"image_url\\\"\\n    assert \\\"image_url\\\" in content_dict\\n    assert \\\"url\\\" in content_dict[\\\"image_url\\\"]\\n    assert content_dict[\\\"image_url\\\"][\\\"url\\\"].startswith(f\\\"data:{custom_mime};base64,\\\")\\n\\n\\ndef test_create_image_content_dict_invalid_file():\\n    \\\"\\\"\\\"Test creation of image content dict with invalid file.\\\"\\\"\\\"\\n    with pytest.raises(FileNotFoundError):\\n        create_image_content_dict(\\\"nonexistent.jpg\\\")\\n\\n\\ndef test_create_image_content_dict_unrecognized_extension(tmp_path):\\n    \\\"\\\"\\\"Test creation of image content dict with unrecognized file extension.\\\"\\\"\\\"\\n    invalid_file = tmp_path / \\\"test.unknown\\\"\\n    invalid_file.touch()\\n    with pytest.raises(ValueError, match=\\\"Could not determine MIME type\\\"):\\n        create_image_content_dict(invalid_file)\\n\\n\\ndef test_create_image_content_dict_format_compatibility(sample_image):\\n    \\\"\\\"\\\"Test that the image content dict format is compatible with different LLM providers.\\\"\\\"\\\"\\n    content_dict = create_image_content_dict(sample_image)\\n\\n    # Test the new format structure that should work with Google/Gemini\\n    assert content_dict[\\\"type\\\"] == \\\"image_url\\\"\\n    assert \\\"image_url\\\" in content_dict\\n    assert isinstance(content_dict[\\\"image_url\\\"], dict)\\n    assert \\\"url\\\" in content_dict[\\\"image_url\\\"]\\n\\n    # Test that the URL is a valid data URL\\n    url = content_dict[\\\"image_url\\\"][\\\"url\\\"]\\n    assert url.startswith(\\\"data:\\\")\\n    assert \\\";base64,\\\" in url\\n\\n    # Verify the structure matches OpenAI's expected format\\n    # OpenAI expects: {\\\"type\\\": \\\"image_url\\\", \\\"image_url\\\": {\\\"url\\\": \\\"data:...\\\"}}\\n    assert all(key in [\\\"type\\\", \\\"image_url\\\"] for key in content_dict)\\n    assert all(key in [\\\"url\\\"] for key in content_dict[\\\"image_url\\\"])\\n\\n\\ndef test_image_content_dict_google_gemini_compatibility(sample_image):\\n    \\\"\\\"\\\"Test that the format resolves the original Gemini error.\\\"\\\"\\\"\\n    content_dict = create_image_content_dict(sample_image)\\n\\n    # The original error was: \\\"Unrecognized message part type: image\\\"\\n    # This should now be \\\"image_url\\\" which Gemini supports\\n    assert content_dict[\\\"type\\\"] == \\\"image_url\\\"\\n\\n    # Gemini should accept this format without the \\\"source_type\\\" field\\n    # that was causing issues in the old format\\n    assert \\\"source_type\\\" not in content_dict\\n\\n    # The nested structure should match what Gemini expects\\n    assert \\\"image_url\\\" in content_dict\\n    assert \\\"url\\\" in content_dict[\\\"image_url\\\"]\\n\\n\\ndef test_image_content_dict_openai_compatibility(sample_image):\\n    \\\"\\\"\\\"Test compatibility with OpenAI's expected image format.\\\"\\\"\\\"\\n    content_dict = create_image_content_dict(sample_image)\\n\\n    # OpenAI Vision API expects exactly this structure:\\n    # {\\\"type\\\": \\\"image_url\\\", \\\"image_url\\\": {\\\"url\\\": \\\"data:image/jpeg;base64,...\\\"}}\\n    expected_keys = {\\\"type\\\", \\\"image_url\\\"}\\n    assert set(content_dict.keys()) == expected_keys\\n\\n    assert content_dict[\\\"type\\\"] == \\\"image_url\\\"\\n    assert isinstance(content_dict[\\\"image_url\\\"], dict)\\n    assert \\\"url\\\" in content_dict[\\\"image_url\\\"]\\n\\n    # OpenAI accepts data URLs with base64 encoding\\n    url = content_dict[\\\"image_url\\\"][\\\"url\\\"]\\n    assert url.startswith(\\\"data:image/\\\")\\n    assert \\\";base64,\\\" in url\\n\\n\\ndef test_image_content_dict_anthropic_compatibility(sample_image):\\n    \\\"\\\"\\\"Test compatibility with Anthropic's expected image format.\\\"\\\"\\\"\\n    content_dict = create_image_content_dict(sample_image)\\n\\n    # Anthropic Claude also uses the image_url format for vision\\n    # This format should be compatible\\n    assert content_dict[\\\"type\\\"] == \\\"image_url\\\"\\n    assert \\\"image_url\\\" in content_dict\\n\\n    # Anthropic accepts base64 data URLs\\n    url = content_dict[\\\"image_url\\\"][\\\"url\\\"]\\n    assert url.startswith(\\\"data:\\\")\\n    assert \\\"base64\\\" in url\\n\\n\\ndef test_image_content_dict_langchain_message_compatibility(sample_image):\\n    \\\"\\\"\\\"Test that the format integrates well with LangChain message structures.\\\"\\\"\\\"\\n    content_dict = create_image_content_dict(sample_image)\\n\\n    # Simulate how this would be used in a LangChain message\\n    message_content = [{\\\"type\\\": \\\"text\\\", \\\"text\\\": \\\"What do you see in this image?\\\"}, content_dict]\\n\\n    # Verify the message structure is valid\\n    text_part = message_content[0]\\n    image_part = message_content[1]\\n\\n    assert text_part[\\\"type\\\"] == \\\"text\\\"\\n    assert image_part[\\\"type\\\"] == \\\"image_url\\\"\\n    assert \\\"image_url\\\" in image_part\\n    assert \\\"url\\\" in image_part[\\\"image_url\\\"]\\n\\n\\ndef test_image_content_dict_no_legacy_fields(sample_image):\\n    \\\"\\\"\\\"Test that legacy fields that caused issues are not present.\\\"\\\"\\\"\\n    content_dict = create_image_content_dict(sample_image)\\n\\n    # These fields from the old format should not be present\\n    # as they caused compatibility issues with some providers\\n    legacy_fields = [\\\"source_type\\\", \\\"source\\\", \\\"media_type\\\"]\\n\\n    for field in legacy_fields:\\n        assert field not in content_dict, f\\\"Legacy field '{field}' should not be present\\\"\\n        assert field not in content_dict.get(\\\"image_url\\\", {}), f\\\"Legacy field '{field}' should not be in image_url\\\"\\n\\n\\ndef test_image_content_dict_multiple_formats(tmp_path):\\n    \\\"\\\"\\\"Test that the format works consistently across different image types.\\\"\\\"\\\"\\n    # Test with different image formats\\n    formats_to_test = [\\n        (\\\"test.png\\\", \\\"image/png\\\"),\\n        (\\\"test.jpg\\\", \\\"image/jpeg\\\"),\\n        (\\\"test.gif\\\", \\\"image/gif\\\"),\\n        (\\\"test.webp\\\", \\\"image/webp\\\"),\\n    ]\\n\\n    # Use the same image content for all formats (the test PNG data)\\n    image_content = base64.b64decode(\\n        \\\"iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAACklEQVR4nGMAAQAABQABDQottAAAAABJRU5ErkJggg==\\\"\\n    )\\n\\n    for filename, expected_mime in formats_to_test:\\n        image_path = tmp_path / filename\\n        image_path.write_bytes(image_content)\\n\\n        try:\\n            content_dict = create_image_content_dict(image_path)\\n\\n            # All formats should produce the same structure\\n            assert content_dict[\\\"type\\\"] == \\\"image_url\\\"\\n            assert \\\"image_url\\\" in content_dict\\n            assert \\\"url\\\" in content_dict[\\\"image_url\\\"]\\n\\n            # The MIME type should be detected correctly\\n            url = content_dict[\\\"image_url\\\"][\\\"url\\\"]\\n            assert url.startswith(f\\\"data:{expected_mime};base64,\\\")\\n\\n        except ValueError as e:\\n            # Some formats might not be supported, which is fine\\n            if \\\"Could not determine MIME type\\\" not in str(e):\\n                raise\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/utils/test_interface_utils.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"d23234e07c9af3a1ca4b3a8fa36b1fd879ab76cd608bbb8026996d33d12112e8\",\"content\":\"import pytest\\nfrom langflow.interface.utils import extract_input_variables_from_prompt\\n\\n\\n@pytest.mark.parametrize(\\n    (\\\"prompt\\\", \\\"expected\\\"),\\n    [\\n        # Basic variable extraction\\n        (\\\"Hello {name}!\\\", [\\\"name\\\"]),\\n        (\\\"Hi {name}, you are {age} years old\\\", [\\\"name\\\", \\\"age\\\"]),\\n        # Empty prompt\\n        (\\\"\\\", []),\\n        (\\\"No variables here\\\", []),\\n        # Duplicate variables\\n        (\\\"Hello {name}! How are you {name}?\\\", [\\\"name\\\"]),\\n        # Whitespace handling - Formatter preserves whitespace in field names\\n        (\\\"Hello { name }!\\\", [\\\" name \\\"]),\\n        (\\\"Hi {  name  }, bye\\\", [\\\"  name  \\\"]),\\n        # Multiple braces (escaping)\\n        (\\\"Escaped {{not_a_var}}\\\", []),\\n        (\\\"Mixed {{escaped}} and {real_var}\\\", [\\\"real_var\\\"]),\\n        (\\\"Double escaped {{{{not_this}}}}\\\", []),\\n        # Complex cases\\n        (\\\"Hello {name}! Your score is {{4 + 5}}, age: {age}\\\", [\\\"name\\\", \\\"age\\\"]),\\n        (\\\"Nested {{obj['key']}} with {normal_var}\\\", [\\\"normal_var\\\"]),\\n        (\\\"Template {{user.name}} with {id} and {type}\\\", [\\\"id\\\", \\\"type\\\"]),\\n        # Edge cases\\n        (\\\"{single}\\\", [\\\"single\\\"]),\\n        (\\\"{{double}}\\\", []),\\n        (\\\"{{{}}}\\\", []),\\n        # Multiple variables with various spacing\\n        (\\n            \\\"\\\"\\\"\\n        Multi-line with {var1}\\n        and {var2} plus\\n        {var3} at the end\\n        \\\"\\\"\\\",\\n            [\\\"var1\\\", \\\"var2\\\", \\\"var3\\\"],\\n        ),\\n    ],\\n)\\ndef test_extract_input_variables(prompt, expected):\\n    \\\"\\\"\\\"Test the extract_input_variables_from_prompt function with various cases.\\\"\\\"\\\"\\n    result = extract_input_variables_from_prompt(prompt)\\n    assert sorted(result) == sorted(expected), f\\\"Failed for prompt: {prompt}\\\"\\n\\n\\n@pytest.mark.parametrize(\\n    (\\\"prompt\\\", \\\"expected_error\\\"),\\n    [\\n        # Malformed format strings that should raise ValueError\\n        (\\\"}{\\\", \\\"Single '}' encountered in format string\\\"),\\n        (\\\"{incomplete\\\", \\\"expected '}' before end of string\\\"),\\n        (\\\"incomplete}\\\", \\\"Single '}' encountered in format string\\\"),\\n    ],\\n)\\ndef test_extract_input_variables_malformed(prompt, expected_error):\\n    \\\"\\\"\\\"Test that malformed format strings raise ValueError.\\\"\\\"\\\"\\n    with pytest.raises(ValueError, match=expected_error):\\n        extract_input_variables_from_prompt(prompt)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/utils/test_lazy_load.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"395f4436d9b41f31012adb3cd16f2e67a65e917de6fc05ee873f6612a7686514\",\"content\":\"import pytest\\nfrom langflow.utils.lazy_load import LazyLoadDictBase\\n\\n\\nclass TestLazyLoadDictBase:\\n    \\\"\\\"\\\"Test cases for LazyLoadDictBase class.\\\"\\\"\\\"\\n\\n    class ConcreteLazyLoad(LazyLoadDictBase):\\n        \\\"\\\"\\\"Concrete implementation for testing.\\\"\\\"\\\"\\n\\n        def __init__(self, build_dict_return=\\\"__default__\\\", get_type_dict_return=None):\\n            super().__init__()\\n            if build_dict_return == \\\"__default__\\\":\\n                self.build_dict_return = {\\\"test\\\": \\\"value\\\"}\\n            else:\\n                self.build_dict_return = build_dict_return\\n            self.get_type_dict_return = get_type_dict_return or {\\\"type\\\": \\\"dict\\\"}\\n            self.build_dict_call_count = 0\\n\\n        def _build_dict(self):\\n            self.build_dict_call_count += 1\\n            return self.build_dict_return\\n\\n        def get_type_dict(self):\\n            return self.get_type_dict_return\\n\\n    def test_lazy_load_dict_base_initialization(self):\\n        \\\"\\\"\\\"Test proper initialization of LazyLoadDictBase.\\\"\\\"\\\"\\n        lazy_load = self.ConcreteLazyLoad()\\n\\n        assert lazy_load._all_types_dict is None\\n        assert lazy_load.build_dict_call_count == 0\\n\\n    def test_all_types_dict_lazy_loading(self):\\n        \\\"\\\"\\\"Test that all_types_dict is loaded lazily.\\\"\\\"\\\"\\n        test_dict = {\\\"key1\\\": \\\"value1\\\", \\\"key2\\\": \\\"value2\\\"}\\n        lazy_load = self.ConcreteLazyLoad(build_dict_return=test_dict)\\n\\n        # First access should trigger _build_dict\\n        result = lazy_load.all_types_dict\\n\\n        assert result == test_dict\\n        assert lazy_load.build_dict_call_count == 1\\n        assert lazy_load._all_types_dict == test_dict\\n\\n    def test_all_types_dict_caching(self):\\n        \\\"\\\"\\\"Test that all_types_dict is cached after first access.\\\"\\\"\\\"\\n        test_dict = {\\\"cached\\\": \\\"value\\\"}\\n        lazy_load = self.ConcreteLazyLoad(build_dict_return=test_dict)\\n\\n        # First access\\n        result1 = lazy_load.all_types_dict\\n        # Second access\\n        result2 = lazy_load.all_types_dict\\n\\n        assert result1 == test_dict\\n        assert result2 == test_dict\\n        assert result1 is result2  # Same object reference\\n        assert lazy_load.build_dict_call_count == 1  # Only called once\\n\\n    def test_all_types_dict_multiple_accesses(self):\\n        \\\"\\\"\\\"Test multiple accesses to all_types_dict property.\\\"\\\"\\\"\\n        test_dict = {\\\"multi\\\": \\\"access\\\", \\\"test\\\": \\\"value\\\"}\\n        lazy_load = self.ConcreteLazyLoad(build_dict_return=test_dict)\\n\\n        # Multiple accesses\\n        for _ in range(5):\\n            result = lazy_load.all_types_dict\\n            assert result == test_dict\\n\\n        # _build_dict should only be called once\\n        assert lazy_load.build_dict_call_count == 1\\n\\n    def test_build_dict_not_implemented_error(self):\\n        \\\"\\\"\\\"Test that _build_dict raises NotImplementedError in base class.\\\"\\\"\\\"\\n        base = LazyLoadDictBase()\\n\\n        with pytest.raises(NotImplementedError):\\n            base._build_dict()\\n\\n    def test_get_type_dict_not_implemented_error(self):\\n        \\\"\\\"\\\"Test that get_type_dict raises NotImplementedError in base class.\\\"\\\"\\\"\\n        base = LazyLoadDictBase()\\n\\n        with pytest.raises(NotImplementedError):\\n            base.get_type_dict()\\n\\n    def test_get_type_dict_implementation(self):\\n        \\\"\\\"\\\"Test that get_type_dict works correctly in concrete implementation.\\\"\\\"\\\"\\n        type_dict = {\\\"component\\\": \\\"type\\\", \\\"data\\\": \\\"structure\\\"}\\n        lazy_load = self.ConcreteLazyLoad(get_type_dict_return=type_dict)\\n\\n        result = lazy_load.get_type_dict()\\n\\n        assert result == type_dict\\n\\n    def test_all_types_dict_with_empty_dict(self):\\n        \\\"\\\"\\\"Test all_types_dict with empty dictionary from _build_dict.\\\"\\\"\\\"\\n        lazy_load = self.ConcreteLazyLoad(build_dict_return={})\\n\\n        result = lazy_load.all_types_dict\\n\\n        assert result == {}\\n        assert lazy_load.build_dict_call_count == 1\\n\\n    def test_all_types_dict_with_none_from_build_dict(self):\\n        \\\"\\\"\\\"Test all_types_dict when _build_dict returns None.\\\"\\\"\\\"\\n        lazy_load = self.ConcreteLazyLoad(build_dict_return=None)\\n\\n        result = lazy_load.all_types_dict\\n\\n        assert result is None\\n        assert lazy_load.build_dict_call_count == 1\\n\\n    def test_all_types_dict_with_complex_data(self):\\n        \\\"\\\"\\\"Test all_types_dict with complex nested data structures.\\\"\\\"\\\"\\n        complex_dict = {\\n            \\\"components\\\": {\\\"llm\\\": [\\\"OpenAI\\\", \\\"Anthropic\\\"], \\\"tools\\\": {\\\"python\\\": \\\"PythonTool\\\", \\\"api\\\": \\\"APITool\\\"}},\\n            \\\"metadata\\\": {\\\"version\\\": \\\"1.0\\\", \\\"updated\\\": \\\"2023-01-01\\\"},\\n        }\\n        lazy_load = self.ConcreteLazyLoad(build_dict_return=complex_dict)\\n\\n        result = lazy_load.all_types_dict\\n\\n        assert result == complex_dict\\n        assert result[\\\"components\\\"][\\\"llm\\\"] == [\\\"OpenAI\\\", \\\"Anthropic\\\"]\\n        assert result[\\\"components\\\"][\\\"tools\\\"][\\\"python\\\"] == \\\"PythonTool\\\"\\n        assert lazy_load.build_dict_call_count == 1\\n\\n    def test_inheritance_behavior(self):\\n        \\\"\\\"\\\"Test that inheritance works properly.\\\"\\\"\\\"\\n\\n        class CustomLazyLoad(LazyLoadDictBase):\\n            def _build_dict(self):\\n                return {\\\"custom\\\": \\\"implementation\\\"}\\n\\n            def get_type_dict(self):\\n                return {\\\"custom\\\": \\\"type_dict\\\"}\\n\\n        custom = CustomLazyLoad()\\n\\n        assert custom.all_types_dict == {\\\"custom\\\": \\\"implementation\\\"}\\n        assert custom.get_type_dict() == {\\\"custom\\\": \\\"type_dict\\\"}\\n\\n    def test_all_types_dict_property_behavior(self):\\n        \\\"\\\"\\\"Test that all_types_dict behaves as a proper property.\\\"\\\"\\\"\\n        lazy_load = self.ConcreteLazyLoad(build_dict_return={\\\"prop\\\": \\\"test\\\"})\\n\\n        # Check that it's a property and not a method\\n        assert hasattr(type(lazy_load), \\\"all_types_dict\\\")\\n        assert isinstance(type(lazy_load).all_types_dict, property)\\n\\n        # Accessing it should return the value, not a method\\n        result = lazy_load.all_types_dict\\n        assert callable(result) is False\\n        assert result == {\\\"prop\\\": \\\"test\\\"}\\n\\n    def test_state_consistency(self):\\n        \\\"\\\"\\\"Test that internal state remains consistent.\\\"\\\"\\\"\\n        lazy_load = self.ConcreteLazyLoad(build_dict_return={\\\"state\\\": \\\"test\\\"})\\n\\n        # Initially _all_types_dict should be None\\n        assert lazy_load._all_types_dict is None\\n\\n        # After first access, it should be set\\n        result = lazy_load.all_types_dict\\n        assert lazy_load._all_types_dict is not None\\n        assert lazy_load._all_types_dict == {\\\"state\\\": \\\"test\\\"}\\n\\n        # The returned value should be the same as internal state\\n        assert result is lazy_load._all_types_dict\\n\\n    def test_manual_dict_assignment(self):\\n        \\\"\\\"\\\"Test behavior when _all_types_dict is manually assigned.\\\"\\\"\\\"\\n        lazy_load = self.ConcreteLazyLoad(build_dict_return={\\\"build\\\": \\\"dict\\\"})\\n\\n        # Manually assign the dict\\n        manual_dict = {\\\"manual\\\": \\\"assignment\\\"}\\n        lazy_load._all_types_dict = manual_dict\\n\\n        # Should return the manually assigned dict, not call _build_dict\\n        result = lazy_load.all_types_dict\\n\\n        assert result == manual_dict\\n        assert lazy_load.build_dict_call_count == 0  # _build_dict not called\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/utils/test_mcp_cleanup.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"7d809c3c2c44df5b710945ab2d0fb96c8d3a7eba24ac13d5a4aaa0d3a5330198\",\"content\":\"\\\"\\\"\\\"Tests for MCP cleanup utilities.\\\"\\\"\\\"\\n\\nimport sys\\nfrom unittest.mock import AsyncMock, MagicMock, patch\\n\\nimport pytest\\nfrom langflow.utils.mcp_cleanup import (\\n    _kill_mcp_processes,\\n    _terminate_child_mcp_processes,\\n    _terminate_orphaned_mcp_processes,\\n    _try_terminate_mcp_process,\\n    cleanup_mcp_sessions,\\n)\\n\\npytestmark = pytest.mark.asyncio\\n\\n\\nclass TestCleanupMcpSessions:\\n    \\\"\\\"\\\"Tests for cleanup_mcp_sessions function.\\\"\\\"\\\"\\n\\n    async def test_cleanup_with_valid_session_manager(self):\\n        \\\"\\\"\\\"Test cleanup when a valid MCPSessionManager exists in cache.\\\"\\\"\\\"\\n        mock_session_manager = MagicMock()\\n        mock_session_manager.cleanup_all = AsyncMock()\\n\\n        mock_cache_service = MagicMock()\\n        mock_cache_service.get.return_value = mock_session_manager\\n\\n        with (\\n            patch(\\n                \\\"langflow.services.deps.get_shared_component_cache_service\\\",\\n                return_value=mock_cache_service,\\n            ),\\n            patch(\\\"langflow.utils.mcp_cleanup._kill_mcp_processes\\\", new_callable=AsyncMock) as mock_kill,\\n            patch(\\\"lfx.base.mcp.util.MCPSessionManager\\\", new=type(mock_session_manager)),\\n        ):\\n            await cleanup_mcp_sessions()\\n\\n            mock_session_manager.cleanup_all.assert_called_once()\\n            mock_kill.assert_called_once()\\n\\n    async def test_cleanup_with_cache_miss(self):\\n        \\\"\\\"\\\"Test cleanup when no session manager exists (cache miss).\\\"\\\"\\\"\\n        mock_cache_service = MagicMock()\\n\\n        cache_miss_sentinel = object()\\n\\n        with (\\n            patch(\\\"lfx.services.cache.utils.CACHE_MISS\\\", cache_miss_sentinel),\\n            patch(\\n                \\\"langflow.services.deps.get_shared_component_cache_service\\\",\\n                return_value=mock_cache_service,\\n            ),\\n            patch(\\\"langflow.utils.mcp_cleanup._kill_mcp_processes\\\", new_callable=AsyncMock) as mock_kill,\\n        ):\\n            mock_cache_service.get.return_value = cache_miss_sentinel\\n\\n            await cleanup_mcp_sessions()\\n\\n            # Should still call the fallback kill function\\n            mock_kill.assert_called_once()\\n\\n    async def test_cleanup_handles_import_error(self):\\n        \\\"\\\"\\\"Test cleanup handles import errors gracefully.\\\"\\\"\\\"\\n        with (\\n            patch.dict(\\\"sys.modules\\\", {\\\"lfx.base.mcp.util\\\": None}),\\n            patch(\\\"langflow.utils.mcp_cleanup._kill_mcp_processes\\\", new_callable=AsyncMock) as mock_kill,\\n        ):\\n            # Should not raise, should silently continue\\n            await cleanup_mcp_sessions()\\n            mock_kill.assert_called_once()\\n\\n    async def test_cleanup_handles_exception_in_session_manager(self):\\n        \\\"\\\"\\\"Test cleanup handles exceptions from session manager gracefully.\\\"\\\"\\\"\\n        mock_session_manager = MagicMock()\\n        mock_session_manager.cleanup_all = AsyncMock(side_effect=Exception(\\\"Test error\\\"))\\n\\n        mock_cache_service = MagicMock()\\n        mock_cache_service.get.return_value = mock_session_manager\\n\\n        with (\\n            patch(\\n                \\\"langflow.services.deps.get_shared_component_cache_service\\\",\\n                return_value=mock_cache_service,\\n            ),\\n            patch(\\\"langflow.utils.mcp_cleanup._kill_mcp_processes\\\", new_callable=AsyncMock) as mock_kill,\\n            patch(\\\"lfx.base.mcp.util.MCPSessionManager\\\", new=type(mock_session_manager)),\\n        ):\\n            # Should not raise\\n            await cleanup_mcp_sessions()\\n            # Fallback should still be called\\n            mock_kill.assert_called_once()\\n\\n\\nclass TestKillMcpProcesses:\\n    \\\"\\\"\\\"Tests for _kill_mcp_processes function.\\\"\\\"\\\"\\n\\n    async def test_skips_on_windows(self):\\n        \\\"\\\"\\\"Test that the function skips on Windows.\\\"\\\"\\\"\\n        with patch.object(sys, \\\"platform\\\", \\\"win32\\\"):\\n            # Should return immediately without doing anything\\n            await _kill_mcp_processes()\\n\\n    async def test_skips_when_psutil_not_available(self):\\n        \\\"\\\"\\\"Test that the function handles missing psutil gracefully.\\\"\\\"\\\"\\n        with (\\n            patch.object(sys, \\\"platform\\\", \\\"darwin\\\"),\\n            patch.dict(\\\"sys.modules\\\", {\\\"psutil\\\": None}),\\n        ):\\n            # Should not raise\\n            await _kill_mcp_processes()\\n\\n    async def test_kills_child_and_orphaned_processes(self):\\n        \\\"\\\"\\\"Test that both child and orphaned processes are terminated.\\\"\\\"\\\"\\n        mock_psutil = MagicMock()\\n\\n        with (\\n            patch.object(sys, \\\"platform\\\", \\\"darwin\\\"),\\n            patch.dict(\\\"sys.modules\\\", {\\\"psutil\\\": mock_psutil}),\\n            patch(\\n                \\\"langflow.utils.mcp_cleanup._terminate_child_mcp_processes\\\",\\n                new_callable=AsyncMock,\\n                return_value=2,\\n            ) as mock_child,\\n            patch(\\n                \\\"langflow.utils.mcp_cleanup._terminate_orphaned_mcp_processes\\\",\\n                new_callable=AsyncMock,\\n                return_value=1,\\n            ) as mock_orphan,\\n        ):\\n            await _kill_mcp_processes()\\n\\n            mock_child.assert_called_once()\\n            mock_orphan.assert_called_once()\\n\\n    async def test_logs_killed_count(self):\\n        \\\"\\\"\\\"Test that killed process count is logged.\\\"\\\"\\\"\\n        mock_psutil = MagicMock()\\n\\n        with (\\n            patch.object(sys, \\\"platform\\\", \\\"darwin\\\"),\\n            patch.dict(\\\"sys.modules\\\", {\\\"psutil\\\": mock_psutil}),\\n            patch(\\n                \\\"langflow.utils.mcp_cleanup._terminate_child_mcp_processes\\\",\\n                new_callable=AsyncMock,\\n                return_value=3,\\n            ),\\n            patch(\\n                \\\"langflow.utils.mcp_cleanup._terminate_orphaned_mcp_processes\\\",\\n                new_callable=AsyncMock,\\n                return_value=2,\\n            ),\\n            patch(\\\"langflow.utils.mcp_cleanup.logger\\\") as mock_logger,\\n        ):\\n            mock_logger.ainfo = AsyncMock()\\n\\n            await _kill_mcp_processes()\\n\\n            mock_logger.ainfo.assert_called_once()\\n            call_args = mock_logger.ainfo.call_args[0][0]\\n            assert \\\"5\\\" in call_args  # 3 + 2 = 5\\n\\n    async def test_does_not_log_when_no_processes_killed(self):\\n        \\\"\\\"\\\"Test that no log is made when no processes are killed.\\\"\\\"\\\"\\n        mock_psutil = MagicMock()\\n\\n        with (\\n            patch.object(sys, \\\"platform\\\", \\\"darwin\\\"),\\n            patch.dict(\\\"sys.modules\\\", {\\\"psutil\\\": mock_psutil}),\\n            patch(\\n                \\\"langflow.utils.mcp_cleanup._terminate_child_mcp_processes\\\",\\n                new_callable=AsyncMock,\\n                return_value=0,\\n            ),\\n            patch(\\n                \\\"langflow.utils.mcp_cleanup._terminate_orphaned_mcp_processes\\\",\\n                new_callable=AsyncMock,\\n                return_value=0,\\n            ),\\n            patch(\\\"langflow.utils.mcp_cleanup.logger\\\") as mock_logger,\\n        ):\\n            mock_logger.ainfo = AsyncMock()\\n\\n            await _kill_mcp_processes()\\n\\n            mock_logger.ainfo.assert_not_called()\\n\\n\\nclass TestTerminateChildMcpProcesses:\\n    \\\"\\\"\\\"Tests for _terminate_child_mcp_processes function.\\\"\\\"\\\"\\n\\n    async def test_terminates_mcp_child_processes(self):\\n        \\\"\\\"\\\"Test that MCP child processes are terminated.\\\"\\\"\\\"\\n        mock_psutil = MagicMock()\\n\\n        mock_mcp_proc = MagicMock()\\n        mock_mcp_proc.cmdline.return_value = [\\\"python\\\", \\\"mcp-server-filesystem\\\", \\\"/tmp\\\"]  # noqa: S108\\n        mock_mcp_proc.terminate = MagicMock()\\n        mock_mcp_proc.wait = MagicMock()\\n\\n        mock_other_proc = MagicMock()\\n        mock_other_proc.cmdline.return_value = [\\\"python\\\", \\\"other_script.py\\\"]\\n\\n        mock_current = MagicMock()\\n        mock_current.children.return_value = [mock_mcp_proc, mock_other_proc]\\n\\n        mock_psutil.Process.return_value = mock_current\\n        mock_psutil.NoSuchProcess = Exception\\n        mock_psutil.AccessDenied = Exception\\n        mock_psutil.ZombieProcess = Exception\\n        mock_psutil.TimeoutExpired = Exception\\n\\n        with patch(\\n            \\\"langflow.utils.mcp_cleanup._try_terminate_mcp_process\\\",\\n            new_callable=AsyncMock,\\n            side_effect=[True, False],\\n        ):\\n            count = await _terminate_child_mcp_processes(mock_psutil)\\n\\n        assert count == 1\\n\\n    async def test_handles_no_such_process_on_children(self):\\n        \\\"\\\"\\\"Test handling when current process doesn't exist.\\\"\\\"\\\"\\n        mock_psutil = MagicMock()\\n\\n        mock_current = MagicMock()\\n        mock_current.children.side_effect = mock_psutil.NoSuchProcess\\n\\n        mock_psutil.Process.return_value = mock_current\\n        mock_psutil.NoSuchProcess = Exception\\n\\n        count = await _terminate_child_mcp_processes(mock_psutil)\\n\\n        assert count == 0\\n\\n\\nclass TestTerminateOrphanedMcpProcesses:\\n    \\\"\\\"\\\"Tests for _terminate_orphaned_mcp_processes function.\\\"\\\"\\\"\\n\\n    async def test_terminates_orphaned_mcp_processes(self):\\n        \\\"\\\"\\\"Test that orphaned MCP processes (ppid=1) are terminated.\\\"\\\"\\\"\\n        mock_psutil = MagicMock()\\n\\n        # Orphaned MCP process (ppid=1)\\n        mock_orphan_mcp = MagicMock()\\n        mock_orphan_mcp.info = {\\n            \\\"pid\\\": 12345,\\n            \\\"ppid\\\": 1,\\n            \\\"cmdline\\\": [\\\"python\\\", \\\"mcp-server-filesystem\\\", \\\"/tmp\\\"],  # noqa: S108\\n        }\\n\\n        # Non-orphaned MCP process\\n        mock_non_orphan = MagicMock()\\n        mock_non_orphan.info = {\\n            \\\"pid\\\": 12346,\\n            \\\"ppid\\\": 1000,\\n            \\\"cmdline\\\": [\\\"python\\\", \\\"mcp-server-filesystem\\\", \\\"/tmp\\\"],  # noqa: S108\\n        }\\n\\n        # Orphaned non-MCP process\\n        mock_orphan_other = MagicMock()\\n        mock_orphan_other.info = {\\n            \\\"pid\\\": 12347,\\n            \\\"ppid\\\": 1,\\n            \\\"cmdline\\\": [\\\"python\\\", \\\"other_script.py\\\"],\\n        }\\n\\n        mock_psutil.process_iter.return_value = [mock_orphan_mcp, mock_non_orphan, mock_orphan_other]\\n        mock_psutil.NoSuchProcess = Exception\\n        mock_psutil.AccessDenied = Exception\\n        mock_psutil.ZombieProcess = Exception\\n\\n        with patch(\\n            \\\"langflow.utils.mcp_cleanup._try_terminate_mcp_process\\\",\\n            new_callable=AsyncMock,\\n            side_effect=[True, False],  # Only first call (orphan_mcp) returns True\\n        ):\\n            count = await _terminate_orphaned_mcp_processes(mock_psutil)\\n\\n        # Only the orphaned MCP process should be attempted (ppid=1)\\n        # The non-orphan (ppid=1000) should be skipped before _try_terminate is called\\n        assert count == 1\\n\\n    async def test_skips_non_orphaned_processes(self):\\n        \\\"\\\"\\\"Test that non-orphaned processes are skipped.\\\"\\\"\\\"\\n        mock_psutil = MagicMock()\\n\\n        mock_proc = MagicMock()\\n        mock_proc.info = {\\n            \\\"pid\\\": 12345,\\n            \\\"ppid\\\": 1000,  # Not orphaned\\n            \\\"cmdline\\\": [\\\"python\\\", \\\"mcp-server-filesystem\\\"],\\n        }\\n\\n        mock_psutil.process_iter.return_value = [mock_proc]\\n        mock_psutil.NoSuchProcess = Exception\\n        mock_psutil.AccessDenied = Exception\\n        mock_psutil.ZombieProcess = Exception\\n\\n        with patch(\\n            \\\"langflow.utils.mcp_cleanup._try_terminate_mcp_process\\\",\\n            new_callable=AsyncMock,\\n        ) as mock_terminate:\\n            count = await _terminate_orphaned_mcp_processes(mock_psutil)\\n\\n        assert count == 0\\n        mock_terminate.assert_not_called()\\n\\n    async def test_handles_access_denied(self):\\n        \\\"\\\"\\\"Test handling AccessDenied exception during iteration.\\\"\\\"\\\"\\n        mock_psutil = MagicMock()\\n\\n        mock_proc = MagicMock()\\n        mock_proc.info = property(lambda _: (_ for _ in ()).throw(mock_psutil.AccessDenied))\\n\\n        # Make info raise AccessDenied\\n        type(mock_proc).info = property(lambda _: (_ for _ in ()).throw(mock_psutil.AccessDenied))\\n\\n        mock_psutil.process_iter.return_value = [mock_proc]\\n        mock_psutil.NoSuchProcess = type(\\\"NoSuchProcess\\\", (Exception,), {})\\n        mock_psutil.AccessDenied = type(\\\"AccessDenied\\\", (Exception,), {})\\n        mock_psutil.ZombieProcess = type(\\\"ZombieProcess\\\", (Exception,), {})\\n\\n        # Should not raise\\n        count = await _terminate_orphaned_mcp_processes(mock_psutil)\\n        assert count == 0\\n\\n\\nclass TestTryTerminateMcpProcess:\\n    \\\"\\\"\\\"Tests for _try_terminate_mcp_process function.\\\"\\\"\\\"\\n\\n    async def test_terminates_mcp_server_process(self):\\n        \\\"\\\"\\\"Test termination of mcp-server process.\\\"\\\"\\\"\\n        mock_psutil = MagicMock()\\n        mock_psutil.NoSuchProcess = Exception\\n        mock_psutil.AccessDenied = Exception\\n        mock_psutil.ZombieProcess = Exception\\n        mock_psutil.TimeoutExpired = Exception\\n\\n        mock_proc = MagicMock()\\n        mock_proc.cmdline.return_value = [\\\"python\\\", \\\"mcp-server-filesystem\\\", \\\"/tmp\\\"]  # noqa: S108\\n        mock_proc.terminate = MagicMock()\\n        mock_proc.wait = MagicMock()\\n\\n        result = await _try_terminate_mcp_process(mock_proc, mock_psutil)\\n\\n        assert result is True\\n        mock_proc.terminate.assert_called_once()\\n        mock_proc.wait.assert_called_once_with(timeout=2)\\n\\n    async def test_terminates_mcp_proxy_process(self):\\n        \\\"\\\"\\\"Test termination of mcp-proxy process.\\\"\\\"\\\"\\n        mock_psutil = MagicMock()\\n        mock_psutil.NoSuchProcess = Exception\\n        mock_psutil.AccessDenied = Exception\\n        mock_psutil.ZombieProcess = Exception\\n        mock_psutil.TimeoutExpired = Exception\\n\\n        mock_proc = MagicMock()\\n        mock_proc.cmdline.return_value = [\\\"mcp-proxy\\\", \\\"--port\\\", \\\"8080\\\"]\\n        mock_proc.terminate = MagicMock()\\n        mock_proc.wait = MagicMock()\\n\\n        result = await _try_terminate_mcp_process(mock_proc, mock_psutil)\\n\\n        assert result is True\\n        mock_proc.terminate.assert_called_once()\\n\\n    async def test_skips_non_mcp_process(self):\\n        \\\"\\\"\\\"Test that non-MCP processes are skipped.\\\"\\\"\\\"\\n        mock_psutil = MagicMock()\\n        mock_psutil.NoSuchProcess = Exception\\n        mock_psutil.AccessDenied = Exception\\n        mock_psutil.ZombieProcess = Exception\\n\\n        mock_proc = MagicMock()\\n        mock_proc.cmdline.return_value = [\\\"python\\\", \\\"some_other_script.py\\\"]\\n\\n        result = await _try_terminate_mcp_process(mock_proc, mock_psutil)\\n\\n        assert result is False\\n        mock_proc.terminate.assert_not_called()\\n\\n    async def test_kills_process_on_timeout(self):\\n        \\\"\\\"\\\"Test that process is killed when terminate times out.\\\"\\\"\\\"\\n        mock_psutil = MagicMock()\\n        mock_psutil.NoSuchProcess = Exception\\n        mock_psutil.AccessDenied = Exception\\n        mock_psutil.ZombieProcess = Exception\\n        mock_psutil.TimeoutExpired = type(\\\"TimeoutExpired\\\", (Exception,), {})\\n\\n        mock_proc = MagicMock()\\n        mock_proc.cmdline.return_value = [\\\"python\\\", \\\"mcp-server-test\\\"]\\n        mock_proc.terminate = MagicMock()\\n        mock_proc.wait = MagicMock(side_effect=mock_psutil.TimeoutExpired)\\n        mock_proc.kill = MagicMock()\\n\\n        result = await _try_terminate_mcp_process(mock_proc, mock_psutil)\\n\\n        assert result is True\\n        mock_proc.terminate.assert_called_once()\\n        mock_proc.kill.assert_called_once()\\n\\n    async def test_handles_no_such_process(self):\\n        \\\"\\\"\\\"Test handling when process no longer exists.\\\"\\\"\\\"\\n        mock_psutil = MagicMock()\\n        mock_psutil.NoSuchProcess = type(\\\"NoSuchProcess\\\", (Exception,), {})\\n        mock_psutil.AccessDenied = Exception\\n        mock_psutil.ZombieProcess = Exception\\n\\n        mock_proc = MagicMock()\\n        mock_proc.cmdline.side_effect = mock_psutil.NoSuchProcess\\n\\n        result = await _try_terminate_mcp_process(mock_proc, mock_psutil)\\n\\n        assert result is False\\n\\n    async def test_handles_access_denied(self):\\n        \\\"\\\"\\\"Test handling when access is denied.\\\"\\\"\\\"\\n        mock_psutil = MagicMock()\\n        mock_psutil.NoSuchProcess = Exception\\n        mock_psutil.AccessDenied = type(\\\"AccessDenied\\\", (Exception,), {})\\n        mock_psutil.ZombieProcess = Exception\\n\\n        mock_proc = MagicMock()\\n        mock_proc.cmdline.side_effect = mock_psutil.AccessDenied\\n\\n        result = await _try_terminate_mcp_process(mock_proc, mock_psutil)\\n\\n        assert result is False\\n\\n    async def test_handles_zombie_process(self):\\n        \\\"\\\"\\\"Test handling zombie processes.\\\"\\\"\\\"\\n        mock_psutil = MagicMock()\\n        mock_psutil.NoSuchProcess = Exception\\n        mock_psutil.AccessDenied = Exception\\n        mock_psutil.ZombieProcess = type(\\\"ZombieProcess\\\", (Exception,), {})\\n\\n        mock_proc = MagicMock()\\n        mock_proc.cmdline.side_effect = mock_psutil.ZombieProcess\\n\\n        result = await _try_terminate_mcp_process(mock_proc, mock_psutil)\\n\\n        assert result is False\\n\\n    async def test_handles_empty_cmdline(self):\\n        \\\"\\\"\\\"Test handling when cmdline returns empty list.\\\"\\\"\\\"\\n        mock_psutil = MagicMock()\\n        mock_psutil.NoSuchProcess = Exception\\n        mock_psutil.AccessDenied = Exception\\n        mock_psutil.ZombieProcess = Exception\\n\\n        mock_proc = MagicMock()\\n        mock_proc.cmdline.return_value = []\\n\\n        result = await _try_terminate_mcp_process(mock_proc, mock_psutil)\\n\\n        assert result is False\\n\\n    async def test_handles_none_cmdline(self):\\n        \\\"\\\"\\\"Test handling when cmdline returns None.\\\"\\\"\\\"\\n        mock_psutil = MagicMock()\\n        mock_psutil.NoSuchProcess = Exception\\n        mock_psutil.AccessDenied = Exception\\n        mock_psutil.ZombieProcess = Exception\\n\\n        mock_proc = MagicMock()\\n        mock_proc.cmdline.return_value = None\\n\\n        result = await _try_terminate_mcp_process(mock_proc, mock_psutil)\\n\\n        assert result is False\\n\\n\\nclass TestMcpCleanupIntegration:\\n    \\\"\\\"\\\"Integration tests for MCP cleanup.\\\"\\\"\\\"\\n\\n    async def test_full_cleanup_flow_success(self):\\n        \\\"\\\"\\\"Test the complete cleanup flow when everything works.\\\"\\\"\\\"\\n        mock_session_manager = MagicMock()\\n        mock_session_manager.cleanup_all = AsyncMock()\\n\\n        mock_cache_service = MagicMock()\\n        mock_cache_service.get.return_value = mock_session_manager\\n\\n        with (\\n            patch(\\n                \\\"langflow.services.deps.get_shared_component_cache_service\\\",\\n                return_value=mock_cache_service,\\n            ),\\n            patch(\\\"langflow.utils.mcp_cleanup._kill_mcp_processes\\\", new_callable=AsyncMock),\\n            patch(\\\"lfx.base.mcp.util.MCPSessionManager\\\", new=type(mock_session_manager)),\\n        ):\\n            # Should complete without raising\\n            await cleanup_mcp_sessions()\\n\\n    async def test_full_cleanup_flow_with_all_errors(self):\\n        \\\"\\\"\\\"Test that cleanup continues even when everything fails.\\\"\\\"\\\"\\n        mock_cache_service = MagicMock()\\n        mock_cache_service.get.side_effect = Exception(\\\"Cache error\\\")\\n\\n        with (\\n            patch(\\n                \\\"langflow.services.deps.get_shared_component_cache_service\\\",\\n                return_value=mock_cache_service,\\n            ),\\n            patch(\\n                \\\"langflow.utils.mcp_cleanup._kill_mcp_processes\\\",\\n                new_callable=AsyncMock,\\n                side_effect=Exception(\\\"Kill error\\\"),\\n            ),\\n        ):\\n            # Should not raise even with all errors\\n            await cleanup_mcp_sessions()\\n\\n    async def test_cleanup_is_silent_on_errors(self):\\n        \\\"\\\"\\\"Test that cleanup doesn't log errors (silent failure during shutdown).\\\"\\\"\\\"\\n        mock_cache_service = MagicMock()\\n        mock_cache_service.get.side_effect = Exception(\\\"Some error\\\")\\n\\n        with (\\n            patch(\\n                \\\"langflow.services.deps.get_shared_component_cache_service\\\",\\n                return_value=mock_cache_service,\\n            ),\\n            patch(\\\"langflow.utils.mcp_cleanup._kill_mcp_processes\\\", new_callable=AsyncMock),\\n            patch(\\\"langflow.utils.mcp_cleanup.logger\\\") as mock_logger,\\n        ):\\n            mock_logger.awarning = AsyncMock()\\n            mock_logger.aerror = AsyncMock()\\n\\n            await cleanup_mcp_sessions()\\n\\n            # Should not log errors during cleanup (silent failure)\\n            mock_logger.awarning.assert_not_called()\\n            mock_logger.aerror.assert_not_called()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/utils/test_mcp_client.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f60da387cd7c66078754f73e1e62a9f0f14ddd61ff2515e9e88c705bf3a7a39c\",\"content\":\"\\\"\\\"\\\"Unit tests for lfx.mcp \u2014 redact, registry, and client modules.\\n\\nThese test pure functions only (no network, no server).\\n\\\"\\\"\\\"\\n\\nimport pytest\\nfrom lfx.mcp.client import LangflowClient\\nfrom lfx.mcp.redact import (\\n    is_sensitive_field,\\n    redact_node,\\n    redact_template,\\n)\\nfrom lfx.mcp.registry import (\\n    describe_component,\\n    search_registry,\\n)\\n\\n# ---------------------------------------------------------------------------\\n# Redact\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestIsSensitiveField:\\n    def test_api_key(self):\\n        assert is_sensitive_field(\\\"api_key\\\") is True\\n\\n    def test_openai_api_key(self):\\n        assert is_sensitive_field(\\\"openai_api_key\\\") is True\\n\\n    def test_password(self):\\n        assert is_sensitive_field(\\\"password\\\") is True\\n\\n    def test_secret_token(self):\\n        assert is_sensitive_field(\\\"secret_token\\\") is True\\n\\n    def test_private_key(self):\\n        assert is_sensitive_field(\\\"private_key\\\") is True\\n\\n    def test_access_key(self):\\n        assert is_sensitive_field(\\\"access_key_id\\\") is True\\n\\n    def test_input_value_not_sensitive(self):\\n        assert is_sensitive_field(\\\"input_value\\\") is False\\n\\n    def test_model_name_not_sensitive(self):\\n        assert is_sensitive_field(\\\"model_name\\\") is False\\n\\n    def test_temperature_not_sensitive(self):\\n        assert is_sensitive_field(\\\"temperature\\\") is False\\n\\n\\nclass TestRedactTemplate:\\n    def test_masks_sensitive_values(self):\\n        template = {\\n            \\\"api_key\\\": {\\\"value\\\": \\\"sk-secret-123\\\", \\\"type\\\": \\\"str\\\"},\\n            \\\"model_name\\\": {\\\"value\\\": \\\"gpt-4o\\\", \\\"type\\\": \\\"str\\\"},\\n            \\\"password\\\": {\\\"value\\\": \\\"hunter2\\\", \\\"type\\\": \\\"str\\\"},\\n        }\\n        result = redact_template(template)\\n        assert result[\\\"api_key\\\"][\\\"value\\\"] == \\\"***REDACTED***\\\"\\n        assert result[\\\"model_name\\\"][\\\"value\\\"] == \\\"gpt-4o\\\"\\n        assert result[\\\"password\\\"][\\\"value\\\"] == \\\"***REDACTED***\\\"\\n\\n    def test_preserves_empty_sensitive(self):\\n        template = {\\\"api_key\\\": {\\\"value\\\": \\\"\\\", \\\"type\\\": \\\"str\\\"}}\\n        result = redact_template(template)\\n        assert result[\\\"api_key\\\"][\\\"value\\\"] == \\\"\\\"\\n\\n    def test_preserves_none_sensitive(self):\\n        template = {\\\"api_key\\\": {\\\"value\\\": None, \\\"type\\\": \\\"str\\\"}}\\n        result = redact_template(template)\\n        assert result[\\\"api_key\\\"][\\\"value\\\"] is None\\n\\n    def test_preserves_non_dict_fields(self):\\n        template = {\\n            \\\"code\\\": \\\"print('hello')\\\",\\n            \\\"api_key\\\": {\\\"value\\\": \\\"sk-123\\\", \\\"type\\\": \\\"str\\\"},\\n        }\\n        result = redact_template(template)\\n        assert result[\\\"code\\\"] == \\\"print('hello')\\\"\\n        assert result[\\\"api_key\\\"][\\\"value\\\"] == \\\"***REDACTED***\\\"\\n\\n    def test_does_not_modify_original(self):\\n        template = {\\\"api_key\\\": {\\\"value\\\": \\\"sk-123\\\", \\\"type\\\": \\\"str\\\"}}\\n        redact_template(template)\\n        assert template[\\\"api_key\\\"][\\\"value\\\"] == \\\"sk-123\\\"\\n\\n\\nclass TestRedactNode:\\n    def test_redacts_node_template(self):\\n        node_data = {\\n            \\\"type\\\": \\\"OpenAIModel\\\",\\n            \\\"node\\\": {\\n                \\\"template\\\": {\\n                    \\\"api_key\\\": {\\\"value\\\": \\\"sk-real-key\\\", \\\"type\\\": \\\"str\\\"},\\n                    \\\"model_name\\\": {\\\"value\\\": \\\"gpt-4o\\\", \\\"type\\\": \\\"str\\\"},\\n                },\\n            },\\n        }\\n        result = redact_node(node_data)\\n        assert result[\\\"node\\\"][\\\"template\\\"][\\\"api_key\\\"][\\\"value\\\"] == \\\"***REDACTED***\\\"\\n        assert result[\\\"node\\\"][\\\"template\\\"][\\\"model_name\\\"][\\\"value\\\"] == \\\"gpt-4o\\\"\\n\\n    def test_does_not_modify_original(self):\\n        node_data = {\\n            \\\"type\\\": \\\"OpenAIModel\\\",\\n            \\\"node\\\": {\\n                \\\"template\\\": {\\n                    \\\"api_key\\\": {\\\"value\\\": \\\"sk-real-key\\\", \\\"type\\\": \\\"str\\\"},\\n                },\\n            },\\n        }\\n        redact_node(node_data)\\n        assert node_data[\\\"node\\\"][\\\"template\\\"][\\\"api_key\\\"][\\\"value\\\"] == \\\"sk-real-key\\\"\\n\\n    def test_handles_node_without_template(self):\\n        node_data = {\\\"type\\\": \\\"Simple\\\", \\\"node\\\": {}}\\n        result = redact_node(node_data)\\n        assert result[\\\"type\\\"] == \\\"Simple\\\"\\n\\n\\n# ---------------------------------------------------------------------------\\n# Registry (pure functions)\\n# ---------------------------------------------------------------------------\\n\\nSAMPLE_REGISTRY = {\\n    \\\"ChatInput\\\": {\\n        \\\"display_name\\\": \\\"Chat Input\\\",\\n        \\\"description\\\": \\\"Get chat inputs from the user\\\",\\n        \\\"category\\\": \\\"inputs\\\",\\n        \\\"outputs\\\": [{\\\"name\\\": \\\"message\\\", \\\"types\\\": [\\\"Message\\\"]}],\\n        \\\"template\\\": {\\n            \\\"input_value\\\": {\\\"type\\\": \\\"str\\\", \\\"input_types\\\": [\\\"Message\\\"], \\\"required\\\": False},\\n            \\\"sender\\\": {\\\"type\\\": \\\"str\\\"},\\n        },\\n    },\\n    \\\"ChatOutput\\\": {\\n        \\\"display_name\\\": \\\"Chat Output\\\",\\n        \\\"description\\\": \\\"Display chat outputs\\\",\\n        \\\"category\\\": \\\"outputs\\\",\\n        \\\"outputs\\\": [{\\\"name\\\": \\\"message\\\", \\\"types\\\": [\\\"Message\\\"], \\\"tool_mode\\\": True}],\\n        \\\"template\\\": {\\n            \\\"input_value\\\": {\\\"type\\\": \\\"str\\\", \\\"input_types\\\": [\\\"Message\\\"], \\\"required\\\": True},\\n        },\\n    },\\n    \\\"OpenAIModel\\\": {\\n        \\\"display_name\\\": \\\"OpenAI\\\",\\n        \\\"description\\\": \\\"OpenAI language model\\\",\\n        \\\"category\\\": \\\"models\\\",\\n        \\\"outputs\\\": [\\n            {\\\"name\\\": \\\"text_output\\\", \\\"types\\\": [\\\"Message\\\"]},\\n            {\\\"name\\\": \\\"model_output\\\", \\\"types\\\": [\\\"LanguageModel\\\"]},\\n        ],\\n        \\\"template\\\": {\\n            \\\"model_name\\\": {\\\"type\\\": \\\"str\\\", \\\"real_time_refresh\\\": True},\\n            \\\"api_key\\\": {\\\"type\\\": \\\"str\\\", \\\"input_types\\\": [\\\"SecretStr\\\"], \\\"required\\\": True},\\n            \\\"input_value\\\": {\\\"type\\\": \\\"str\\\", \\\"input_types\\\": [\\\"Message\\\"], \\\"required\\\": False},\\n        },\\n    },\\n}\\n\\n\\nclass TestSearchRegistry:\\n    def test_no_filters_returns_all(self):\\n        results = search_registry(SAMPLE_REGISTRY)\\n        assert len(results) == 3\\n\\n    def test_query_filters_by_name(self):\\n        results = search_registry(SAMPLE_REGISTRY, query=\\\"Chat\\\")\\n        types = {r[\\\"type\\\"] for r in results}\\n        assert types == {\\\"ChatInput\\\", \\\"ChatOutput\\\"}\\n\\n    def test_query_filters_by_category(self):\\n        results = search_registry(SAMPLE_REGISTRY, query=\\\"models\\\")\\n        assert len(results) == 1\\n        assert results[0][\\\"type\\\"] == \\\"OpenAIModel\\\"\\n\\n    def test_category_exact_filter(self):\\n        results = search_registry(SAMPLE_REGISTRY, category=\\\"inputs\\\")\\n        assert len(results) == 1\\n        assert results[0][\\\"type\\\"] == \\\"ChatInput\\\"\\n\\n    def test_query_and_category_combined(self):\\n        results = search_registry(SAMPLE_REGISTRY, query=\\\"Chat\\\", category=\\\"outputs\\\")\\n        assert len(results) == 1\\n        assert results[0][\\\"type\\\"] == \\\"ChatOutput\\\"\\n\\n    def test_no_matches(self):\\n        results = search_registry(SAMPLE_REGISTRY, query=\\\"Nonexistent\\\")\\n        assert results == []\\n\\n    def test_case_insensitive_query(self):\\n        results = search_registry(SAMPLE_REGISTRY, query=\\\"chat\\\")\\n        assert len(results) == 2\\n\\n    def test_result_fields(self):\\n        results = search_registry(SAMPLE_REGISTRY, query=\\\"OpenAI\\\")\\n        assert len(results) == 1\\n        r = results[0]\\n        assert r[\\\"type\\\"] == \\\"OpenAIModel\\\"\\n        assert r[\\\"category\\\"] == \\\"models\\\"\\n        assert r[\\\"display_name\\\"] == \\\"OpenAI\\\"\\n        assert r[\\\"description\\\"] == \\\"OpenAI language model\\\"\\n\\n\\nclass TestDescribeComponent:\\n    def test_describe_chat_input(self):\\n        info = describe_component(SAMPLE_REGISTRY, \\\"ChatInput\\\")\\n        assert info[\\\"type\\\"] == \\\"ChatInput\\\"\\n        assert info[\\\"display_name\\\"] == \\\"Chat Input\\\"\\n        assert info[\\\"category\\\"] == \\\"inputs\\\"\\n        assert len(info[\\\"outputs\\\"]) == 1\\n        assert info[\\\"outputs\\\"][0][\\\"name\\\"] == \\\"message\\\"\\n\\n    def test_describe_inputs(self):\\n        info = describe_component(SAMPLE_REGISTRY, \\\"OpenAIModel\\\")\\n        input_names = {i[\\\"name\\\"] for i in info[\\\"inputs\\\"]}\\n        # Only fields with input_types are listed as inputs\\n        assert \\\"api_key\\\" in input_names\\n        assert \\\"input_value\\\" in input_names\\n        assert \\\"model_name\\\" not in input_names  # no input_types\\n\\n    def test_describe_unknown_raises(self):\\n        with pytest.raises(ValueError, match=\\\"Unknown component\\\"):\\n            describe_component(SAMPLE_REGISTRY, \\\"TotallyFake\\\")\\n\\n    def test_describe_outputs(self):\\n        info = describe_component(SAMPLE_REGISTRY, \\\"OpenAIModel\\\")\\n        output_names = {o[\\\"name\\\"] for o in info[\\\"outputs\\\"]}\\n        assert output_names == {\\\"text_output\\\", \\\"model_output\\\"}\\n\\n    def test_describe_ignores_output_side_tool_mode(self):\\n        \\\"\\\"\\\"ChatOutput's message output carries tool_mode; the component has no toolset.\\n\\n        Output-side tool_mode marks which outputs a toolset exposes, so it must\\n        not be read as the component's capability \u2014 Component._handle_tool_mode\\n        creates component_as_tool only for a tool_mode input or add_tool_output.\\n        \\\"\\\"\\\"\\n        info = describe_component(SAMPLE_REGISTRY, \\\"ChatOutput\\\")\\n        output_names = {o[\\\"name\\\"] for o in info[\\\"outputs\\\"]}\\n        assert \\\"component_as_tool\\\" not in output_names\\n\\n    def test_describe_no_tool_output_without_tool_mode(self):\\n        info = describe_component(SAMPLE_REGISTRY, \\\"OpenAIModel\\\")\\n        output_names = {o[\\\"name\\\"] for o in info[\\\"outputs\\\"]}\\n        assert \\\"component_as_tool\\\" not in output_names\\n\\n    def test_describe_required_field(self):\\n        info = describe_component(SAMPLE_REGISTRY, \\\"ChatOutput\\\")\\n        input_field = next(i for i in info[\\\"inputs\\\"] if i[\\\"name\\\"] == \\\"input_value\\\")\\n        assert input_field[\\\"required\\\"] is True\\n\\n\\n# ---------------------------------------------------------------------------\\n# LangflowClient \u2014 pure method tests (no network)\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestClientHeaders:\\n    def test_no_credentials(self):\\n        client = LangflowClient(server_url=\\\"http://test:7860\\\")\\n        client.api_key = None\\n        client.access_token = None\\n        headers = client._headers()\\n        assert headers == {\\\"Content-Type\\\": \\\"application/json\\\"}\\n        assert \\\"Authorization\\\" not in headers\\n        assert \\\"x-api-key\\\" not in headers\\n\\n    def test_api_key_only(self):\\n        client = LangflowClient(server_url=\\\"http://test:7860\\\", api_key=\\\"sk-test-key\\\")\\n        headers = client._headers()\\n        assert \\\"Authorization\\\" not in headers\\n        assert headers[\\\"x-api-key\\\"] == \\\"sk-test-key\\\"\\n\\n    def test_access_token_only(self):\\n        client = LangflowClient(server_url=\\\"http://test:7860\\\")\\n        token = \\\"jwt-token-123\\\"  # noqa: S105\\n        client.access_token = token\\n        headers = client._headers()\\n        assert headers[\\\"Authorization\\\"] == f\\\"Bearer {token}\\\"\\n        assert \\\"x-api-key\\\" not in headers\\n\\n    def test_both_token_and_api_key(self):\\n        \\\"\\\"\\\"access_token takes precedence for Bearer, api_key still sent as x-api-key.\\\"\\\"\\\"\\n        client = LangflowClient(server_url=\\\"http://test:7860\\\", api_key=\\\"sk-key\\\")\\n        token = \\\"jwt-token\\\"  # noqa: S105\\n        client.access_token = token\\n        headers = client._headers()\\n        assert headers[\\\"Authorization\\\"] == f\\\"Bearer {token}\\\"\\n        assert headers[\\\"x-api-key\\\"] == \\\"sk-key\\\"\\n\\n    def test_content_type_always_present(self):\\n        client = LangflowClient(server_url=\\\"http://test:7860\\\")\\n        headers = client._headers()\\n        assert headers[\\\"Content-Type\\\"] == \\\"application/json\\\"\\n\\n\\nclass TestClientUrl:\\n    def test_basic_path(self):\\n        client = LangflowClient(server_url=\\\"http://localhost:7860\\\")\\n        assert client._url(\\\"/flows/\\\") == \\\"http://localhost:7860/api/v1/flows/\\\"\\n\\n    def test_trailing_slash_stripped(self):\\n        client = LangflowClient(server_url=\\\"http://localhost:7860/\\\")\\n        assert client._url(\\\"/flows/\\\") == \\\"http://localhost:7860/api/v1/flows/\\\"\\n\\n    def test_nested_path(self):\\n        client = LangflowClient(server_url=\\\"http://host:8000\\\")\\n        assert client._url(\\\"/flows/abc-123\\\") == \\\"http://host:8000/api/v1/flows/abc-123\\\"\\n\\n    def test_default_server_url(self):\\n        client = LangflowClient()\\n        assert client._url(\\\"/test\\\") == f\\\"{client.server_url}/api/v1/test\\\"\\n\\n\\nclass TestClientInit:\\n    def test_default_values(self):\\n        client = LangflowClient()\\n        assert client.server_url.startswith(\\\"http\\\")\\n        assert client.access_token is None\\n\\n    def test_custom_server_url(self):\\n        client = LangflowClient(server_url=\\\"http://custom:9000\\\")\\n        assert client.server_url == \\\"http://custom:9000\\\"\\n\\n    def test_http_client_starts_none(self):\\n        client = LangflowClient()\\n        assert client._http is None\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/utils/test_migration.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"2ef47cc3f59ef027cdabeaca58b8079b2ebf6396922ce43b64baa24bebb47c2f\",\"content\":\"from unittest.mock import Mock, patch\\n\\nimport pytest\\nimport sqlalchemy as sa\\nfrom langflow.utils.migration import column_exists, constraint_exists, foreign_key_exists, table_exists\\n\\n\\nclass TestTableExists:\\n    \\\"\\\"\\\"Test cases for table_exists function.\\\"\\\"\\\"\\n\\n    @patch(\\\"sqlalchemy.inspect\\\")\\n    def test_table_exists_true(self, mock_inspect):\\n        \\\"\\\"\\\"Test when table exists.\\\"\\\"\\\"\\n        mock_inspector = Mock()\\n        mock_inspector.get_table_names.return_value = [\\\"users\\\", \\\"posts\\\", \\\"comments\\\"]\\n        mock_inspect.return_value = mock_inspector\\n\\n        mock_conn = Mock()\\n\\n        result = table_exists(\\\"users\\\", mock_conn)\\n\\n        assert result is True\\n        mock_inspect.assert_called_once_with(mock_conn)\\n        mock_inspector.get_table_names.assert_called_once()\\n\\n    @patch(\\\"sqlalchemy.inspect\\\")\\n    def test_table_exists_false(self, mock_inspect):\\n        \\\"\\\"\\\"Test when table does not exist.\\\"\\\"\\\"\\n        mock_inspector = Mock()\\n        mock_inspector.get_table_names.return_value = [\\\"users\\\", \\\"posts\\\", \\\"comments\\\"]\\n        mock_inspect.return_value = mock_inspector\\n\\n        mock_conn = Mock()\\n\\n        result = table_exists(\\\"nonexistent_table\\\", mock_conn)\\n\\n        assert result is False\\n        mock_inspect.assert_called_once_with(mock_conn)\\n        mock_inspector.get_table_names.assert_called_once()\\n\\n    @patch(\\\"sqlalchemy.inspect\\\")\\n    def test_table_exists_empty_database(self, mock_inspect):\\n        \\\"\\\"\\\"Test when database has no tables.\\\"\\\"\\\"\\n        mock_inspector = Mock()\\n        mock_inspector.get_table_names.return_value = []\\n        mock_inspect.return_value = mock_inspector\\n\\n        mock_conn = Mock()\\n\\n        result = table_exists(\\\"any_table\\\", mock_conn)\\n\\n        assert result is False\\n        mock_inspect.assert_called_once_with(mock_conn)\\n        mock_inspector.get_table_names.assert_called_once()\\n\\n    @patch(\\\"sqlalchemy.inspect\\\")\\n    def test_table_exists_case_sensitive(self, mock_inspect):\\n        \\\"\\\"\\\"Test case sensitivity of table name matching.\\\"\\\"\\\"\\n        mock_inspector = Mock()\\n        mock_inspector.get_table_names.return_value = [\\\"Users\\\", \\\"posts\\\"]\\n        mock_inspect.return_value = mock_inspector\\n\\n        mock_conn = Mock()\\n\\n        # Exact case match should work\\n        result = table_exists(\\\"Users\\\", mock_conn)\\n        assert result is True\\n\\n        # Different case should not match (depends on database implementation)\\n        result = table_exists(\\\"users\\\", mock_conn)\\n        assert result is False\\n\\n    @patch(\\\"sqlalchemy.inspect\\\")\\n    def test_table_exists_with_engine(self, mock_inspect):\\n        \\\"\\\"\\\"Test function works with both engine and connection objects.\\\"\\\"\\\"\\n        mock_inspector = Mock()\\n        mock_inspector.get_table_names.return_value = [\\\"test_table\\\"]\\n        mock_inspect.return_value = mock_inspector\\n\\n        mock_engine = Mock(spec=sa.engine.Engine)\\n\\n        result = table_exists(\\\"test_table\\\", mock_engine)\\n\\n        assert result is True\\n        mock_inspect.assert_called_once_with(mock_engine)\\n\\n\\nclass TestColumnExists:\\n    \\\"\\\"\\\"Test cases for column_exists function.\\\"\\\"\\\"\\n\\n    @patch(\\\"sqlalchemy.inspect\\\")\\n    def test_column_exists_true(self, mock_inspect):\\n        \\\"\\\"\\\"Test when column exists in table.\\\"\\\"\\\"\\n        mock_inspector = Mock()\\n        mock_inspector.get_columns.return_value = [\\n            {\\\"name\\\": \\\"id\\\", \\\"type\\\": \\\"INTEGER\\\"},\\n            {\\\"name\\\": \\\"username\\\", \\\"type\\\": \\\"VARCHAR\\\"},\\n            {\\\"name\\\": \\\"email\\\", \\\"type\\\": \\\"VARCHAR\\\"},\\n        ]\\n        mock_inspect.return_value = mock_inspector\\n\\n        mock_conn = Mock()\\n\\n        result = column_exists(\\\"users\\\", \\\"username\\\", mock_conn)\\n\\n        assert result is True\\n        mock_inspect.assert_called_once_with(mock_conn)\\n        mock_inspector.get_columns.assert_called_once_with(\\\"users\\\")\\n\\n    @patch(\\\"sqlalchemy.inspect\\\")\\n    def test_column_exists_false(self, mock_inspect):\\n        \\\"\\\"\\\"Test when column does not exist in table.\\\"\\\"\\\"\\n        mock_inspector = Mock()\\n        mock_inspector.get_columns.return_value = [\\n            {\\\"name\\\": \\\"id\\\", \\\"type\\\": \\\"INTEGER\\\"},\\n            {\\\"name\\\": \\\"username\\\", \\\"type\\\": \\\"VARCHAR\\\"},\\n            {\\\"name\\\": \\\"email\\\", \\\"type\\\": \\\"VARCHAR\\\"},\\n        ]\\n        mock_inspect.return_value = mock_inspector\\n\\n        mock_conn = Mock()\\n\\n        result = column_exists(\\\"users\\\", \\\"nonexistent_column\\\", mock_conn)\\n\\n        assert result is False\\n        mock_inspect.assert_called_once_with(mock_conn)\\n        mock_inspector.get_columns.assert_called_once_with(\\\"users\\\")\\n\\n    @patch(\\\"sqlalchemy.inspect\\\")\\n    def test_column_exists_empty_table(self, mock_inspect):\\n        \\\"\\\"\\\"Test when table has no columns.\\\"\\\"\\\"\\n        mock_inspector = Mock()\\n        mock_inspector.get_columns.return_value = []\\n        mock_inspect.return_value = mock_inspector\\n\\n        mock_conn = Mock()\\n\\n        result = column_exists(\\\"empty_table\\\", \\\"any_column\\\", mock_conn)\\n\\n        assert result is False\\n        mock_inspect.assert_called_once_with(mock_conn)\\n        mock_inspector.get_columns.assert_called_once_with(\\\"empty_table\\\")\\n\\n    @patch(\\\"sqlalchemy.inspect\\\")\\n    def test_column_exists_case_sensitive(self, mock_inspect):\\n        \\\"\\\"\\\"Test case sensitivity of column name matching.\\\"\\\"\\\"\\n        mock_inspector = Mock()\\n        mock_inspector.get_columns.return_value = [\\n            {\\\"name\\\": \\\"UserName\\\", \\\"type\\\": \\\"VARCHAR\\\"},\\n            {\\\"name\\\": \\\"email\\\", \\\"type\\\": \\\"VARCHAR\\\"},\\n        ]\\n        mock_inspect.return_value = mock_inspector\\n\\n        mock_conn = Mock()\\n\\n        # Exact case match should work\\n        result = column_exists(\\\"users\\\", \\\"UserName\\\", mock_conn)\\n        assert result is True\\n\\n        # Different case should not match\\n        result = column_exists(\\\"users\\\", \\\"username\\\", mock_conn)\\n        assert result is False\\n\\n    @patch(\\\"sqlalchemy.inspect\\\")\\n    def test_column_exists_multiple_calls(self, mock_inspect):\\n        \\\"\\\"\\\"Test multiple column existence checks on same table.\\\"\\\"\\\"\\n        mock_inspector = Mock()\\n        mock_inspector.get_columns.return_value = [\\n            {\\\"name\\\": \\\"id\\\", \\\"type\\\": \\\"INTEGER\\\"},\\n            {\\\"name\\\": \\\"name\\\", \\\"type\\\": \\\"VARCHAR\\\"},\\n            {\\\"name\\\": \\\"created_at\\\", \\\"type\\\": \\\"TIMESTAMP\\\"},\\n        ]\\n        mock_inspect.return_value = mock_inspector\\n\\n        mock_conn = Mock()\\n\\n        # Multiple checks should all work\\n        assert column_exists(\\\"posts\\\", \\\"id\\\", mock_conn) is True\\n        assert column_exists(\\\"posts\\\", \\\"name\\\", mock_conn) is True\\n        assert column_exists(\\\"posts\\\", \\\"created_at\\\", mock_conn) is True\\n        assert column_exists(\\\"posts\\\", \\\"updated_at\\\", mock_conn) is False\\n\\n        # Inspector should be called for each check\\n        assert mock_inspect.call_count == 4\\n        assert mock_inspector.get_columns.call_count == 4\\n\\n\\nclass TestForeignKeyExists:\\n    \\\"\\\"\\\"Test cases for foreign_key_exists function.\\\"\\\"\\\"\\n\\n    @patch(\\\"sqlalchemy.inspect\\\")\\n    def test_foreign_key_exists_true(self, mock_inspect):\\n        \\\"\\\"\\\"Test when foreign key exists.\\\"\\\"\\\"\\n        mock_inspector = Mock()\\n        mock_inspector.get_foreign_keys.return_value = [\\n            {\\\"name\\\": \\\"fk_user_id\\\", \\\"constrained_columns\\\": [\\\"user_id\\\"]},\\n            {\\\"name\\\": \\\"fk_category_id\\\", \\\"constrained_columns\\\": [\\\"category_id\\\"]},\\n            {\\\"name\\\": \\\"fk_author_id\\\", \\\"constrained_columns\\\": [\\\"author_id\\\"]},\\n        ]\\n        mock_inspect.return_value = mock_inspector\\n\\n        mock_conn = Mock()\\n\\n        result = foreign_key_exists(\\\"posts\\\", \\\"fk_user_id\\\", mock_conn)\\n\\n        assert result is True\\n        mock_inspect.assert_called_once_with(mock_conn)\\n        mock_inspector.get_foreign_keys.assert_called_once_with(\\\"posts\\\")\\n\\n    @patch(\\\"sqlalchemy.inspect\\\")\\n    def test_foreign_key_exists_false(self, mock_inspect):\\n        \\\"\\\"\\\"Test when foreign key does not exist.\\\"\\\"\\\"\\n        mock_inspector = Mock()\\n        mock_inspector.get_foreign_keys.return_value = [\\n            {\\\"name\\\": \\\"fk_user_id\\\", \\\"constrained_columns\\\": [\\\"user_id\\\"]},\\n            {\\\"name\\\": \\\"fk_category_id\\\", \\\"constrained_columns\\\": [\\\"category_id\\\"]},\\n        ]\\n        mock_inspect.return_value = mock_inspector\\n\\n        mock_conn = Mock()\\n\\n        result = foreign_key_exists(\\\"posts\\\", \\\"fk_nonexistent\\\", mock_conn)\\n\\n        assert result is False\\n        mock_inspect.assert_called_once_with(mock_conn)\\n        mock_inspector.get_foreign_keys.assert_called_once_with(\\\"posts\\\")\\n\\n    @patch(\\\"sqlalchemy.inspect\\\")\\n    def test_foreign_key_exists_no_foreign_keys(self, mock_inspect):\\n        \\\"\\\"\\\"Test when table has no foreign keys.\\\"\\\"\\\"\\n        mock_inspector = Mock()\\n        mock_inspector.get_foreign_keys.return_value = []\\n        mock_inspect.return_value = mock_inspector\\n\\n        mock_conn = Mock()\\n\\n        result = foreign_key_exists(\\\"simple_table\\\", \\\"any_fk\\\", mock_conn)\\n\\n        assert result is False\\n        mock_inspect.assert_called_once_with(mock_conn)\\n        mock_inspector.get_foreign_keys.assert_called_once_with(\\\"simple_table\\\")\\n\\n    @patch(\\\"sqlalchemy.inspect\\\")\\n    def test_foreign_key_exists_none_names(self, mock_inspect):\\n        \\\"\\\"\\\"Test when foreign keys have None names.\\\"\\\"\\\"\\n        mock_inspector = Mock()\\n        mock_inspector.get_foreign_keys.return_value = [\\n            {\\\"name\\\": None, \\\"constrained_columns\\\": [\\\"user_id\\\"]},\\n            {\\\"name\\\": \\\"fk_valid\\\", \\\"constrained_columns\\\": [\\\"category_id\\\"]},\\n        ]\\n        mock_inspect.return_value = mock_inspector\\n\\n        mock_conn = Mock()\\n\\n        result = foreign_key_exists(\\\"posts\\\", \\\"fk_valid\\\", mock_conn)\\n        assert result is True\\n\\n        # Should handle None names gracefully\\n        result = foreign_key_exists(\\\"posts\\\", None, mock_conn)\\n        assert result is True  # None should match None\\n\\n    @patch(\\\"sqlalchemy.inspect\\\")\\n    def test_foreign_key_exists_case_sensitive(self, mock_inspect):\\n        \\\"\\\"\\\"Test case sensitivity of foreign key name matching.\\\"\\\"\\\"\\n        mock_inspector = Mock()\\n        mock_inspector.get_foreign_keys.return_value = [{\\\"name\\\": \\\"FK_User_ID\\\", \\\"constrained_columns\\\": [\\\"user_id\\\"]}]\\n        mock_inspect.return_value = mock_inspector\\n\\n        mock_conn = Mock()\\n\\n        # Exact case match should work\\n        result = foreign_key_exists(\\\"posts\\\", \\\"FK_User_ID\\\", mock_conn)\\n        assert result is True\\n\\n        # Different case should not match\\n        result = foreign_key_exists(\\\"posts\\\", \\\"fk_user_id\\\", mock_conn)\\n        assert result is False\\n\\n\\nclass TestConstraintExists:\\n    \\\"\\\"\\\"Test cases for constraint_exists function.\\\"\\\"\\\"\\n\\n    @patch(\\\"sqlalchemy.inspect\\\")\\n    def test_constraint_exists_true(self, mock_inspect):\\n        \\\"\\\"\\\"Test when constraint exists.\\\"\\\"\\\"\\n        mock_inspector = Mock()\\n        mock_inspector.get_unique_constraints.return_value = [\\n            {\\\"name\\\": \\\"uq_username\\\", \\\"column_names\\\": [\\\"username\\\"]},\\n            {\\\"name\\\": \\\"uq_email\\\", \\\"column_names\\\": [\\\"email\\\"]},\\n            {\\\"name\\\": \\\"uq_composite\\\", \\\"column_names\\\": [\\\"first_name\\\", \\\"last_name\\\"]},\\n        ]\\n        mock_inspect.return_value = mock_inspector\\n\\n        mock_conn = Mock()\\n\\n        result = constraint_exists(\\\"users\\\", \\\"uq_username\\\", mock_conn)\\n\\n        assert result is True\\n        mock_inspect.assert_called_once_with(mock_conn)\\n        mock_inspector.get_unique_constraints.assert_called_once_with(\\\"users\\\")\\n\\n    @patch(\\\"sqlalchemy.inspect\\\")\\n    def test_constraint_exists_false(self, mock_inspect):\\n        \\\"\\\"\\\"Test when constraint does not exist.\\\"\\\"\\\"\\n        mock_inspector = Mock()\\n        mock_inspector.get_unique_constraints.return_value = [\\n            {\\\"name\\\": \\\"uq_username\\\", \\\"column_names\\\": [\\\"username\\\"]},\\n            {\\\"name\\\": \\\"uq_email\\\", \\\"column_names\\\": [\\\"email\\\"]},\\n        ]\\n        mock_inspect.return_value = mock_inspector\\n\\n        mock_conn = Mock()\\n\\n        result = constraint_exists(\\\"users\\\", \\\"uq_nonexistent\\\", mock_conn)\\n\\n        assert result is False\\n        mock_inspect.assert_called_once_with(mock_conn)\\n        mock_inspector.get_unique_constraints.assert_called_once_with(\\\"users\\\")\\n\\n    @patch(\\\"sqlalchemy.inspect\\\")\\n    def test_constraint_exists_no_constraints(self, mock_inspect):\\n        \\\"\\\"\\\"Test when table has no unique constraints.\\\"\\\"\\\"\\n        mock_inspector = Mock()\\n        mock_inspector.get_unique_constraints.return_value = []\\n        mock_inspect.return_value = mock_inspector\\n\\n        mock_conn = Mock()\\n\\n        result = constraint_exists(\\\"simple_table\\\", \\\"any_constraint\\\", mock_conn)\\n\\n        assert result is False\\n        mock_inspect.assert_called_once_with(mock_conn)\\n        mock_inspector.get_unique_constraints.assert_called_once_with(\\\"simple_table\\\")\\n\\n    @patch(\\\"sqlalchemy.inspect\\\")\\n    def test_constraint_exists_none_names(self, mock_inspect):\\n        \\\"\\\"\\\"Test when constraints have None names.\\\"\\\"\\\"\\n        mock_inspector = Mock()\\n        mock_inspector.get_unique_constraints.return_value = [\\n            {\\\"name\\\": None, \\\"column_names\\\": [\\\"id\\\"]},\\n            {\\\"name\\\": \\\"uq_valid\\\", \\\"column_names\\\": [\\\"username\\\"]},\\n        ]\\n        mock_inspect.return_value = mock_inspector\\n\\n        mock_conn = Mock()\\n\\n        result = constraint_exists(\\\"users\\\", \\\"uq_valid\\\", mock_conn)\\n        assert result is True\\n\\n        # Should handle None names gracefully\\n        result = constraint_exists(\\\"users\\\", None, mock_conn)\\n        assert result is True  # None should match None\\n\\n    @patch(\\\"sqlalchemy.inspect\\\")\\n    def test_constraint_exists_case_sensitive(self, mock_inspect):\\n        \\\"\\\"\\\"Test case sensitivity of constraint name matching.\\\"\\\"\\\"\\n        mock_inspector = Mock()\\n        mock_inspector.get_unique_constraints.return_value = [{\\\"name\\\": \\\"UQ_Username\\\", \\\"column_names\\\": [\\\"username\\\"]}]\\n        mock_inspect.return_value = mock_inspector\\n\\n        mock_conn = Mock()\\n\\n        # Exact case match should work\\n        result = constraint_exists(\\\"users\\\", \\\"UQ_Username\\\", mock_conn)\\n        assert result is True\\n\\n        # Different case should not match\\n        result = constraint_exists(\\\"users\\\", \\\"uq_username\\\", mock_conn)\\n        assert result is False\\n\\n    @patch(\\\"sqlalchemy.inspect\\\")\\n    def test_constraint_exists_multiple_constraints(self, mock_inspect):\\n        \\\"\\\"\\\"Test with multiple unique constraints.\\\"\\\"\\\"\\n        mock_inspector = Mock()\\n        mock_inspector.get_unique_constraints.return_value = [\\n            {\\\"name\\\": \\\"uq_single_column\\\", \\\"column_names\\\": [\\\"email\\\"]},\\n            {\\\"name\\\": \\\"uq_composite\\\", \\\"column_names\\\": [\\\"first_name\\\", \\\"last_name\\\", \\\"birth_date\\\"]},\\n            {\\\"name\\\": \\\"uq_another\\\", \\\"column_names\\\": [\\\"phone_number\\\"]},\\n        ]\\n        mock_inspect.return_value = mock_inspector\\n\\n        mock_conn = Mock()\\n\\n        # All existing constraints should be found\\n        assert constraint_exists(\\\"users\\\", \\\"uq_single_column\\\", mock_conn) is True\\n        assert constraint_exists(\\\"users\\\", \\\"uq_composite\\\", mock_conn) is True\\n        assert constraint_exists(\\\"users\\\", \\\"uq_another\\\", mock_conn) is True\\n\\n        # Non-existing constraint should return False\\n        assert constraint_exists(\\\"users\\\", \\\"uq_missing\\\", mock_conn) is False\\n\\n\\nclass TestIntegrationScenarios:\\n    \\\"\\\"\\\"Integration test scenarios for migration utilities.\\\"\\\"\\\"\\n\\n    @patch(\\\"sqlalchemy.inspect\\\")\\n    def test_complete_migration_check_workflow(self, mock_inspect):\\n        \\\"\\\"\\\"Test a complete migration check workflow.\\\"\\\"\\\"\\n        mock_inspector = Mock()\\n\\n        # Setup mock responses for different calls\\n        def get_table_names_side_effect():\\n            return [\\\"users\\\", \\\"posts\\\", \\\"comments\\\", \\\"categories\\\"]\\n\\n        def get_columns_side_effect(table_name):\\n            columns_map = {\\n                \\\"users\\\": [\\n                    {\\\"name\\\": \\\"id\\\", \\\"type\\\": \\\"INTEGER\\\"},\\n                    {\\\"name\\\": \\\"username\\\", \\\"type\\\": \\\"VARCHAR\\\"},\\n                    {\\\"name\\\": \\\"email\\\", \\\"type\\\": \\\"VARCHAR\\\"},\\n                    {\\\"name\\\": \\\"created_at\\\", \\\"type\\\": \\\"TIMESTAMP\\\"},\\n                ],\\n                \\\"posts\\\": [\\n                    {\\\"name\\\": \\\"id\\\", \\\"type\\\": \\\"INTEGER\\\"},\\n                    {\\\"name\\\": \\\"title\\\", \\\"type\\\": \\\"VARCHAR\\\"},\\n                    {\\\"name\\\": \\\"content\\\", \\\"type\\\": \\\"TEXT\\\"},\\n                    {\\\"name\\\": \\\"user_id\\\", \\\"type\\\": \\\"INTEGER\\\"},\\n                ],\\n            }\\n            return columns_map.get(table_name, [])\\n\\n        def get_foreign_keys_side_effect(table_name):\\n            fk_map = {\\\"posts\\\": [{\\\"name\\\": \\\"fk_posts_user_id\\\", \\\"constrained_columns\\\": [\\\"user_id\\\"]}]}\\n            return fk_map.get(table_name, [])\\n\\n        def get_unique_constraints_side_effect(table_name):\\n            constraint_map = {\\n                \\\"users\\\": [\\n                    {\\\"name\\\": \\\"uq_users_username\\\", \\\"column_names\\\": [\\\"username\\\"]},\\n                    {\\\"name\\\": \\\"uq_users_email\\\", \\\"column_names\\\": [\\\"email\\\"]},\\n                ]\\n            }\\n            return constraint_map.get(table_name, [])\\n\\n        mock_inspector.get_table_names.side_effect = get_table_names_side_effect\\n        mock_inspector.get_columns.side_effect = get_columns_side_effect\\n        mock_inspector.get_foreign_keys.side_effect = get_foreign_keys_side_effect\\n        mock_inspector.get_unique_constraints.side_effect = get_unique_constraints_side_effect\\n        mock_inspect.return_value = mock_inspector\\n\\n        mock_conn = Mock()\\n\\n        # Test complete migration check scenario\\n        # Check if tables exist\\n        assert table_exists(\\\"users\\\", mock_conn) is True\\n        assert table_exists(\\\"posts\\\", mock_conn) is True\\n        assert table_exists(\\\"nonexistent_table\\\", mock_conn) is False\\n\\n        # Check if required columns exist\\n        assert column_exists(\\\"users\\\", \\\"username\\\", mock_conn) is True\\n        assert column_exists(\\\"users\\\", \\\"email\\\", mock_conn) is True\\n        assert column_exists(\\\"posts\\\", \\\"user_id\\\", mock_conn) is True\\n        assert column_exists(\\\"posts\\\", \\\"nonexistent_column\\\", mock_conn) is False\\n\\n        # Check if foreign keys exist\\n        assert foreign_key_exists(\\\"posts\\\", \\\"fk_posts_user_id\\\", mock_conn) is True\\n        assert foreign_key_exists(\\\"posts\\\", \\\"nonexistent_fk\\\", mock_conn) is False\\n\\n        # Check if constraints exist\\n        assert constraint_exists(\\\"users\\\", \\\"uq_users_username\\\", mock_conn) is True\\n        assert constraint_exists(\\\"users\\\", \\\"uq_users_email\\\", mock_conn) is True\\n        assert constraint_exists(\\\"users\\\", \\\"nonexistent_constraint\\\", mock_conn) is False\\n\\n    @patch(\\\"sqlalchemy.inspect\\\")\\n    def test_error_handling_in_inspection(self, mock_inspect):\\n        \\\"\\\"\\\"Test error handling when SQLAlchemy inspection fails.\\\"\\\"\\\"\\n        mock_inspector = Mock()\\n        mock_inspector.get_table_names.side_effect = Exception(\\\"Database connection error\\\")\\n        mock_inspect.return_value = mock_inspector\\n\\n        mock_conn = Mock()\\n\\n        # Should propagate the exception\\n        with pytest.raises(Exception, match=\\\"Database connection error\\\"):\\n            table_exists(\\\"any_table\\\", mock_conn)\\n\\n    @patch(\\\"sqlalchemy.inspect\\\")\\n    def test_with_different_connection_types(self, mock_inspect):\\n        \\\"\\\"\\\"Test functions work with different SQLAlchemy connection types.\\\"\\\"\\\"\\n        mock_inspector = Mock()\\n        mock_inspector.get_table_names.return_value = [\\\"test_table\\\"]\\n        mock_inspect.return_value = mock_inspector\\n\\n        # Test with mock engine\\n        mock_engine = Mock(spec=sa.engine.Engine)\\n        result = table_exists(\\\"test_table\\\", mock_engine)\\n        assert result is True\\n\\n        # Test with mock connection\\n        mock_connection = Mock(spec=sa.engine.Connection)\\n        result = table_exists(\\\"test_table\\\", mock_connection)\\n        assert result is True\\n\\n        # Verify inspect was called with the connection objects\\n        assert mock_inspect.call_count == 2\\n        mock_inspect.assert_any_call(mock_engine)\\n        mock_inspect.assert_any_call(mock_connection)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/utils/test_mustache_security.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"5f3ae8d6d5568b4965307974f7976df906dde339073b43dabf00d21b4b85e209\",\"content\":\"\\\"\\\"\\\"Tests for mustache security utilities.\\\"\\\"\\\"\\n\\nimport pytest\\nfrom langflow.utils.mustache_security import safe_mustache_render, validate_mustache_template\\n\\n\\nclass TestMustacheSecurity:\\n    \\\"\\\"\\\"Test mustache security functions.\\\"\\\"\\\"\\n\\n    def test_validate_accepts_simple_variables(self):\\n        \\\"\\\"\\\"Test that simple variables are accepted.\\\"\\\"\\\"\\n        # Should not raise\\n        validate_mustache_template(\\\"Hello {{name}}!\\\")\\n        validate_mustache_template(\\\"{{user_name}} - {{user_email}}\\\")\\n        validate_mustache_template(\\\"Price: {{price_100}}\\\")\\n        validate_mustache_template(\\\"\\\")\\n        validate_mustache_template(\\\"No variables here\\\")\\n\\n    def test_validate_rejects_complex_syntax(self):\\n        \\\"\\\"\\\"Test that complex mustache syntax is rejected.\\\"\\\"\\\"\\n        # Conditionals\\n        with pytest.raises(ValueError, match=\\\"Complex mustache syntax is not allowed\\\"):\\n            validate_mustache_template(\\\"{{#if}}content{{/if}}\\\")\\n\\n        # Inverted sections\\n        with pytest.raises(ValueError, match=\\\"Complex mustache syntax is not allowed\\\"):\\n            validate_mustache_template(\\\"{{^empty}}not empty{{/empty}}\\\")\\n\\n        # Unescaped\\n        with pytest.raises(ValueError, match=\\\"Complex mustache syntax is not allowed\\\"):\\n            validate_mustache_template(\\\"{{&html}}\\\")\\n\\n        # Partials\\n        with pytest.raises(ValueError, match=\\\"Complex mustache syntax is not allowed\\\"):\\n            validate_mustache_template(\\\"{{>header}}\\\")\\n\\n        # Comments\\n        with pytest.raises(ValueError, match=\\\"Complex mustache syntax is not allowed\\\"):\\n            validate_mustache_template(\\\"{{!comment}}\\\")\\n\\n        # Current context\\n        with pytest.raises(ValueError, match=\\\"Complex mustache syntax is not allowed\\\"):\\n            validate_mustache_template(\\\"{{.}}\\\")\\n\\n    def test_validate_rejects_invalid_variable_names(self):\\n        \\\"\\\"\\\"Test that invalid variable names are rejected.\\\"\\\"\\\"\\n        # Spaces in variable names\\n        with pytest.raises(ValueError, match=\\\"Invalid mustache variable\\\"):\\n            validate_mustache_template(\\\"{{ name with spaces }}\\\")\\n\\n        # Starting with numbers\\n        with pytest.raises(ValueError, match=\\\"Invalid mustache variable\\\"):\\n            validate_mustache_template(\\\"{{123invalid}}\\\")\\n\\n        # Special characters\\n        with pytest.raises(ValueError, match=\\\"Invalid mustache variable\\\"):\\n            validate_mustache_template(\\\"{{price-$100}}\\\")\\n\\n        # Empty variables\\n        with pytest.raises(ValueError, match=\\\"Invalid mustache variable\\\"):\\n            validate_mustache_template(\\\"{{}}\\\")\\n\\n        # Dot notation (not supported)\\n        with pytest.raises(ValueError, match=\\\"Invalid mustache variable\\\"):\\n            validate_mustache_template(\\\"{{user.name}}\\\")\\n\\n    def test_safe_render_simple_variables(self):\\n        \\\"\\\"\\\"Test safe rendering of simple variables.\\\"\\\"\\\"\\n        template = \\\"Hello {{name}}! You are {{age}} years old.\\\"\\n        variables = {\\\"name\\\": \\\"Alice\\\", \\\"age\\\": 25}\\n        result = safe_mustache_render(template, variables)\\n        assert result == \\\"Hello Alice! You are 25 years old.\\\"\\n\\n    def test_safe_render_missing_variables(self):\\n        \\\"\\\"\\\"Test rendering with missing variables.\\\"\\\"\\\"\\n        template = \\\"Hello {{name}}! Your score is {{score}}.\\\"\\n        variables = {\\\"name\\\": \\\"Charlie\\\"}\\n        result = safe_mustache_render(template, variables)\\n        assert result == \\\"Hello Charlie! Your score is .\\\"\\n\\n    def test_safe_render_none_values(self):\\n        \\\"\\\"\\\"Test rendering with None values.\\\"\\\"\\\"\\n        template = \\\"Name: {{name}}, Age: {{age}}\\\"\\n        variables = {\\\"name\\\": None, \\\"age\\\": None}\\n        result = safe_mustache_render(template, variables)\\n        assert result == \\\"Name: , Age: \\\"\\n\\n    def test_safe_render_numeric_values(self):\\n        \\\"\\\"\\\"Test rendering with numeric values.\\\"\\\"\\\"\\n        template = \\\"Price: ${{price}}, Quantity: {{qty}}\\\"\\n        variables = {\\\"price\\\": 19.99, \\\"qty\\\": 3}\\n        result = safe_mustache_render(template, variables)\\n        assert result == \\\"Price: $19.99, Quantity: 3\\\"\\n\\n    def test_safe_render_rejects_complex_syntax(self):\\n        \\\"\\\"\\\"Test that safe_render rejects complex syntax.\\\"\\\"\\\"\\n        with pytest.raises(ValueError, match=\\\"Complex mustache syntax is not allowed\\\"):\\n            safe_mustache_render(\\\"{{#if}}test{{/if}}\\\", {\\\"if\\\": True})\\n\\n    def test_safe_render_multiple_variables(self):\\n        \\\"\\\"\\\"Test rendering with multiple variables.\\\"\\\"\\\"\\n        template = \\\"{{greeting}} {{name}}, welcome to {{place}}!\\\"\\n        variables = {\\\"greeting\\\": \\\"Hello\\\", \\\"name\\\": \\\"Alice\\\", \\\"place\\\": \\\"Langflow\\\"}\\n        result = safe_mustache_render(template, variables)\\n        assert result == \\\"Hello Alice, welcome to Langflow!\\\"\\n\\n    def test_safe_render_underscore_variables(self):\\n        \\\"\\\"\\\"Test rendering with underscore variable names.\\\"\\\"\\\"\\n        template = \\\"Private: {{_private_var}}, Public: {{public_var}}\\\"\\n        variables = {\\\"_private_var\\\": \\\"secret\\\", \\\"public_var\\\": \\\"visible\\\"}\\n        result = safe_mustache_render(template, variables)\\n        assert result == \\\"Private: secret, Public: visible\\\"\\n\\n    def test_safe_render_empty_string_values(self):\\n        \\\"\\\"\\\"Test rendering with empty string values.\\\"\\\"\\\"\\n        template = \\\"Start{{middle}}End\\\"\\n        variables = {\\\"middle\\\": \\\"\\\"}\\n        result = safe_mustache_render(template, variables)\\n        assert result == \\\"StartEnd\\\"\\n\"}]}";
